/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkSitemapProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 898 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkSitemapProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));
	
	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		if (m_OpInfo.strReturn == L"SETTLEMENT")
		{
			m_OpInfo.nProcNextScrNum = 903;
			break;
		}
		else if (m_OpInfo.strReturn == L"JOURNAL")
		{
			m_OpInfo.nProcNextScrNum = 921;
			break;
		}
		else if (m_OpInfo.strReturn == L"REPORT")
		{
			m_OpInfo.nProcNextScrNum = 931;
			break;
		}
		else if (m_OpInfo.strReturn == L"DIAGNOSTICS")
		{
			CString	strTemp;

			if (ClerkConfirm(L"901F7S", strTemp) == TRUE)
			{
				// [#2325] NH KSK 2015.01.25 VDM 진입함수 공용화 적용 (SiteMap 누락사항 적용 
				ClerkEnterDiagnostics();

				m_OpInfo.nProcNextScrNum = 821;
				break;
			}
			else	// KSK 2011.05.13 SITE MAP에서 CANCEL시 OP MAIN으로 가도록 수정
			{
				m_OpInfo.nProcNextScrNum = 901;
				break;
			}		// end of KSK 2011.05.13
		}
		else if (m_OpInfo.strReturn == L"CUSTOMER")
		{
			m_OpInfo.nProcNextScrNum = 941;				
			break;
		}
		else if (m_OpInfo.strReturn == L"SYSTEM")
		{
			m_OpInfo.nProcNextScrNum = 951;
			break;
		}
		else if (m_OpInfo.strReturn == L"HOST")
		{
			m_OpInfo.nProcNextScrNum = 961;
			break;
		}
		else if (m_OpInfo.strReturn == L"TRANSACTION")
		{
			m_OpInfo.nProcNextScrNum = 981;				
			break;
		}		

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 901;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} 

	NHDEBUG(DBG_CALL, (L"END\n"));
}

