	m_pDevCmn->fnSCR_DisplayPrevSet(899);
	m_pDevCmn->fnSCR_DisplayString(1, m_pDevCmn->fstrSCR_GetStringFromTextID(T_OPMSG_899001));
	m_pDevCmn->fnSCR_DisplayScreen(899);
	
