/*-------------------------------------------------------------------
CLASS    NAME: CMainFrame
FUNCTION NAME: ClerkTranAdvertisement1Proc()
RETURN TYPE  : 
PARAMETER    : 
DESCRIPTION  : SCR 862 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkTranAdvertisement1Proc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F1
		// [#2166] NH KSK 2012.12.17
// 		if ((m_OpInfo.strTempArray.GetSize() >= 2) && (m_OpInfo.strTempArray[0] == L"ADVERTISEMENT"))
// 		{
// 			MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_TRAN_ADV_ENDISFLAG1, m_OpInfo.strTempArray[1] == L"ENABLE" ? 1 : 0);
// 		}
		if (m_OpInfo.strReturn == L"ADVERTISEMENT")
		{
			if (MemGetInt(_MEM_FLD_ADVINFO, _MEM_VAR_TRAN_ADV_ENDISFLAG1) == ENABLE)
				MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_TRAN_ADV_ENDISFLAG1, 0);
			else
				MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_TRAN_ADV_ENDISFLAG1, ENABLE);
		}
		// end of [#2166]
		else if (m_OpInfo.strReturn == L"DELETE")
		{
			CString strAdFile;

			// KSK 2011.05.16 후면기에서 광고가 Delete 되지 않는 Bug Fix
//			strAdFile.Format(_T("%s\\%d_%d\\TranADV_01.jpg"), ADVERTISEMENT_PATH, GetSystemMetrics(SM_CXSCREEN), GetSystemMetrics(SM_CYSCREEN));
			NH_SCR_CONFIG eFrontConfig = m_pDevCmn->m_pConfig->GetScreenConfig(SCR_FRONT);
			strAdFile.Format(L"%s\\%d_%d\\TranADV_01.jpg", ADVERTISEMENT_PATH, eFrontConfig.nWidth, eFrontConfig.nHeight);
			// end of KSK 2011.05.16

			// 파일을 찾지 못하면 에러메시지 표시하고 종료함.
			CCeFileFind	fFinder;
			if( fFinder.FindFile(strAdFile) == FALSE )
			{
				ClerkNoticeToUser(T_FAIL_FIND);
			}
			else
			{
				if (ClerkConfirm(L"862F2S", m_OpInfo.strReturn) == TRUE)
				{
					// [#2110] NH KSK 2011.12.22 File Delete시에 Read Only File을 삭제하지 못하는 Bug Fix (Read Only->Read/Write로 변경)
					SetFileAttributes(strAdFile, FILE_ATTRIBUTE_NORMAL);
					// end of [#2110]

					if( DeleteFile(strAdFile) == 0 )			// FAIL
						ClerkNoticeToUser(T_FAIL_DELETE);
					else
						ClerkNoticeToUser(T_OPERATE_OK);
				}
			}
			fFinder.Close();
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 868;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
}

