// [#2150] US Justin 2012.10.08 Add ClerkStandard1ExtenedProc 
/*-------------------------------------------------------------------
CLASS    NAME: CMainFrame
FUNCTION NAME: ClerkStandard1ExtenedProc()
RETURN TYPE  : 
PARAMETER    : 
DESCRIPTION  : SCR 994 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkStandard1ExtenedProc()
{
	NHDEBUG(1, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// [#2166] NH KSK 2012.12.17
// 		if (m_OpInfo.strTempArray[0] == L"DYNAMICFLOW")	
// 		{
// 			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_ENABLE, m_OpInfo.strTempArray[1] == L"ENABLE" ? 1 : 0);
// 		}
		if (m_OpInfo.strReturn == L"DYNAMICFLOW")	
		{
			// [#2499] US Jutin 2017.08.21 Open Dual Host DCC for US Customers.
			/*
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_ENABLE) == ENABLE)
			{
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_ENABLE, 0);
				// [#2240] NH Justin 
				if(MemGetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE) != 1)
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE, 0);
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_DCC, 0);
				// End of [#2240]
			}
			else
			{
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_ENABLE, ENABLE);
			}
			*/
			#if (US_VERSION)
				int nNewSetting =  MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_ENABLE) + 1;

				if( nNewSetting > DYNAMICFLOW_DUALHOST)
					nNewSetting = DYNAMICFLOW_DISABLE;

				// Dual Host is possible if non 512K EPP is used or Dial Up Mode is used.
				if( (nNewSetting == DYNAMICFLOW_DUALHOST) &&
					( (MemGetVersion(_MEMKEY_EPVERSION, L"PIN").CompareNoCase(PIN_512K_EP_VERSION)<0) || (MemGetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_NETWORKTYPE) == NETWORK_DIALUP) ) )
					nNewSetting = DYNAMICFLOW_DISABLE;

				if(nNewSetting == DYNAMICFLOW_ENABLE)
				{
					MemSetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DUALHOSTDCC_ENABLE, 0);			// Disable Dual Host DCC
				}
				else if(nNewSetting == DYNAMICFLOW_DUALHOST)
				{
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_DCC, 0);					// Disable STD1 DF DCC
					if(MemGetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE) == 2)		// Disable PIN Change if it was "HOST DETERMINE"
						MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE, 0);
				}
				else if(nNewSetting == DYNAMICFLOW_DISABLE)
				{
					MemSetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DUALHOSTDCC_ENABLE, 0);			// Disable Dual Host DCC
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_DCC, 0);					// Disable STD1 DF DCC
					if(MemGetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE) == 2)		// Disable PIN Change if it was "HOST DETERMINE"
						MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE, 0);

#if (APP_CUSTOM_PAI)
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DCCLOOKUP_LOCALSURCHARGE, ENABLE);
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_DCC, ENABLE); // Host det.
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_1STCALL_OPTION, DYNAMICFLOW_1STCALL_OFF); // 1st call disabled
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DYNAMICFLOW_DCC_TYPE, DYNAMICFLOW_DCC_TYPE_BOTH);
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DCC_CUSTOMOPTION, DCC_CUSTOMOPTION_PLANET);
#endif
				}

				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_ENABLE, nNewSetting);
			#else
				MemSetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DUALHOSTDCC_ENABLE, 0);		// Disable Dual Host DCC

				if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_ENABLE) == ENABLE)
				{
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_ENABLE, 0);
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_DCC, 0);
					if(MemGetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE) == 2)		// HOST DETERMINE
						MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE, 0);
				}
				else
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_ENABLE, ENABLE);
			#endif
			// End of [#2499]
		}
		// [#2240] NH Justin 2013.12.17 DF 1st call option
		else if (m_OpInfo.strTempArray[0] == L"DF1STCALLOPTION")	
		{
			int nOpt = MemGetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_1STCALL_OPTION) + 1;
			if( nOpt>1 )	nOpt=0;
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_1STCALL_OPTION, nOpt);
			if(nOpt==DYNAMICFLOW_1STCALL_OFF)
			{
				if(MemGetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE) == 2)		// HOST DETERMINE
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE, 0);
			}
		}
		// End of [#2240]
		// end of [#2166]
		else if (m_OpInfo.strTempArray[0] == L"PINCHANGE")			// NOT WORKING <=== BUTTON IS DISABLED
		{
			int nOpt = MemGetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE) + 1;
			if( nOpt>2 )	nOpt=0;
			// [#2240] NH Justin 2013.12.17 DF 1st call option
			if( nOpt==2 )		// Host Determine
			{
				if( (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_ENABLE) != ENABLE) || 
					(MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_1STCALL_OPTION) != DYNAMICFLOW_1STCALL_ON) )
				nOpt=0;
			}
			// End of [#2240]
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_PINCHANGE, nOpt);
		}
		else if (m_OpInfo.strReturn == L"CURRCENCYCONVERSION")
		{
			int nOpt =	MemGetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_DCC) + 1;
			if(nOpt>1)	nOpt=0;
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_SERVICE_DCC, nOpt);
		}
		// [#2187] US Justin 2013.04.17 DCC Custom option
		else if (m_OpInfo.strReturn == L"DCCCUSTOMOPTION")
		{
			m_OpInfo.nProcNextScrNum = 794;
			break;
		}		
		// End of [#2187]
		// [#2490] NH Justin 2017.06.14 Standard1 Dynamic Flow MAC Option
		else if (m_OpInfo.strTempArray[0] == L"DYNAMICFLOWMAC")	
		{
			int nOpt = MemGetInt( _MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_STD1_DYNAMICFLOW_MAC ) + 1;
			if( nOpt > 2 )	nOpt=1;
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_STD1_DYNAMICFLOW_MAC, nOpt);
		}
		// End of [#2490]
		// [#2499] US Justin 2017.08.21 Enable Dual Host for all US Custtomers
		else if (m_OpInfo.strTempArray[0] == L"DUALHOSTDCC")	
		{
			m_OpInfo.nProcNextScrNum = 791;
			break;
		}
		// End of [#2499]

		// [#2360] NH KSK 2015.12.23 주석처리
		/*
		else if (m_OpInfo.strReturn == L"DISCLAIMER")
		{
			CString strValue;
			strValue.Format(L"%s\n%s\n%s", MemGetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER1),
										   MemGetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER2),
										   MemGetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER3));

			if (ClerkInputAlpha(L"994F6T", strValue, 3, 40, m_OpInfo.strReturn) == TRUE)
			{
				SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

				if (m_OpInfo.strTempArray.GetSize() == 3)
				{
					CString strMsg[3];

					for(int i=0; i<3; i++)
					{
						strMsg[i] = m_OpInfo.strTempArray[i];
						strMsg[i].TrimLeft();
					}

					if (strMsg[0].GetLength() <= 0 && strMsg[1].GetLength() <= 0 && strMsg[2].GetLength() <= 0)
					{
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER1, L"");
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER2, L"");
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER3, L"");
					}
					else
					{
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER1, m_OpInfo.strTempArray[0]);
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER2, m_OpInfo.strTempArray[1]);
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER3, m_OpInfo.strTempArray[2]);
					}
					ClerkNoticeToUser(T_OPERATE_OK);
				}
			}
		}
		// [#2202] NH Justin 2013.06.20 Add Extra Disclaimer
		else if (m_OpInfo.strReturn == L"DISCLAIMER2")
		{
			CString strValue;
			strValue.Format(L"%s\n%s\n%s", MemGetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER4),
										   MemGetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER5),
										   MemGetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER6));

			if (ClerkInputAlpha(L"994F8T", strValue, 3, 40, m_OpInfo.strReturn) == TRUE)
			{
				SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

				if (m_OpInfo.strTempArray.GetSize() == 3)
				{
					CString strMsg[3];

					for(int i=0; i<3; i++)
					{
						strMsg[i] = m_OpInfo.strTempArray[i];
						strMsg[i].TrimLeft();
					}

					if (strMsg[0].GetLength() <= 0 && strMsg[1].GetLength() <= 0 && strMsg[2].GetLength() <= 0)
					{
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER4, L"");
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER5, L"");
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER6, L"");
					}
					else
					{
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER4, m_OpInfo.strTempArray[0]);
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER5, m_OpInfo.strTempArray[1]);
						MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DF_DCC_DISCLAIMER6, m_OpInfo.strTempArray[2]);
					}
					ClerkNoticeToUser(T_OPERATE_OK);
				}
			}
		}
		// End of [#2202]
		*/
		// end of [#2360]

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 870;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
	} 
	NHDEBUG(1, (L"END\n"));
}
