						MemSetStr(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_STORE_MESSAGE3, m_OpInfo.strTempArray[2]);
						MemSetStr(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_STORE_MESSAGE4, m_OpInfo.strTempArray[3]);
