		{
				m_OpInfo.nProcNextScrNum = 855;			// [#30] NH AIREAT 2008.3.18
				break;
		}
		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 855;
			break;
		}
