/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: 857:ClerkViewBinListProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 857 PROC
-------------------------------------------------------------------*/
#if (AU_VERSION)	// [#2069] NH KSK 2011.06.13
void	CMainFrame::ClerkViewBinListProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	m_OpInfo.nMoveProcReason = MOVE_PROC_SELECT;					// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout


	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F1
		if (m_OpInfo.strReturn == L"PREVPAGE")
		{
			if ( m_pDevCmn->m_BINMgr.MoveCurrentPage(-1) == FALSE)
				ClerkNoticeToUser(T_NO_BIN_DATA_MSG);
		}
		// F2
		else if (m_OpInfo.strReturn == L"NEXTPAGE")
		{
			if ( m_pDevCmn->m_BINMgr.MoveCurrentPage(1) == FALSE)
				ClerkNoticeToUser(T_NO_BIN_DATA_MSG);
		}
		// F3
		else if (m_OpInfo.strReturn == L"PREV50")
		{
			if ( m_pDevCmn->m_BINMgr.MoveCurrentPage(-5) == FALSE)
				ClerkNoticeToUser(T_NO_BIN_DATA_MSG);
		}
		// F5
		else if (m_OpInfo.strReturn == L"NEXT50")
		{
			if ( m_pDevCmn->m_BINMgr.MoveCurrentPage(5) == FALSE)
				ClerkNoticeToUser(T_NO_BIN_DATA_MSG);
		}
		// F5
		else if (m_OpInfo.strReturn == L"ADDNEW")
		{
			m_pDevCmn->m_BINMgr.SetEditBinInformation(FALSE);
			m_OpInfo.nProcNextScrNum = 855;
			break;
		}
		// F6
		else if ( m_OpInfo.strReturn ==   L"EDIT")
		{
			CString strBinCount;
			strBinCount.Format(L"%d", m_pDevCmn->m_BINMgr.GetTotalBinCount());
			if (ClerkInputNumber(L"857F6T", L"", strBinCount, EDIT_NORMAL, 5 , m_OpInfo.strReturn) == TRUE)
			{
				NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));
				
				m_OpInfo.m_strMsg = T_INVALID_DATA;

				if (IsNum(m_OpInfo.strReturn) == TRUE)
				{
					int nTargetIndex = Asc2Int(m_OpInfo.strReturn) -1;
					int nTotalCount = m_pDevCmn->m_BINMgr.GetTotalBinCount();

					if ( nTargetIndex >= 0 && nTargetIndex < nTotalCount)
					{
						m_pDevCmn->m_BINMgr.SetEditBinInformation(TRUE, nTargetIndex);
						m_OpInfo.nProcNextScrNum = 855;
						break;
					}
				}
				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}
		}
		// F7
		else if (  m_OpInfo.strReturn ==   L"SEARCH")
		{
			CString strBinCount;
			strBinCount.Format(L"%d", m_pDevCmn->m_BINMgr.GetTotalBinCount());
			if (ClerkInputNumber(L"857F7T", L"", strBinCount, EDIT_NORMAL, 10 , m_OpInfo.strReturn) == TRUE)
			{
				NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

				if ( m_OpInfo.strReturn.GetLength() == 0)
				{
					m_OpInfo.m_strMsg = T_BIN_INVALID_MSG;
					ClerkNoticeToUser(m_OpInfo.m_strMsg);
				}
				else
				{
					ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);
					char szBin[BIN_NO_SIZE+1];
					memset(szBin, 0, sizeof(szBin));
					WideToMulti(szBin, m_OpInfo.strReturn, sizeof(szBin));

					m_pDevCmn->m_BINMgr.SetSearchBinNumber(szBin);

					if ( m_pDevCmn->m_BINMgr.SearchNextBinNumber() == FALSE)
					{
						m_OpInfo.m_strMsg = T_BIN_NOT_FOUND_MSG;
						ClerkNoticeToUser(m_OpInfo.m_strMsg);
					}	
				}
			}
		}
		// F8
		else if (  m_OpInfo.strReturn ==   L"DELETE")
		{
			CString strBinCount;
			strBinCount.Format(L"%d", m_pDevCmn->m_BINMgr.GetTotalBinCount());
			if (ClerkInputNumber(L"857F8T", L"", strBinCount, EDIT_NORMAL, 5 , m_OpInfo.strReturn) == TRUE)
			{
				NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));
				
				m_OpInfo.m_strMsg = T_INVALID_DATA;

				if (IsNum(m_OpInfo.strReturn) == TRUE)
				{
					int nTargetIndex = Asc2Int(m_OpInfo.strReturn) -1;
					int nTotalCount = m_pDevCmn->m_BINMgr.GetTotalBinCount();

					if ( nTargetIndex >= 0 && nTargetIndex < nTotalCount)
					{
						m_pDevCmn->m_BINMgr.DeleteBinProperites(nTargetIndex);
						m_OpInfo.m_strMsg = T_OPERATE_OK;
					}
				}
				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 858;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
////////////////////////////////////////////////////////////////////////////////////////////////////////////

}
#endif
//end of //[#545]



/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkSelectCouponOptionProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 949 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkSelectCouponOptionProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		if (m_OpInfo.strReturn == L"COUPONSETTING")
		{
			if (MemGetInt(_MEM_FLD_ENHANCED_COUPON, _MEM_VAR_ENHANCED_COUPON_ENABLE) == ENABLE)
				m_OpInfo.nProcNextScrNum = 874;
			else
				m_OpInfo.nProcNextScrNum = 803;
			break;
		}
		// [#2166] NH KSK 2012.12.17
// 		else
// 		{
// 			if (m_OpInfo.strTempArray.GetSize() == 2 && m_OpInfo.strTempArray[0] == L"ENHANCEDCOUPONENDISABLE")
// 				MemSetInt(_MEM_FLD_ENHANCED_COUPON, _MEM_VAR_ENHANCED_COUPON_ENABLE, m_OpInfo.strTempArray[1] == L"ENHANCED COUPON" ? 1 : 0);	// [#633] NH KSK 2010.03.31
// 		}
		else if (m_OpInfo.strReturn == L"ENHANCEDCOUPONENDISABLE")
		{
			if (MemGetInt(_MEM_FLD_ENHANCED_COUPON, _MEM_VAR_ENHANCED_COUPON_ENABLE) == ENABLE)
				MemSetInt(_MEM_FLD_ENHANCED_COUPON, _MEM_VAR_ENHANCED_COUPON_ENABLE, 0);
			else
				MemSetInt(_MEM_FLD_ENHANCED_COUPON, _MEM_VAR_ENHANCED_COUPON_ENABLE, ENABLE);
		}
		// end of [#2166]

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;				// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
			m_OpInfo.nProcNextScrNum = 869;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;			// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (_T("***ClerkCtrl***CMainFrame::ClerkSelectCouponOptionProc() return \n")));

	return;
}

/*-------------------------------------------------------------------
CLASS    NAME: CMainFrame
FUNCTION NAME: ClerkBasicCouponSettingProc()
RETURN TYPE  : 
PARAMETER    : 
DESCRIPTION  : SCR 803 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkBasicCouponSettingProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		if (m_OpInfo.strReturn == L"COUPON1")
		{
#if (US_VERSION || CA_VERSION || MX_VERSION) //[#2000] SOOK 2010.10.12 호주 사양 적용 (Coupon & Advertisement) // [#2115] MX KSK 2012.02.05
			m_OpInfo.nProcNextScrNum = 831;
#else
			m_OpInfo.nProcNextScrNum = 837;
#endif //end of [#2000]
			break;
		}
		else if (m_OpInfo.strReturn == L"COUPON2")
		{
//			m_OpInfo.nProcNextScrNum = 832;
#if (US_VERSION || CA_VERSION || MX_VERSION) //[#2000] SOOK 2010.10.12 호주 사양 적용 (Coupon & Advertisement)	// [#2115] MX KSK 2012.02.05
			m_OpInfo.nProcNextScrNum = 832;
#else
			m_OpInfo.nProcNextScrNum = 838;
#endif //end of [#2000]
			break;
		}
		else if (m_OpInfo.strReturn == L"COUPON3")
		{
//			m_OpInfo.nProcNextScrNum = 833;
#if (US_VERSION || CA_VERSION || MX_VERSION) //[#2000] SOOK 2010.10.12 호주 사양 적용 (Coupon & Advertisement)	// [#2115] MX KSK 2012.02.05
			m_OpInfo.nProcNextScrNum = 833;
#else
			m_OpInfo.nProcNextScrNum = 839;
#endif //end of [#2000]
			break;
		}
		else if (m_OpInfo.strReturn == L"COUPON4")
		{
//			m_OpInfo.nProcNextScrNum = 834;
#if (US_VERSION || CA_VERSION || MX_VERSION) //[#2000] SOOK 2010.10.12 호주 사양 적용 (Coupon & Advertisement)	// [#2115] MX KSK 2012.02.05
			m_OpInfo.nProcNextScrNum = 834;
#else
			m_OpInfo.nProcNextScrNum = 840;
#endif //end of [#2000]
			break;
		}
		else if (m_OpInfo.strReturn == L"COUPON5")
		{
//			m_OpInfo.nProcNextScrNum = 835;
#if (US_VERSION || CA_VERSION || MX_VERSION) //[#2000] SOOK 2010.10.12 호주 사양 적용 (Coupon & Advertisement) // [#2115] MX KSK 2012.02.05
			m_OpInfo.nProcNextScrNum = 835;
#else
			m_OpInfo.nProcNextScrNum = 841;
#endif //end of [#2000]
			break;
		}
		else if (m_OpInfo.strReturn == L"COUPON6")
		{
//			m_OpInfo.nProcNextScrNum = 836;
#if (US_VERSION || CA_VERSION || MX_VERSION) //[#2000] SOOK 2010.10.12 호주 사양 적용 (Coupon & Advertisement)	// [#2115] MX KSK 2012.02.05
			m_OpInfo.nProcNextScrNum = 836;
#else
			m_OpInfo.nProcNextScrNum = 842;
#endif //end of [#2000]
			break;
		}
		// [#2556] NH Justin 2018.06.11 OP Coupon Test Print
		else if (m_OpInfo.strReturn == L"TESTPRINT")
		{
			CString strPrintData = L"";
			CString strTemp;
			for (int i = 0; i < 6; i++)
			{
				if (MemGetInt(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_ENDISFLAG+i) == ENABLE)
				{
					if(strPrintData.GetLength()>0)
					{
						AddPrintData(strPrintData, L" ");
						AddPrintData(strPrintData, L" ");
					}

					AddPrintData(strPrintData, L"  %-10.10s#%d %s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_RECE_CPN), (i+1), m_pDevCmn->fstrSCR_GetStringFromTextID(T_RECE_MSG));
					AddPrintData(strPrintData, L"****************************************");
					strTemp.Format(L"%s%c%s",	MemGetStr(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_TEXT1+(i*3)), FIELD_DELIMITER,	MemGetStr(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_TEXT2+(i*3)));
					if (strTemp.GetLength() <= 1)
						strTemp.Format(L"  (%s)", m_pDevCmn->fstrSCR_GetStringByTextID("none"));
					AddPrintData(strPrintData, strTemp);
					AddPrintData(strPrintData, L"****************************************");
				}
			}
			if(strPrintData.GetLength()<=0)
			{
				ClerkNoticeToUser(T_OPERATE_NG, TRUE);
			}
			else
			{
				ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);
				if (m_pDevCmn->fnSPR_PrintReceipt(FALSE, strPrintData, K_1_WAIT, TRUE, FALSE) != TRUE)				// No Header, Eject, No Barcode
					ClerkNoticeToUser(T_OPERATE_NG);
				else
					ClerkNoticeToUser(T_OPERATE_OK);
			}
		}
		// End of [#2556]

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;				// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
#if (US_VERSION || CA_VERSION || MX_VERSION) //[#2000] SOOK 2010.10.12 호주 사양 적용 (Coupon & Advertisement)	// [#2115] MX KSK 2012.02.05
			m_OpInfo.nProcNextScrNum = 949;
#else
			m_OpInfo.nProcNextScrNum = 869;
#endif	//end of [#2000]
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;			// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (_T("***ClerkCtrl***CMainFrame::ClerkBasicCouponSettingProc() return \n")));

	return;
}

