void	CMainFrame::ClerkBasicCoupon1Proc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));
	CString strTemp;

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// [#2166] NH KSK 2012.12.17
//		if ((m_OpInfo.strTempArray.GetSize() >= 2) && (m_OpInfo.strTempArray[0] == L"COUPONACTIVATE1"))	// F1
//		{
//			MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_ENDISFLAG, m_OpInfo.strTempArray[1] == L"ENABLE" ? 1 : 0);
//		}	
		if (m_OpInfo.strReturn == L"COUPONACTIVATE1")	// F1
		{
			if (MemGetInt(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_ENDISFLAG) == ENABLE)
				MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_ENDISFLAG, 0);
			else
				MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_ENDISFLAG, ENABLE);
		}
		// end of [#2166]
		else if (m_OpInfo.strReturn == L"COUPON1TEXT")
		{
			CString strValue;
			strValue.Format(L"%s\n%s", 	MemGetStr(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_TEXT1),
										MemGetStr(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_TEXT2));

//			if (ClerkInputAlpha(L"831F2T", strValue, 2, 39, strTemp) == TRUE)
			if (ClerkInputAlpha(L"831F2T", strValue, 2, 40, strTemp) == TRUE)	// [#11] NH KSK 2010.09.27 Coupon 사양 변경 39 -> 40
			{
				m_OpInfo.strTempArray.RemoveAll();
				SplitString(strTemp, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

				if (m_OpInfo.strTempArray.GetSize() == 2)
				{
					CString strMsg[2];

					for(int i=0; i<2; i++)
					{
						strMsg[i] = m_OpInfo.strTempArray[i];
						strMsg[i].TrimLeft();
					}

					if (strMsg[0].GetLength() <= 0 && strMsg[1].GetLength() <= 0)
					{
						MemSetStr(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_TEXT1, L"");
						MemSetStr(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_TEXT2, L"");
					}
					else
					{
						MemSetStr(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_TEXT1, m_OpInfo.strTempArray[0]);
						MemSetStr(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON1_TEXT2, m_OpInfo.strTempArray[1]);
					}
					ClerkNoticeToUser(T_OPERATE_OK);
				}
				else
					ClerkNoticeToUser(T_INVALID_DATA);
			}
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;				// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
			m_OpInfo.nProcNextScrNum = 803;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;			// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (_T("***ClerkCtrl***CMainFrame::ClerkBasicCoupon1Proc() return \n")));

	return;
}

