// 		}	
		if (m_OpInfo.strReturn == L"COUPONACTIVATE4")	// F1
		{
			if (MemGetInt(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON4_ENDISFLAG) == ENABLE)
				MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON4_ENDISFLAG, 0);
			else
				MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON4_ENDISFLAG, ENABLE);

			if (MemGetInt(_MEM_FLD_ADVINFO, _MEM_VAR_COUPON4_ENDISFLAG) == 0)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_AWARD_COUPON4_ENABLE,  0);

		}	
		if (m_OpInfo.strReturn == L"AWARDCOUPON4")	// F1
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_AWARD_COUPON4_ENABLE) == ENABLE)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_AWARD_COUPON4_ENABLE, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_AWARD_COUPON4_ENABLE, ENABLE);
		}
