/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkSystemSetupProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 951 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkSystemSetupProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();


		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F1
		if (m_OpInfo.strReturn == L"SETCLOCK")
		{
			m_OpInfo.nProcNextScrNum = 952;
			break;
		}
		// F2
		else if (m_OpInfo.strReturn == L"CHANGEPASSWORD")
		{
			m_OpInfo.nProcNextScrNum = 956;
			break;
		}
		// F3
		else if (m_OpInfo.strReturn == L"SPEAKERVOL")
		{
			m_OpInfo.nProcNextScrNum = 953;
			break;
		}
		// F4  //SOOK 2010.10.11 호주 사양 적용 
		else if (m_OpInfo.strReturn == L"SERIALNUMBER")
		{
			 CString strValue = MemGetStr(_MEM_FLD_APP_ATMINFO,_MEM_VAR_APP_ATMSERIALNO);

			if (ClerkInputAlpha(L"951F4T", strValue, 1, 10, m_OpInfo.strReturn) == TRUE)
			{
				CString strtemp;
				
				strtemp = m_OpInfo.strReturn;
				strtemp.TrimLeft();
				strtemp.TrimRight();
				
				if (strtemp.GetLength() <= 0)
				{
					MemSetStr(_MEM_FLD_APP_ATMINFO,_MEM_VAR_APP_ATMSERIALNO, L"");
					m_OpInfo.m_strMsg = T_OPERATE_OK;
				}
				else
				{
					if (strtemp.GetLength() <= 10)
					{
						MemSetStr(_MEM_FLD_APP_ATMINFO,_MEM_VAR_APP_ATMSERIALNO, m_OpInfo.strReturn);
						m_OpInfo.m_strMsg = T_OPERATE_OK;
					}
					else
						m_OpInfo.m_strMsg = T_INVALID_DATA;
				}

				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}

		} //end of [#2000]
		// F5
		else if (m_OpInfo.strReturn == L"ATMIPSETUP")
		{
			if (MemGetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_NETWORKTYPE) == NETWORK_DIALUP)	// Dial-up
				m_OpInfo.nProcNextScrNum = 957;
			else
				m_OpInfo.nProcNextScrNum = 979;
			break;
		}
		// F6
		else if (m_OpInfo.strReturn == L"DEVICESETUP")
		{
			m_OpInfo.nProcNextScrNum = 844;
			break;
		}
		// F7
		else if (m_OpInfo.strReturn == L"LANGUAGES")
		{
			// [#2434] AU Kook 2016.07.27 Support Multi Languages for transaction.
//#if (AU_A_VERSION)
#if (AU_VERSION)	// [#2468] AU KSK 2017.01.18
			m_OpInfo.nProcNextScrNum = 954;		// go 'TRANSACTION LANGUAGE' directly.
			// end of [#2434]
#else
			// [#2166] NH KSK 2012.11.13
			m_OpInfo.nProcNextScrNum = 993;
#endif
			break;
		}
		// F8
		else if (m_OpInfo.strReturn == L"SYSTEMCONTROL")
		{
			m_OpInfo.nProcNextScrNum = 846;
			break;
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 901;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
}


/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkClockSetupProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 952 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkClockSetupProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	BOOL	bShowScreen = TRUE;

	m_OpInfo.m_UserInputValue[5] = L"";
	m_OpInfo.m_UserInputValue[6] = L"";
	m_OpInfo.m_UserInputValue[7] = L"";
	m_OpInfo.m_UserInputValue[8] = L"";
	m_OpInfo.m_UserInputValue[9] = L"";

	while(TRUE)
	{
		///////////////////////////////////
		// DISPLAY SCREEN
		if (bShowScreen == TRUE)
		{
			ClerkScreenDisplay(m_OpInfo.nProcNextScrNum, m_OpInfo.nTimeout);
			m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);
			bShowScreen = FALSE;

			m_OpInfo.nProcLoofCnt = 0;
		}

		///////////////////////////////////
		// Check Device
		// 장치의 상태를 체크하고 변경시 아래에서 Update를 수행한다.
		if (m_OpInfo.nProcLoofCnt >= SCR_UPDATECYCLE)
		{
			ClerkCheckDeviceStatus();
			ClerkScreenUpdate(m_OpInfo.nProcNextScrNum);

			m_OpInfo.nProcLoofCnt = 0;
		}

		///////////////////////////////////
		// GET KEY STRING
		// 화면 입력을 기다린다.
		if (m_pDevCmn->fnSCR_ScanDeviceAction(DEV_SCR, SCR_INPUTWAIT, EVENT_IN) == DEV_SCR)
		{
			m_pDevCmn->fnAPL_EnDisableHotKey(DISABLE);
			m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

			NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

			//-----------------------------------
			// PROCESS KEY STRING
			//-----------------------------------
			// F1
			if (m_OpInfo.strReturn == L"YEAR")
			{
				if (ClerkInputNumber(L"952F1T", L"", m_OpInfo.m_UserInputValue[0], EDIT_NORMAL, 4, m_OpInfo.strReturn) == TRUE)
				{
					if (IsNum(m_OpInfo.strReturn) == TRUE)
						m_OpInfo.m_UserInputValue[5] = m_OpInfo.strReturn;
					else
						ClerkNoticeToUser(T_INVALID_DATA);
				}
				bShowScreen = TRUE;
			}
			// F3
			else if (m_OpInfo.strReturn == L"MONTH")
			{
				if (ClerkInputNumber(L"952F3T", L"", m_OpInfo.m_UserInputValue[1], EDIT_NORMAL, 2, m_OpInfo.strReturn) == TRUE)
				{
					if (IsNum(m_OpInfo.strReturn) == TRUE)
						m_OpInfo.m_UserInputValue[6] = m_OpInfo.strReturn;
					else
						ClerkNoticeToUser(T_INVALID_DATA);
				}
				bShowScreen = TRUE;
			}
			// F5
			else if (m_OpInfo.strReturn == L"DAY")
			{
				if (ClerkInputNumber(L"952F5T", L"", m_OpInfo.m_UserInputValue[2], EDIT_NORMAL, 2, m_OpInfo.strReturn) == TRUE)
				{
					if (IsNum(m_OpInfo.strReturn) == TRUE)
						m_OpInfo.m_UserInputValue[7] = m_OpInfo.strReturn;
					else
						ClerkNoticeToUser(T_INVALID_DATA);
				}
				bShowScreen = TRUE;
			}
			// F2
			else if (m_OpInfo.strReturn == L"HOUR")
			{
				if (ClerkInputNumber(L"952F2T", L"", m_OpInfo.m_UserInputValue[3], EDIT_NORMAL, 2, m_OpInfo.strReturn) == TRUE)
				{
					if (IsNum(m_OpInfo.strReturn) == TRUE)
						m_OpInfo.m_UserInputValue[8] = m_OpInfo.strReturn;
					else
						ClerkNoticeToUser(T_INVALID_DATA);
				}
				bShowScreen = TRUE;
			}
			// F4
			else if (m_OpInfo.strReturn == L"MINUTE")
			{
				if (ClerkInputNumber(L"952F4T", L"", m_OpInfo.m_UserInputValue[4], EDIT_NORMAL, 2, m_OpInfo.strReturn) == TRUE)
				{
					if (IsNum(m_OpInfo.strReturn) == TRUE)
						m_OpInfo.m_UserInputValue[9] = m_OpInfo.strReturn;
					else
						ClerkNoticeToUser(T_INVALID_DATA);
				}
				bShowScreen = TRUE;
			}
			
			// F8
			else if (m_OpInfo.strReturn == L"APPLY")
			{
				int	nTemp;

				// Setting current time
				CString strCurTime = m_pDevCmn->fstrAPL_ClerkInformationMake(801);

				if (m_OpInfo.m_UserInputValue[5].GetLength() == 0)
					m_OpInfo.m_UserInputValue[5] = strCurTime.Mid(0,4);

				if (m_OpInfo.m_UserInputValue[6].GetLength() == 0)
					m_OpInfo.m_UserInputValue[6] = strCurTime.Mid(4,2);

				if (m_OpInfo.m_UserInputValue[7].GetLength() == 0)
					m_OpInfo.m_UserInputValue[7] = strCurTime.Mid(6,2);

				if (m_OpInfo.m_UserInputValue[8].GetLength() == 0)
					m_OpInfo.m_UserInputValue[8] = strCurTime.Mid(8,2);

				if (m_OpInfo.m_UserInputValue[9].GetLength() == 0)
					m_OpInfo.m_UserInputValue[9] = strCurTime.Mid(10,2);

				nTemp = Asc2Int(m_OpInfo.m_UserInputValue[5]);

				m_OpInfo.m_strMsg = T_INVALID_DATA;

				if (nTemp >= 2000 && 
					nTemp <= 2099 &&
					m_OpInfo.m_UserInputValue[5].GetLength() != 0 &&
					m_OpInfo.m_UserInputValue[6].GetLength() != 0 &&
					m_OpInfo.m_UserInputValue[7].GetLength() != 0 &&
					m_OpInfo.m_UserInputValue[8].GetLength() != 0 &&
					m_OpInfo.m_UserInputValue[9].GetLength() != 0)
				{
					COleDateTime oleDate, oleCurDate;
					
					oleCurDate = COleDateTime::GetCurrentTime();
					
					oleDate.SetDateTime(Asc2Int(m_OpInfo.m_UserInputValue[5]), 
										Asc2Int(m_OpInfo.m_UserInputValue[6]), 
										Asc2Int(m_OpInfo.m_UserInputValue[7]), 
										Asc2Int(m_OpInfo.m_UserInputValue[8]), 
										Asc2Int(m_OpInfo.m_UserInputValue[9]),
										0 );
					
					if(oleDate.GetStatus() == COleDateTime::valid)
					{
						CString szDate, szTime, szCurDate;
						szCurDate.Format(_T("%4d%2d%d"), oleCurDate.GetYear(),
							oleCurDate.GetMonth(),
							oleCurDate.GetDay());
						
						szDate.Format(_T("%4d%2d%d"),	oleDate.GetYear(),
							oleDate.GetMonth(),
							oleDate.GetDay());
						
						szTime.Format(_T("%2d%2d"),		oleDate.GetHour(),
							oleDate.GetMinute());
						
						PutDateTime(szDate,szTime);
						
						// Reset Auto Day Total
						if (szCurDate != szDate)
						{
							MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_AUTODAYTOTAL_TIME_YEAR, 2000);
							// [#2037] AU KSK 2011.03.31	// [#2457] US Justin 2016.12.09 Support Moniview Journal Uploading
							// [#2500] CA Justin 2017.08.22 Support Moniview Journal Uploading
							#if (AU_VERSION || US_VERSION || CA_VERSION)	
								MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_SCHEDULED_JOURNAL_YEAR, 2000);	// [#613] AU_C KSK 2010.01.18 System Date 변경 시 무조건 Send하도록 함
							#endif
						}
#if SUPPORT_CHANGE_PARAMETER_JNL	//[#610] SOOK 2010.01.16 Configuration Change 저널 추가 
						m_pDevCmn->m_JNLMgr.Save(OPERATOR_ACTION, L"ATM Date & Time Changed"); 
#endif  //end of [#610]
						
						m_OpInfo.m_strMsg = T_OPERATE_OK;
					}
				}

				m_OpInfo.m_UserInputValue[5] = L"";
				m_OpInfo.m_UserInputValue[6] = L"";
				m_OpInfo.m_UserInputValue[7] = L"";
				m_OpInfo.m_UserInputValue[8] = L"";
				m_OpInfo.m_UserInputValue[9] = L"";

				ClerkNoticeToUser(m_OpInfo.m_strMsg);
				bShowScreen = TRUE;
			}

			//-----------------------------------
			// COMMON PROCESS
			//-----------------------------------
			if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
			{
				m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
				m_OpInfo.nProcNextScrNum = 951;
				break;
			}
			else if (m_OpInfo.strReturn == S_TIMEOVER)
			{
				m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
				m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
				break;
			}
		}

		m_OpInfo.nProcLoofCnt++;	
		Delay_Msg(PROC_LOOFDELAY);

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
}


/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkAdjustVolumeProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 953 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkAdjustVolumeProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		if (m_OpInfo.strReturn == L"VOLUMEUP")
		{
			int nVol = MemGetInt(_MEM_FLD_INI_DEVINFO, _MEM_VAR_DEVINFO_VOLUMELEVEL);
			nVol++;

			if (nVol < 0)			
				nVol = 0;
			else if (nVol > 10)
				nVol = 10;

			MemSetInt(_MEM_FLD_INI_DEVINFO, _MEM_VAR_DEVINFO_VOLUMELEVEL, nVol);
			m_pAdaCtrl->fnExp_SetVolume(nVol);
		}
		else if (m_OpInfo.strReturn == L"VOLUMEDOWN")
		{
			int nVol = MemGetInt(_MEM_FLD_INI_DEVINFO, _MEM_VAR_DEVINFO_VOLUMELEVEL);
			nVol--;

			if (nVol < 0)			
				nVol = 0;
			else if (nVol > 10)
				nVol = 10;

			MemSetInt(_MEM_FLD_INI_DEVINFO, _MEM_VAR_DEVINFO_VOLUMELEVEL, nVol);
			m_pAdaCtrl->fnExp_SetVolume(nVol);
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 951;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
}

