// [#16] NH KGS 2008.03.12 OP Reversal Retry Count
/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkReversalRetryProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 990 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkReversalRetryProc()	
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		if (m_OpInfo.strReturn == L"COUNT")
		{
			CString strAmount;
			strAmount.Format(L"%d", MemGetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_REVERSAL_RETRY));

			if (ClerkInputNumber(L"990F1T", L"", strAmount, EDIT_NORMAL, 3, m_OpInfo.strReturn) == TRUE)
			{
				NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));
				if (IsNum(m_OpInfo.strReturn) == TRUE)
				{
					int nRetryCnt = Asc2Int( m_OpInfo.strReturn);
					if( 0 <= nRetryCnt && nRetryCnt <= 999)
					{
						MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_REVERSAL_RETRY, nRetryCnt);
						ClerkNoticeToUser(T_OPERATE_OK);
					}
					else
						ClerkNoticeToUser(T_INVALID_DATA);
				}
				else
					ClerkNoticeToUser(T_INVALID_DATA);
			}
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;				// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
			m_OpInfo.nProcNextScrNum = 971;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;			// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
}
