//	[#81] UK KGS 2008.04.07 AID List 
/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkEMVProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 950 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkEMVProc()	
{
	NHDEBUG(DBG_CALL, (_T("***ClerkCtrl***CMainFrame::ClerkEMVProc() \n")));

	m_OpInfo.nProcLoofCnt = 0;
	m_OpInfo.nMsgClearCount = 0;
	m_OpInfo.nMoveProcReason = MOVE_PROC_SELECT;					// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
	
	while(TRUE)
	{
		ClerkWaitScreenInput_byCha();

		// Get Event String
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;				// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
			m_OpInfo.nProcNextScrNum = 996;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;			// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
		else if (m_OpInfo.strReturn == L"AIDLIST")
		{
			m_OpInfo.nProcNextScrNum = 998;
			break;
		}
		// [#2166] NH KSK 2012.12.17
		else if (m_OpInfo.strReturn == L"EMVENDISABLE")
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_EMV_ENABLE) == ENABLE)
				MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_EMV_ENABLE, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_EMV_ENABLE, ENABLE);
		}
		// [#2226] NH Justin 2013.10.23 Add Kernel Version
		else if (m_OpInfo.strReturn == L"KERNELVER")
		{
			// [#2435] NH KSK 2016.07.14 CA Kernel Version 4 -> 5 -> 6 -> 7
			#if(CA_VERSION)
				if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION) == EMV_KERNEL_V4)
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION, EMV_KERNEL_V5);
				else if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION) == EMV_KERNEL_V5)
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION, EMV_KERNEL_V6);
				// [#GLDV-2522] NH Kook 2019.07.01 Support EMV Kernel V7.0
				else if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION) == EMV_KERNEL_V6)
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION, EMV_KERNEL_V7);
				// end of [#GLDV-2522]
				else
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION, EMV_KERNEL_V4);
			#else	// else country Kernel Version 5 -> 6 -> 7
			// [#GLDV-2522] NH Kook 2019.07.01 Support EMV Kernel V7.0
				//if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION) == EMV_KERNEL_V6)
				//	MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION, EMV_KERNEL_V5);
				//else
				//	MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION, EMV_KERNEL_V6);
				if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION) == EMV_KERNEL_V5)
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION, EMV_KERNEL_V6);
				else if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION) == EMV_KERNEL_V6)
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION, EMV_KERNEL_V7);
				else
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION, EMV_KERNEL_V5);
			// end of [#GLDV-2522]
			#endif
			// end of [#2435]

			// For AID En/Disable..... => Should be reboot when exit the OP
			int nEMVKernelVer = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_KERNELVERSION);
			m_pDevCmn->fnEMV_SetKernelVersion(nEMVKernelVer);
		}
		// End of [#2226]
		else if (m_OpInfo.strReturn == L"EMVLATCHOPTION")
		{
			// [#2458] AU KSK 2016.12.09 Sankyo인 경우 SP Open시만 Check하므로 OPEN CLOSE를 위한 Confirm 화면 추가
			// KSK 주의 : Latch Enable이 0이고 Disable이 1임
			if (m_pDevCmn->GetDeviceType(L"MCU") == MCU_SANKYO_DIP)
			{
				CString	strTemp;

				if (ClerkConfirm(L"950F4S", strTemp) == TRUE)		
				{
					ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);

					// MCU Device Close
					m_pDevCmn->fnMCU_Deinitialize();

					if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_LATCH_ENABLE) == 0)
					{
						MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_LATCH_ENABLE, 1);
						RegSetInt(L"SOFTWARE\\ATM\\DevInfo\\IDC", L"LatchOption", 1);	// Latch 사용 안함
					}
					else
					{
						MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_LATCH_ENABLE, 0);
						RegSetInt(L"SOFTWARE\\ATM\\DevInfo\\IDC", L"LatchOption", 0);				// Latch 사용함
					}

					// MCU Device Open
					m_pDevCmn->fnAPL_ClearError();
					m_pDevCmn->fnMCU_Initialize();
					m_pDevCmn->fnAPL_CheckDeviceAction(DEV_MCU);						// 2005.09.11

					if (m_pDevCmn->fnMCU_GetDeviceStatus() != NORMAL)
						ClerkNoticeToUser(T_DEVICE_ERR, TRUE);
					else
						ClerkNoticeToUser(T_OPERATE_OK, TRUE);
				}

				// 이 후 950번 화면 갱신을 위해 임의로 현재 화면 번호를 초기화
				m_OpInfo.nCurScrNum = 0;
			}
			else
			{
				// MAGTEK인 경우
				if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_LATCH_ENABLE) == 0)
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_LATCH_ENABLE, 1);
				else
					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_LATCH_ENABLE, 0);

				// MCU Registry 설정 변경 (MCU SP 변경 필요함)
				if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_LATCH_ENABLE) == 0)
					RegSetInt(L"SOFTWARE\\ATM\\DevInfo\\IDC", L"LatchOption", 0);	// Latch 사용함
				else
					RegSetInt(L"SOFTWARE\\ATM\\DevInfo\\IDC", L"LatchOption", 1);	// Latch 사용 안함
			}			
		}
		// [#2425] US Justin 2016.05.23 EMV Language Selection
		else if (m_OpInfo.strReturn == L"LANGUAGESELECTION")
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_LANGUAGESELECTION) == ENABLE)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_LANGUAGESELECTION, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_LANGUAGESELECTION, ENABLE);
		}
		// End of [#2425]
		// [#2549] NH Justin 2018.05.08 Move US options under "Other Options" with US Territory Option
		else if (m_OpInfo.strReturn == L"OTHER_OPTIONS")
		{
			m_OpInfo.nProcNextScrNum = 767;
			break;
		}
		/*
		// [#2342] US Justin 2015.05.06 US COMMON AID
		else if (m_OpInfo.strReturn == L"USE_COMMONAID")
		{
			// 0 : COMMONAID_USE_COMMON
			// 1 : COMMONAID_USE_ALL
			// 2 : COMMONAID_USE_INTERNATIONAL
			int nAIDOpt = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_USE_USCOMMONAID) + 1;
			if(nAIDOpt > COMMONAID_USE_ALL)			// Increase number if "international option" shoule be shown to customers.
				nAIDOpt = COMMONAID_USE_COMMON;	
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_USE_USCOMMONAID, nAIDOpt);
		}
		// End of [#2342]
		// [#2481] US Justin 2018.04.21 Add a fallback option for Unknown AID
		else if (m_OpInfo.strReturn == L"FALLBACK4UNKNOWNAID")
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_4_UNKNOWNAID) == 1)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_4_UNKNOWNAID, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_4_UNKNOWNAID, 1);
		}
		// End of [#2481]		
		// [#2517] US Justin 2017.11.30 EMV Fallback Enable/Diable Option
		else if (m_OpInfo.strReturn == L"FALLBACK_ENDISABLE")
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_ENABLE_DISABLE) == 1)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_ENABLE_DISABLE, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_ENABLE_DISABLE, 1);
		}
		// End of [#2517]
		*/
		// End of [#2549]
	} 

	NHDEBUG(DBG_CALL, (_T("***ClerkCtrl***CMainFrame::ClerkEMVProc() return \n")));
}

/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkAIDLIstProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 998 PROC
-------------------------------------------------------------------*/
int	CMainFrame::ClerkAIDListProc()	
{
	NHDEBUG(DBG_CALL, (_T("***ClerkCtrl***CMainFrame::ClerkAIDLIstProc() \n")));

	m_OpInfo.nProcLoofCnt = 0;
	m_OpInfo.nMsgClearCount = 0;
	m_nPageOfList = 0;
	m_OpInfo.nMoveProcReason = MOVE_PROC_SELECT;					// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout

	m_OpInfo.nTempSelectedAID = 1;									// [#2226] US Justin 2013.10.23 AID En/Disable
	//CString strAIDEnDisable = MemGetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_EMV_AIDENDISABLE);	// [#2226] US Justin 2013.10.23 AID En/Disable
		
	while(TRUE)
	{
		ClerkWaitScreenInput_byCha();

		// Get Event String
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;				// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
			m_OpInfo.nProcNextScrNum = 950;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;			// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
		else
		{
			if (m_OpInfo.strTempArray[0] == L"PREVPAGE")
			{
				m_nPageOfList--;
				if(m_nPageOfList < 0)
					m_nPageOfList = 0;
				else
					m_OpInfo.nTempSelectedAID = 1;

			}
			else if (m_OpInfo.strTempArray[0] == L"NEXTPAGE")
			{
				m_nPageOfList++;
				m_OpInfo.nTempSelectedAID = 1;
			}
			// [#2226] US Justin 2013.10.23 
			else if (m_OpInfo.strTempArray[0] == L"PREVAID")
			{
				m_OpInfo.nTempSelectedAID--;
				if(m_OpInfo.nTempSelectedAID<1)	
				{
					if( m_nPageOfList > 0 )
					{
						m_nPageOfList--;
						m_OpInfo.nTempSelectedAID = MAX_AID_PER_PAGE;
					}
					else
						m_OpInfo.nTempSelectedAID = 1;
				}
			}
			else if (m_OpInfo.strTempArray[0] == L"NEXTAID")
			{
				m_OpInfo.nTempSelectedAID++;
				if(m_OpInfo.nTempSelectedAID>MAX_AID_PER_PAGE) 
				{
					if ( (m_nPageOfList*MAX_AID_PER_PAGE+MAX_AID_PER_PAGE) < m_nTotalNumList)
					{
						m_nPageOfList++;
						m_OpInfo.nTempSelectedAID = 1;
					}
					else
						m_OpInfo.nTempSelectedAID = MAX_AID_PER_PAGE;
				}
			}
			else if (m_OpInfo.strTempArray[0] == L"AIDONOFF")
			{
				if( (m_OpInfo.nTempSelectedAID>=1)&&(m_OpInfo.nTempSelectedAID<=MAX_AID_PER_PAGE) &&
					((m_nPageOfList*MAX_AID_PER_PAGE+m_OpInfo.nTempSelectedAID) <= m_nTotalNumList) )
				{
					// [#2342] US Justin 2015.05.08 AID Selection....
					CStringArray strAIDArray;
					SplitString( m_strListOfPage, SCR_CMD_DELIMITER, strAIDArray);
					if( strAIDArray.GetSize() >= m_OpInfo.nTempSelectedAID )
					{
						CString strSelectedAID = strAIDArray.GetAt(m_OpInfo.nTempSelectedAID - 1 );
						if(strSelectedAID.GetLength()>=10)
						{
							CString strTargetEnDis	= strSelectedAID.Left(1);
							CString strTargetAID	= strSelectedAID.Mid(1);

							CString strAIDEnDisable = MemGetStr(_MEM_FLD_EMVCONFIG, _MEM_VAR_EMV_CONFIG_ENABLEDAID);			
							CString strAIDSeparator = CString(AID_FIELD_DELIMITER);
							
							if(strTargetEnDis.CompareNoCase(L"0")==0)	// if the selected AID is Disabled. => Add the AID
								strAIDEnDisable += strTargetAID + strAIDSeparator;
							else										// if the selected AID is Enabled => Remove the AID
							{
								CStringArray strEnabledAIDArray;
								CString      strOneAID;

								SplitString( strAIDEnDisable, AID_FIELD_DELIMITER, strEnabledAIDArray);
								strAIDEnDisable = _T("");
								for(int nEnAID=0; nEnAID<strEnabledAIDArray.GetSize(); nEnAID++)
								{
									strOneAID = strEnabledAIDArray.GetAt(nEnAID);
									if( (strOneAID.GetLength()>=10)&&(strOneAID.CompareNoCase(strTargetAID)!=0) )
										strAIDEnDisable += strOneAID + strAIDSeparator;
								}
							}
							MemSetStr(_MEM_FLD_EMVCONFIG, _MEM_VAR_EMV_CONFIG_ENABLEDAID, strAIDEnDisable);
						}
					}
					// End of [#2342]
				}
			}
			// End of [#2226]
			else
				m_OpInfo.strTempClerkMessage = T_INVALID_DATA;		
		}
	} 

	NHDEBUG(DBG_CALL, (_T("***ClerkCtrl***CMainFrame::ClerkAIDLIstProc() return \n")));

	return TRUE;
}

// [#2549] NH Justin 2018.05.07 Add Perto Rico Option 
/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkEMVOtherOptionsProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 767 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkEMVOtherOptionsProc()	
{
	NHDEBUG(DBG_CALL, (_T("***ClerkCtrl***CMainFrame::ClerkEMVOtherOptionsProc() \n")));

	m_OpInfo.nProcLoofCnt = 0;
	m_OpInfo.nMsgClearCount = 0;
	m_OpInfo.nMoveProcReason = MOVE_PROC_SELECT;
	
	while(TRUE)
	{
		ClerkWaitScreenInput_byCha();

		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 950;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
		else if (m_OpInfo.strReturn == L"USE_COMMONAID")
		{
			// 0 : COMMONAID_USE_COMMON, // 1 : COMMONAID_USE_ALL 	// 2 : COMMONAID_USE_INTERNATIONAL(NOT USED)
			int nAIDOpt = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_USE_USCOMMONAID) + 1;
			if(nAIDOpt > COMMONAID_USE_ALL)
				nAIDOpt = COMMONAID_USE_COMMON;	
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_USE_USCOMMONAID, nAIDOpt);
		}
		else if (m_OpInfo.strReturn == L"US_TERRITORY")
		{
			int nUSTerritory = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_US_TERRITORY_OPTION) + 1;
			if(nUSTerritory > US_TERRITORY_SAMOA)
				nUSTerritory = US_TERRITORY_US;	
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_US_TERRITORY_OPTION, nUSTerritory);
		}
		else if (m_OpInfo.strReturn == L"FALLBACK4UNKNOWNAID")
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_4_UNKNOWNAID) == 1)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_4_UNKNOWNAID, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_4_UNKNOWNAID, 1);
		}
		else if (m_OpInfo.strReturn == L"FALLBACK_ENDISABLE")
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_ENABLE_DISABLE) == 1)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_ENABLE_DISABLE, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_FALLBACK_ENABLE_DISABLE, 1);
		}
	} 
	NHDEBUG(DBG_CALL, (_T("***ClerkCtrl***CMainFrame::ClerkEMVOtherOptionsProc() return \n")));
}
// End of [#2549]

// [#112] US KGS 2008.04.15 Percent Surcharge Menu
/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkPercentSurchargeProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 959 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkPercentSurchargeProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F1
// #if (US_VERSION) //[#2092] US PCS 2011.10.24
// 		if ((m_OpInfo.strTempArray.GetSize() == 2) && (m_OpInfo.strTempArray[0] == _T("PERCENT_SURCHARGE")))
// 		{
// 			m_OpInfo.nProcNextScrNum = 960;
// 			break;
// 		}
// #else	//end of //[#2092] US PCS 2011.10.24
		// [#2136] US PCS 2012.05.30 "Surcharge Table 옵션 추가로 인한 주석처리."
// 		if ((m_OpInfo.strTempArray.GetSize() == 2) && (m_OpInfo.strTempArray[0] == _T("PERCENT_SURCHARGE")))
// 		{
// 			MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_ENABLE, m_OpInfo.strTempArray[1] == _T("ENABLE") ? 1 : 0);
// 			//ClerkNoticeToUser(T_OPERATE_OK);
// 		}
		//end of [#2136]
//#endif
		// F2
		//else if (m_OpInfo.strTempArray[0] == _T("SURCHARGE_PERCENT"))
		if (m_OpInfo.strReturn == _T("SURCHARGE_PERCENT"))
		{
			CString strAmount;
			//strAmount.Format(L"%d", MemGetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_PERCENT));
			strAmount.Format(L"%d", MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DECIMAL_SURCHARGE));				// [#2316] US Justin Support Decimal Surcharge
			if (ClerkInputNumber(L"959F2T", L"", strAmount, EDIT_DECIMAL, 4, m_OpInfo.strReturn) == TRUE)					// [#2316] US Justin Support Decimal Surcharge
			{
				NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));
				if (IsNum(m_OpInfo.strReturn) == TRUE)
				{
					// [#2220] AU KMK 2014.03.04 Percent Surcharge에 0 초과만 입력되도록 수정
					if (Asc2Int(m_OpInfo.strReturn) > 0)
					// end of [#2220]
					{
						//MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_PERCENT, Asc2Int(m_OpInfo.strReturn));
						MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DECIMAL_SURCHARGE, Asc2Int(m_OpInfo.strReturn));		// [#2316] US Justin Support Decimal Surcharge					
						ClerkNoticeToUser(T_OPERATE_OK);
					}
					else
						ClerkNoticeToUser(T_INVALID_DATA);
				}
				else
					ClerkNoticeToUser(T_INVALID_DATA);
			}
		}
		// F4
		// [#2335] NH Justin 2015.03.12 Implement Percentage Surcharge Notice
		//else if (m_OpInfo.strReturn == _T("LOCATION"))
		//{
		//	if (MemGetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_SURCHARGE_WARNINGLOCATION) == 1)
		//		MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_SURCHARGE_WARNINGLOCATION, 0);
		//	else
		//		MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_SURCHARGE_WARNINGLOCATION, 1);
		//}
		else if (m_OpInfo.strReturn == _T("PERCENTNOTICE"))
		{
			// KSK 2017.01.06 AU는 PERCENT만 지원하므로 변경함
			#if (AU_VERSION)
			// [#2354] US Justin 2015.07.01 Percentage Surcharge Notice
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PERCENT_SURCHARGE_NOTICE) == 1)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PERCENT_SURCHARGE_NOTICE, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PERCENT_SURCHARGE_NOTICE, 1);
			#else
			int nSurchargeNotice = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PERCENT_SURCHARGE_NOTICE) + 1;
			if( nSurchargeNotice > SURCHARGENOTICE_BOTH )
				nSurchargeNotice = SURCHARGENOTICE_AMOUNT;
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PERCENT_SURCHARGE_NOTICE, nSurchargeNotice);
			#endif		// end of KSK 2017.01.06
		}
		// end of [#2335]
		// F6
		else if (m_OpInfo.strReturn == L"WANNING_MANNAR")	// [iTM] KSK 2010.02.07 화면 Dat File 수정으로 인한 수정
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_MANNER) == LESSER)
				MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_MANNER, GREATER);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_MANNER, LESSER);
			//ClerkNoticeToUser(T_OPERATE_OK);
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			//m_OpInfo.nProcNextScrNum = 946;
			m_OpInfo.nProcNextScrNum = 960; //[#2136] NH PCS 2012.05.30
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
}
// end of [#112]

// [#2136] US/CA PCS 2012.05.30 "Surcharge Mode Added."
// [#2092] US PCS 2011.10.24
/*-------------------------------------------------------------------
CLASS    NAME: CMainFrame
FUNCTION NAME: ClerkAddTionalSurchargeOptionProc()
RETURN TYPE  : 
PARAMETER    : 
DESCRIPTION  : SCR 960 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkAddTionalSurchargeOptionProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));
	
	// 이곳에서 TerminalID 값을 Check한다.
	BOOL bCheckResultForTable = m_pDevCmn->IsValidSurchargeTable();				// [#2389] US Justin Change Function Name

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F8 Next Step
		if (m_OpInfo.strReturn == _T("NEXT_STEP"))
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_ENABLE) == PERCENT_MODE)
				m_OpInfo.nProcNextScrNum = 959;
			else if (MemGetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_ENABLE) == TABLE_MODE)
				m_OpInfo.nProcNextScrNum = 963; // 이 부분에서는 Table을 Enable한 경우.
			else
			{
				//nth to do.
			}
			break;
		}
		// F7 Mode Selection.
		else if (m_OpInfo.strReturn == _T("SURCHARGE_MODE"))
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_ENABLE) == NOT_USED)
			{
				MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_ENABLE,PERCENT_MODE);
			}
			else if (MemGetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_ENABLE) == PERCENT_MODE)
			{
				if (bCheckResultForTable == TRUE)
					MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_ENABLE,TABLE_MODE);
				else
					MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_ENABLE,NOT_USED);
			}
			else
			{
				MemSetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_PERSURCHARGE_ENABLE,NOT_USED);
			}
			m_OpInfo.strTempClerkMessage = T_OPERATE_OK;
			// end of [#725]
		}
		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		else if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			// [#2220] AU KMK 2013.10.31 호주 EMV. 호주는 945(ATM OPERATOR FEE MODE) 화면으로 돌아가야 됨
#if (AU_VERSION)
			m_OpInfo.nProcNextScrNum = 945;
#else
			m_OpInfo.nProcNextScrNum = 946;
#endif
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
		else
		{
			//nothing to do.
		}
	}//end of while
	NHDEBUG(DBG_CALL, (L"END\n"));
}

// end of [#2092] US PCS 2011.10.24
//end of [#2136]

/*-------------------------------------------------------------------
CLASS    NAME: CMainFrame
FUNCTION NAME: ClerkTableSurchargeOptionProc()
RETURN TYPE  : 
PARAMETER    : 
DESCRIPTION  : SCR 963 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkTableSurchargeOptionProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	BOOL bCheckResultForTable = TRUE; //Test.
	CString strTemp,strTemp2;
	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F8 Next Step
		if (m_OpInfo.strReturn == _T("PRINT_TABLE"))
		{
			if (m_pDevCmn->fnSPR_GetDeviceStatus() == NORMAL)
			{
				ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);

				CString strPrintData;
				SYSTEMTIME localTime;
				::GetLocalTime(&localTime);

				//////////////////////////////////////////////////////////////////////
				// Surcharge Table Print 부분.
				//////////////////////////////////////////////////////////////////////

				// [#2160] CA KMK 2012.11.15 French OP
				AddPrintData(strPrintData, L"========================================");
				AddPrintData(strPrintData, m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_017));
				AddPrintData(strPrintData, L"========================================");

				//				int	nYear, nMonth, nDay, nHour, nMinute, nSecond;
				AddPrintData(strPrintData, L"%-18.18s= %s %2.2d:%2.2d:%2.2d", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_002), GetCmnLocalDate(localTime.wMonth, localTime.wDay, localTime.wYear),
					localTime.wHour, localTime.wMinute, localTime.wSecond);

				CString strTerminal = MemGetStr(_MEM_FLD_APP_ATMINFO,_MEM_VAR_APP_TERMINALID);
				AddPrintData(strPrintData, L"%-18.18s= %s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_JNL_001), strTerminal);

				AddPrintData(strPrintData, L"----------------------------------------");
				AddPrintData(strPrintData, m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_018));
				AddPrintData(strPrintData, m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_019));
				AddPrintData(strPrintData, L"----------------------------------------");
				for (int PrintIndex= 9; PrintIndex < 19 ; PrintIndex++)
				{
					strTemp2.Format(L"%d", m_pDevCmn->m_nSurchTable[0][PrintIndex-9]);
					strTemp.Format(L"%s ~$%5.5s :%s $%s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_020), strTemp2, m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_021), MakeMoneyCent(Int2Asc(m_pDevCmn->m_nSurchTable[1][PrintIndex-9])));
					AddPrintData(strPrintData, strTemp);
				}
				// end of [#2160]

				// 정상일 경우 제외하고는 에러메시지 보임.
				m_OpInfo.m_strMsg = T_PRINTER_ERROR;

				if (m_pDevCmn->fnSPR_PrintReceipt(FALSE, strPrintData, K_1_WAIT) == TRUE)
					m_OpInfo.m_strMsg = T_OPERATE_OK;

				if (m_pDevCmn->fnSPR_GetDeviceStatus() != NORMAL)
					m_pDevCmn->fnAPL_ResetDevice(DEV_SPR);
			}
			else
				m_OpInfo.m_strMsg = T_PRINTER_ERROR;

			ClerkNoticeToUser(m_OpInfo.m_strMsg);
		}
		
		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		else if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 960;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
		else
		{
			//nothing to do.
		}
	}//end of while
	NHDEBUG(DBG_CALL, (L"END\n"));
}

// [#354] [CA] PSC 2008.7.2 Select Receipt Option Proc
/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkSelectReceiptOptionProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 915 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkSelectReceiptOptionProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// [#2166] NH KSK 2012.12.17
// 		if (m_OpInfo.strTempArray.GetSize() == 2 && m_OpInfo.strTempArray[0] == L"SELECTRECEIPT")
// 		{
// 			MemSetInt(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_SELECTRECEIPT, m_OpInfo.strTempArray[1] == L"ENABLE" ? 1 : 0);
// 		}
		if (m_OpInfo.strReturn == L"SELECTRECEIPT")
		{
			if (MemGetInt(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_SELECTRECEIPT) == ENABLE)
				MemSetInt(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_SELECTRECEIPT, 0);
			else
				MemSetInt(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_SELECTRECEIPT, ENABLE);
		}
		// [#2183] NH Justin 2013.04.05 Receipt on Screen Option
		else if (m_OpInfo.strReturn == L"RECEIPTONSCREEN")
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_RECEIPT_ON_SCREEN) == RECEIPT_ON_SCREEN_ENABLE)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_RECEIPT_ON_SCREEN, RECEIPT_ON_SCREEN_DISABLE);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_RECEIPT_ON_SCREEN, RECEIPT_ON_SCREEN_ENABLE);
		}
		// end of [#2166]
		// [#RWC6-290] US Brandon 2021.07.06 Support dual-language receipts
		else if (m_OpInfo.strReturn == L"DUALRECEIPT")
		{
			int nCurrentDualRecipt = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DUAL_RECEIPT);
			nCurrentDualRecipt++;

			int nCurrentDefaultLanguage = MemGetInt(_MEM_FLD_OPTIONALSETTING, _MEM_VAR_OPT_DEFAULT_LANGUAGE);
			
			if (nCurrentDualRecipt == nCurrentDefaultLanguage)
			{
				nCurrentDualRecipt++;
			}

			if (nCurrentDualRecipt == CHN_MODE)
			{
				if (!m_pDevCmn->fnSCR_IsFontLoaded(CHN_MODE-1))
				{
					nCurrentDualRecipt++;
				}
			}

			if (nCurrentDualRecipt == KOR_MODE)
			{
				if (!m_pDevCmn->fnSCR_IsFontLoaded(KOR_MODE-1))
				{
					nCurrentDualRecipt++;
				}
			}

			if (nCurrentDualRecipt == JPN_MODE)
			{
				if (!m_pDevCmn->fnSCR_IsFontLoaded(JPN_MODE-1))
				{
					nCurrentDualRecipt++;
				}
			}

			if (nCurrentDualRecipt > JPN_MODE)
			{
				nCurrentDualRecipt = 0;
			}

			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DUAL_RECEIPT, nCurrentDualRecipt);
		}
		// end of [#RWC6-290]

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 996;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
		
	} // end of while
	
	NHDEBUG(DBG_CALL, (L"END"));
}

// [iTM] US AIREAT 2009.11.27 OP Wizard
/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkQuickReplenish()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 701 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkQuickReplenish()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		if (m_OpInfo.strReturn == L"START")
		{
			CTime	CurTime = CTime::GetCurrentTime();

			m_QuickReplenishInfo.m_strStartTime.Format(L"%s %02.2d:%02.2d:%02.2d",
														GetCmnLocalDate(CurTime.GetMonth(), CurTime.GetDay(), CurTime.GetYear()),
														CurTime.GetHour(), CurTime.GetMinute(), CurTime.GetSecond());
			m_QuickReplenishInfo.m_strEndTime = L"";
			m_QuickReplenishInfo.m_strResultOfDayTotal = L"--";
			m_QuickReplenishInfo.m_strResultOfCstTotal = L"--";
			m_QuickReplenishInfo.m_strResultOfAddCash = L"--";

			m_OpInfo.nProcNextScrNum = 702;
			break;
		}
		else if (m_OpInfo.strReturn == L"BACK")
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 901;
			break;
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 901;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = 901;
			break;
		}
		
	} // end of while
	
	NHDEBUG(DBG_CALL, (L"END\n"));
}

/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkQuickDayTotal()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 702 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkQuickDayTotal()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	m_pDevCmn->fnAPL_EnDisableHotKey(DISABLE);

	ClerkScreenDisplay(m_OpInfo.nProcNextScrNum, m_OpInfo.nTimeout);

	OPERATION_RESULT eResult = ProcDayTotal(TRUE);

	if (eResult == OPERATION_NG)
	{
		CTime	CurTime = CTime::GetCurrentTime();

		m_QuickReplenishInfo.m_strEndTime.Format(L"%s %02.2d:%02.2d:%02.2d",
													GetCmnLocalDate(CurTime.GetMonth(), CurTime.GetDay(), CurTime.GetYear()),
													CurTime.GetHour(), CurTime.GetMinute(), CurTime.GetSecond());

		m_QuickReplenishInfo.m_strResultOfDayTotal = m_pDevCmn->fstrSCR_GetStringFromTextID(T_OPERATE_NG);
		m_OpInfo.nProcNextScrNum = 705;
	}
	else
	{
		if (eResult == OPERATION_OK)
			m_QuickReplenishInfo.m_strResultOfDayTotal = m_pDevCmn->fstrSCR_GetStringFromTextID(T_OPERATE_OK);
		else
			m_QuickReplenishInfo.m_strResultOfDayTotal = m_pDevCmn->fstrSCR_GetStringFromTextID(T_OPERATE_OK_SPRNG);

		m_OpInfo.nProcNextScrNum = 703;
	}

	NHDEBUG(DBG_CALL, (L"END\n"));
}

/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkQuickCassetteTotal()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 703 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkQuickCassetteTotal()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	m_pDevCmn->fnAPL_EnDisableHotKey(DISABLE);

	ClerkScreenDisplay(m_OpInfo.nProcNextScrNum, m_OpInfo.nTimeout);

	OPERATION_RESULT eResult = ProcCassetteTotal();

	if (eResult == OPERATION_OK)
	{
		m_QuickReplenishInfo.m_strResultOfCstTotal = m_pDevCmn->fstrSCR_GetStringFromTextID(T_OPERATE_OK);
		m_OpInfo.nProcNextScrNum = 704;
	}
	else if (eResult == OPERATION_OK_SPRNG)
	{
		m_QuickReplenishInfo.m_strResultOfCstTotal = m_pDevCmn->fstrSCR_GetStringFromTextID(T_OPERATE_OK_SPRNG);
		m_OpInfo.nProcNextScrNum = 704;
	}
	else if (eResult == OPERATION_NG_CDUNG)
	{
		CTime	CurTime = CTime::GetCurrentTime();

		m_QuickReplenishInfo.m_strEndTime.Format(L"%s %02.2d:%02.2d:%02.2d",
													GetCmnLocalDate(CurTime.GetMonth(), CurTime.GetDay(), CurTime.GetYear()),
													CurTime.GetHour(), CurTime.GetMinute(), CurTime.GetSecond());

		m_QuickReplenishInfo.m_strResultOfCstTotal = m_pDevCmn->fstrSCR_GetStringFromTextID(T_CDU_ERROR);
		m_OpInfo.nProcNextScrNum = 705;
	}
	else
	{
		CTime	CurTime = CTime::GetCurrentTime();

		m_QuickReplenishInfo.m_strEndTime.Format(L"%s %02.2d:%02.2d:%02.2d",
													GetCmnLocalDate(CurTime.GetMonth(), CurTime.GetDay(), CurTime.GetYear()),
													CurTime.GetHour(), CurTime.GetMinute(), CurTime.GetSecond());
		m_QuickReplenishInfo.m_strResultOfCstTotal = m_pDevCmn->fstrSCR_GetStringFromTextID(T_OPERATE_NG);
		m_OpInfo.nProcNextScrNum = 705;
	}

	NHDEBUG(DBG_CALL, (L"END\n"));
}

/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkQuickAddCash()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 704 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkQuickAddCash()
{
	NHDEBUG(DBG_CALL, (L"START\n"));
	{

		// clear input value
		m_OpInfo.m_UserInputValue[0] = L"";
		m_OpInfo.m_UserInputValue[1] = L"";
		m_OpInfo.m_UserInputValue[2] = L"";
		m_OpInfo.m_UserInputValue[3] = L"";

		while(TRUE)
		{
			NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

			///////////////////////////////////
			// WAIT FOR USER INPUT
			ClerkWaitScreenInput_byCha();
			m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

			NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

			//-----------------------------------
			// PROCESS KEY STRING
			//-----------------------------------
			// F1
			if (m_OpInfo.strReturn == L"1CST")
			{
				if (ClerkInputNumber(L"912F1T", L"912F1S", m_pDevCmn->fstrAPL_ClerkInformationMake(300), EDIT_NORMAL, 4, m_OpInfo.strReturn) == TRUE)
				{
					NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));
					if (IsNum(m_OpInfo.strReturn) == TRUE)
						m_OpInfo.m_UserInputValue[0] = m_OpInfo.strReturn;
					else
						ClerkNoticeToUser(T_INVALID_DATA);
				}
			}
			// F3
			else if (m_OpInfo.strReturn == L"2CST")
			{
				if (ClerkInputNumber(L"912F3T", L"912F1S", m_pDevCmn->fstrAPL_ClerkInformationMake(301), EDIT_NORMAL, 4, m_OpInfo.strReturn) == TRUE)
				{
					NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));
					if (IsNum(m_OpInfo.strReturn) == TRUE)
						m_OpInfo.m_UserInputValue[1] = m_OpInfo.strReturn;
					else
						ClerkNoticeToUser(T_INVALID_DATA);
				}
			}
			// F5
			else if (m_OpInfo.strReturn == L"3CST")
			{
				if (ClerkInputNumber(L"912F5T", L"912F1S", m_pDevCmn->fstrAPL_ClerkInformationMake(302), EDIT_NORMAL, 4, m_OpInfo.strReturn) == TRUE)
				{
					NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));
					if (IsNum(m_OpInfo.strReturn) == TRUE)
						m_OpInfo.m_UserInputValue[2] = m_OpInfo.strReturn;
					else
						ClerkNoticeToUser(T_INVALID_DATA);
				}
			}
			// F7
			else if (m_OpInfo.strReturn == L"4CST")
			{
				if (ClerkInputNumber(L"912F7T", L"912F1S", m_pDevCmn->fstrAPL_ClerkInformationMake(303), EDIT_NORMAL, 4, m_OpInfo.strReturn) == TRUE)
				{
					NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));
					if (IsNum(m_OpInfo.strReturn) == TRUE)
						m_OpInfo.m_UserInputValue[3] = m_OpInfo.strReturn;
					else
						ClerkNoticeToUser(T_INVALID_DATA);
				}
			}
			// F8
			else if (m_OpInfo.strReturn.Left(7) == L"ADDCASH")
			{
				BOOL	bExit = FALSE;
				ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);

				SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);
				OPERATION_RESULT	eResult = ProcAddCash(m_OpInfo.strTempArray, 0);

				if (eResult == OPERATION_OK)
				{
					m_QuickReplenishInfo.m_strResultOfAddCash = T_OPERATE_OK;
					bExit = TRUE;
				}
				else if (eResult == OPERATION_OK_SPRNG)
				{
					m_QuickReplenishInfo.m_strResultOfAddCash = T_OPERATE_OK_SPRNG;
					bExit = TRUE;
				}
				else if (eResult == OPERATION_NG_CDUNG)
				{
					m_QuickReplenishInfo.m_strResultOfAddCash = T_CDU_ERROR;
					bExit = TRUE;
				}
				else if (eResult == OPERATION_NG_DATANG)
				{
					m_OpInfo.m_strMsg = T_INVALID_DATA;
				}
				else if (eResult == OPERATION_NG_INSERTOVER)
				{
					m_OpInfo.m_strMsg = T_INSERT_OVER;
				}
				else if (eResult == OPERATION_NG_DENOM)
				{
					m_QuickReplenishInfo.m_strResultOfAddCash = T_DENOMINATION_ERROR;
					bExit = TRUE;
				}
				else
				{
					m_QuickReplenishInfo.m_strResultOfAddCash = T_OPERATE_NG;
					bExit = TRUE;
				}

				// clear input value
				m_OpInfo.m_UserInputValue[0] = L"";
				m_OpInfo.m_UserInputValue[1] = L"";
				m_OpInfo.m_UserInputValue[2] = L"";
				m_OpInfo.m_UserInputValue[3] = L"";

				if (bExit == FALSE)
					ClerkNoticeToUser(m_OpInfo.m_strMsg);
				else
				{
					CTime	CurTime = CTime::GetCurrentTime();
					m_QuickReplenishInfo.m_strEndTime.Format(L"%s %02.2d:%02.2d:%02.2d",
						GetCmnLocalDate(CurTime.GetMonth(), CurTime.GetDay(), CurTime.GetYear()),
						CurTime.GetHour(), CurTime.GetMinute(), CurTime.GetSecond());
					m_OpInfo.nProcNextScrNum = 705;
					break;
				}
			}
			// [#2504] US Justin 2017.09.11 
			// F2
			else if (m_OpInfo.strReturn == L"TESTDISPENSE")
			{
				// clear input value
				m_OpInfo.m_UserInputValue[0] = L"";
				m_OpInfo.m_UserInputValue[1] = L"";
				m_OpInfo.m_UserInputValue[2] = L"";
				m_OpInfo.m_UserInputValue[3] = L"";

				ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);

				OPERATION_RESULT eResult = ProcOPTestDispensing();
				if (eResult == OPERATION_OK)	m_OpInfo.m_strMsg = T_OPERATE_OK;
				else							m_OpInfo.m_strMsg = T_OPERATE_NG;
				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}
			// End of [#2504]

			//-----------------------------------
			// COMMON PROCESS
			//-----------------------------------
			if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
			{
				CTime	CurTime = CTime::GetCurrentTime();

				m_QuickReplenishInfo.m_strEndTime.Format(L"%s %02.2d:%02.2d:%02.2d",
					GetCmnLocalDate(CurTime.GetMonth(), CurTime.GetDay(), CurTime.GetYear()),
					CurTime.GetHour(), CurTime.GetMinute(), CurTime.GetSecond());

				m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;				// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
				m_OpInfo.nProcNextScrNum = 705;
				break;
			}
			else if (m_OpInfo.strReturn == S_TIMEOVER)
			{
				CTime	CurTime = CTime::GetCurrentTime();

				m_QuickReplenishInfo.m_strEndTime.Format(L"%s %02.2d:%02.2d:%02.2d",
					GetCmnLocalDate(CurTime.GetMonth(), CurTime.GetDay(), CurTime.GetYear()),
					CurTime.GetHour(), CurTime.GetMinute(), CurTime.GetSecond());

				m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;			// [#236] NZ AIREAT 2008.05.27 OP Screen Timeout
				m_OpInfo.nProcNextScrNum = 705;
				break;
			}

		} // end of while
	}

	NHDEBUG(DBG_CALL, (L"END\n"));
}

/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkQuickResult()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 705 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkQuickResult()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		if (m_OpInfo.strReturn == L"CONFIRM")
		{
			m_OpInfo.nProcNextScrNum = 901;
			break;
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = 901;
			break;
		}
		
	} // end of while
	
	NHDEBUG(DBG_CALL, (L"END\n"));
}
// end of [iTM] OP Wizard

