		//-----------------------------------
		if (m_OpInfo.strReturn == L"PREV")
		{
			if (MemGetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_NETWORKTYPE) == NETWORK_DIALUP)		// Dialup
				m_OpInfo.nProcNextScrNum = 714;		// Communication
			else																	// TCP/IP
				m_OpInfo.nProcNextScrNum = 715;		// TCP/IP Type
			break;
		}
		else if (m_OpInfo.strReturn == L"NEXT")
		{
			if (MemGetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_NETWORKTYPE) == NETWORK_DIALUP)		// Dialup
				m_OpInfo.nProcNextScrNum = 718;		// Host Phone Number
			else																	// TCP/IP
				m_OpInfo.nProcNextScrNum = 720;		// Host Address
			break;
		}
		// [#2166] NH KSK 2012.12.17
//		else if ((m_OpInfo.strTempArray[0] == L"FLOW_CONTROL_TYPE") && (m_OpInfo.strTempArray.GetSize() == 2))
//		{
