//			else if (m_OpInfo.strTempArray[1] == L"EOT_OPTIONAL")
//				MemSetStr(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_EOTCHECKMODE, EOT_OPTIONAL	);
//			else if (m_OpInfo.strTempArray[1] == L"ENQ_EOT_NOT_USED")									//[#2000] SOOK 2010.09.26 호주 작업 
//				MemSetStr(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_EOTCHECKMODE, NO_ENQ_EOT_REQUIRED	);//[#2000] SOOK 2010.09.26 호주 작업 
