/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkQuickHostIpSetupProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 720 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkQuickHostIpSetupProc()	
{
	NHDEBUG(DBG_CALL, (L"START\n"));
	
	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		if (m_OpInfo.strReturn == L"PREV")
		{
			if (MemGetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_TYPE) == VISA_FRAMED_TCPIP)	// TCP/ IP VISA FRAMED
				m_OpInfo.nProcNextScrNum = 716;		// EOT/ENQ Option
			else
				m_OpInfo.nProcNextScrNum = 715;		// TCP/IP TYPE
			break;
		}
		else if (m_OpInfo.strReturn == L"NEXT")
		{
			m_OpInfo.nProcNextScrNum = 723;		// ATM DHCP Setting
			break;
		}
		// [#2166] NH KSK 2012.12.17
//		else if ((m_OpInfo.strTempArray[0] == L"HOST_URL_USE") && (m_OpInfo.strTempArray.GetSize() >= 2))
//		{
//			MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_ISHOSTUSEURL, m_OpInfo.strTempArray[1] == L"ENABLE" ? 1 : 0);
//		}
		else if (m_OpInfo.strReturn == L"HOST_URL_USE")
		{
			if (MemGetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_ISHOSTUSEURL) == ENABLE)
				MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_ISHOSTUSEURL, 0);
			else
				MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_ISHOSTUSEURL, ENABLE);
		}
		// end of [#2166]

		// F2
		else if (m_OpInfo.strReturn == L"HOSTADDRESS1")
		{
			BOOL bRes;
			CString strValue;
			strValue = MemGetStr(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_HOST1NAME);
			
			if (MemGetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_ISHOSTUSEURL) == 1)
				bRes = ClerkInputAlpha(L"980F2T", strValue, 1, 40, m_OpInfo.strReturn);
			else
				bRes = ClerkInputNumber(L"980F2T", L"", strValue, EDIT_NORMAL, 15, m_OpInfo.strReturn);

			if (bRes == TRUE)
			{
				CString strtemp;
				
				strtemp = m_OpInfo.strReturn;
				strtemp.TrimLeft();
				strtemp.TrimRight();

				if (strtemp.GetLength() <= 0)
				{
					MemSetStr(_MEM_FLD_TCPIPINFO,_MEM_VAR_TCPIP_HOST1NAME, L"");
					m_OpInfo.m_strMsg = T_OPERATE_OK;
				}
				else
				{
					// URL이 아닌 경우에만 Check한다.
					if (MemGetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_ISHOSTUSEURL) == 0)
					{
						if (CheckValidate_IPValue(strtemp) == TRUE)
						{
							MemSetStr(_MEM_FLD_TCPIPINFO,_MEM_VAR_TCPIP_HOST1NAME, m_pDevCmn->Convert_IpAddressInfo(strtemp));
								
							if (MemGetStr(_MEM_FLD_TCPIPINFO,_MEM_VAR_TCPIP_HOST2NAME).GetLength() == 0)
								MemSetStr(_MEM_FLD_TCPIPINFO,_MEM_VAR_TCPIP_HOST2NAME, m_pDevCmn->Convert_IpAddressInfo(strtemp));
							
							m_OpInfo.m_strMsg = T_OPERATE_OK;
						}
						else
							m_OpInfo.m_strMsg = T_INVALID_DATA;
					}
					else
					{
						MemSetStr(_MEM_FLD_TCPIPINFO,_MEM_VAR_TCPIP_HOST1NAME, strtemp);

						if (MemGetStr(_MEM_FLD_TCPIPINFO,_MEM_VAR_TCPIP_HOST2NAME).GetLength() == 0)
							MemSetStr(_MEM_FLD_TCPIPINFO,_MEM_VAR_TCPIP_HOST2NAME, strtemp);

						m_OpInfo.m_strMsg = T_OPERATE_OK;
					}
				}

				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}
		}
		// F4
		else if (m_OpInfo.strReturn == L"PORTNUMBER1")
		{
			CString strValue;
			strValue.Format(L"%d", MemGetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_HOST1PORTNO));
			if (ClerkInputNumber(L"980F6T", L"", strValue, EDIT_NORMAL, 5, m_OpInfo.strReturn) == TRUE)
			{
				if (IsNum(m_OpInfo.strReturn) == TRUE)
				{
					int	nPortNum = Asc2Int(m_OpInfo.strReturn);

					if ((nPortNum >= 0) && (nPortNum < 65536))
					{
						MemSetInt(_MEM_FLD_TCPIPINFO,_MEM_VAR_TCPIP_HOST1PORTNO, nPortNum);

						if (nPortNum != 0 && MemGetInt(_MEM_FLD_TCPIPINFO,_MEM_VAR_TCPIP_HOST2PORTNO) == 0)
							MemSetInt(_MEM_FLD_TCPIPINFO,_MEM_VAR_TCPIP_HOST2PORTNO, nPortNum);

						m_OpInfo.m_strMsg = T_OPERATE_OK;
					}
					else
						m_OpInfo.m_strMsg = T_INVALID_DATA;
				}
				else
					m_OpInfo.m_strMsg = T_INVALID_DATA;

				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 713;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
}

