// [#2292] US Justin 2014.09.17
/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkTDLOptionSetupProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 749 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkTDLOptionSetupProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	m_OpInfo.nMoveProcReason = MOVE_PROC_SELECT;
	
	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F1
		if (m_OpInfo.strReturn == _T("DUALBALANCE"))
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_DUALBALANCE) == ENABLE)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_DUALBALANCE, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_DUALBALANCE, ENABLE);
		}
		// F2
		else if (m_OpInfo.strReturn == _T("DYNAMICSURCHARGE"))
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_TIRSURCHARGE) == ENABLE)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_TIRSURCHARGE, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_TIRSURCHARGE, ENABLE);
		}
		// F3
		else if (m_OpInfo.strReturn == _T("CURRENCYCONVERSION"))
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_DCC) == ENABLE)
			{
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_DCC, 0);
			}
			else
			{
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_DCC, ENABLE);
#if (APP_CUSTOM_CIBC_MX)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DCC_CUSTOMOPTION, DCC_CUSTOMOPTION_BANSI);
#endif
			}
		}
		// F4
		else if (m_OpInfo.strReturn == _T("CREDITSURCHARGE"))
		{
			CString strAmount;
			strAmount.Format(L"%d",Asc2Int(MemGetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_CREDITSURCHARGE)));

			if (ClerkInputNumber(L"749F4T", L"", strAmount, EDIT_CENT, 5, m_OpInfo.strReturn) == TRUE)
			{
				NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));
				if( (IsNum(m_OpInfo.strReturn)==TRUE) || (IsZero(m_OpInfo.strReturn)==TRUE) )
				{
					strAmount.Format(L"%d", Asc2Int(m_OpInfo.strReturn));
					MemSetStr(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_CREDITSURCHARGE, strAmount);

					ClerkNoticeToUser(T_OPERATE_OK);
				}
				else
					ClerkNoticeToUser(T_INVALID_DATA);
			}
		}
		// [#2437] Supporting Cardtronics ALLPOINT Surcharge Notice
		// F5
		else if (m_OpInfo.strReturn == _T("ALLPOINTSURCHARGE"))
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_SURCHARGE) == ENABLE)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_SURCHARGE, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_SURCHARGE, ENABLE);
		}
		// End of [#2437]

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 795;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}		
	} // end of while
	
	NHDEBUG(DBG_CALL, (L"END\n"));
}
// End of [#2292]
#endif

