/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkHalCashSetupProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 759 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkHalCashSetupProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	m_OpInfo.nMoveProcReason = MOVE_PROC_SELECT;
	
	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F1
		if (m_OpInfo.strReturn == _T("ENABLEHALCASH"))
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PIN4_ENABLE) == ENABLE)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PIN4_ENABLE, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PIN4_ENABLE, ENABLE);
		}
		//[#J003] US Justin 2018.11.12 Mastercard Cash Pickup - Add OP Menu for removing Sym Key, Add an indicator for Sym Key Existance
		// F3
		if (m_OpInfo.strReturn == _T("REMOVE_SYMKEY"))
		{
			if (ClerkConfirm(L"759F3S", m_OpInfo.strReturn) == TRUE)
			{
				m_pTranCmn->m_Pin4.RemoveDownloadCredentials();
				ClerkNoticeToUser(T_OPERATE_OK);
			}
		}
		// End of [#J003]
		// [#2455] US Justin Edit HALCASH Host Information Locally
		// [#2554] US Justin 2018.06.06 Setup other MC Cash Pick up information
		// F2 or F6
		else if( (m_OpInfo.strReturn == _T("HALCASH_HOST_AUTHN")) || (m_OpInfo.strReturn == _T("HALCASH_HOST_AUTHO")) )
		{
			CString strValue = m_pTranCmn->m_Pin4.m_strHostIP;
			if(m_OpInfo.strReturn == _T("HALCASH_HOST_AUTHN"))	strValue = m_pTranCmn->m_Pin4.m_strAuthHostIP;
				
			CString strEditTitle = L"759F6T";
			if(m_OpInfo.strReturn == _T("HALCASH_HOST_AUTHN"))	strEditTitle = L"759F2T";

			if (ClerkInputAlpha(strEditTitle, strValue, 1, 40, m_OpInfo.strReturn) == TRUE)
			{
				CString strtemp = m_OpInfo.strReturn;
				strtemp.TrimLeft();				
				strtemp.TrimRight();

				if (strtemp.GetLength() <= 0)
					m_OpInfo.m_strMsg = T_OPERATE_NG;
				else
				{
					if(strEditTitle == L"759F2T")			m_pTranCmn->m_Pin4.m_strAuthHostIP = strtemp ;
					else									m_pTranCmn->m_Pin4.m_strHostIP = strtemp ;

					if( m_pTranCmn->m_Pin4.SavePin4Setting() )
						m_OpInfo.m_strMsg = T_OPERATE_OK;
					else
					{
						if(strEditTitle == L"759F2T")		m_pTranCmn->m_Pin4.m_strAuthHostIP = strValue;
						else								m_pTranCmn->m_Pin4.m_strHostIP = strValue;					
						m_OpInfo.m_strMsg = T_OPERATE_NG;
					}
				}
				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}
		}
		// F4 or F8
		else if( (m_OpInfo.strReturn == _T("HALCASH_PORT_AUTHN")) || (m_OpInfo.strReturn == _T("HALCASH_PORT_AUTHO")) )
		{
			CString strValue = m_pTranCmn->m_Pin4.m_strHostPort;
			if(m_OpInfo.strReturn == _T("HALCASH_PORT_AUTHN"))	strValue = m_pTranCmn->m_Pin4.m_strAuthHostPort;

			CString strEditTitle = L"759F8T";
			if(m_OpInfo.strReturn == _T("HALCASH_PORT_AUTHN"))	strEditTitle = L"759F4T";

			if (ClerkInputNumber(strEditTitle, L"", strValue, EDIT_NORMAL, 5, m_OpInfo.strReturn) == TRUE)
			{
				long nNewNum = Asc2Int(m_OpInfo.strReturn);
				if (nNewNum <= 0)
					m_OpInfo.m_strMsg = T_OPERATE_NG;
				else
				{
					if(strEditTitle == L"759F4T")			m_pTranCmn->m_Pin4.m_strAuthHostPort.Format(L"%ld", nNewNum);
					else									m_pTranCmn->m_Pin4.m_strHostPort.Format(L"%ld", nNewNum);

					if( m_pTranCmn->m_Pin4.SavePin4Setting() )
						m_OpInfo.m_strMsg = T_OPERATE_OK;
					else
					{

						if(strEditTitle == L"759F4T")		m_pTranCmn->m_Pin4.m_strAuthHostPort = strValue;
						else								m_pTranCmn->m_Pin4.m_strHostPort = strValue;					
						m_OpInfo.m_strMsg = T_OPERATE_NG;
					}
				}
				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}
		}
		/*
		// F6
		else if (m_OpInfo.strReturn == _T("HALCASH_WITHAMT"))
		{
			CString strValue = m_pTranCmn->m_Pin4.m_strMaxDispenseLimit;
			if (ClerkInputNumber(L"759F6T", L"", strValue, EDIT_NORMAL, 4, m_OpInfo.strReturn) == TRUE)
			{
				long nNewNum = Asc2Int(m_OpInfo.strReturn);
				if (nNewNum < 20)
					m_OpInfo.m_strMsg = T_OPERATE_NG;
				else
				{
					m_pTranCmn->m_Pin4.m_strMaxDispenseLimit.Format(L"%ld", nNewNum);
					if( m_pTranCmn->m_Pin4.SavePin4Setting() )
						m_OpInfo.m_strMsg = T_OPERATE_OK;
					else
					{
						m_pTranCmn->m_Pin4.m_strMaxDispenseLimit = strValue;
						m_OpInfo.m_strMsg = T_OPERATE_NG;
					}
				}
				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}
		}
		*/
		// End of [#2554]
		// End of [#2455]

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 795;		// [#2471] US Justin 2017.02.01 Combine setup
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
		
	} // end of while
	NHDEBUG(DBG_CALL, (L"END\n"));
}
// End of [#2396]
#endif
