// [#2535] US Justin 2018.03.20 GivePay Online
#if (APP_GPAY_GIFTCARD_PURCHASE)
/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkGivePaySetupProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 748 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkGivePaySetupProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));
	m_OpInfo.nMoveProcReason = MOVE_PROC_SELECT;

	// generate QR code here
	ClerkGivePayGenerateQRCode();
	
	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT

		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F1
		if (m_OpInfo.strReturn == _T("ENABLEGIVEPAY"))
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_GIVEPAY_ENABLE_DISABLE) == ENABLE)
			{
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_GIVEPAY_ENABLE_DISABLE, 0);
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_GIVEPAY_UPSELL, GIVEPAY_APPEAR_BOTH);	// Default = 0 = BOTH	// [#RWC6-1]
			}
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_GIVEPAY_ENABLE_DISABLE, ENABLE);
		}
		// F2
		else if (m_OpInfo.strReturn == _T("REGISTERGIVEPAY"))
		{
			ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);			
			if( m_pTranCmn->P_NH_GivePay_DownloadData(GPAY_DOWNLOAD_OP_ENROLL) == RES_OK)	m_OpInfo.m_strMsg = T_OPERATE_OK;
			else																			m_OpInfo.m_strMsg = T_OPERATE_NG;
			ClerkNoticeToUser(m_OpInfo.m_strMsg);
		}
		// F3
		else if (m_OpInfo.strReturn == _T("RESETIMAGES"))
		{
			if (ClerkConfirm(L"748F3S", m_OpInfo.strReturn) == TRUE)
			{
				ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);	
				if( m_pTranCmn->m_GivePayData.ResetImageFiles() )				m_OpInfo.m_strMsg = T_OPERATE_OK;
				else															m_OpInfo.m_strMsg = T_OPERATE_NG;
				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}
		}		
		// F4		// [#J006] US Justin GivePay Enhancement5, Add Upsell Option
		else if (m_OpInfo.strReturn == _T("UPSELL_OPTION"))
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_GIVEPAY_UPSELL) == GIVEPAY_APPEAR_INDIVIDUAL)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_GIVEPAY_UPSELL, GIVEPAY_APPEAR_PIGGYBACK);
			else if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_GIVEPAY_UPSELL) == GIVEPAY_APPEAR_PIGGYBACK)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_GIVEPAY_UPSELL, GIVEPAY_APPEAR_BOTH);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_GIVEPAY_UPSELL, GIVEPAY_APPEAR_INDIVIDUAL);
		}			// End of [#J006]
		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nProcNextScrNum = 795;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
		
	} // end of while
	NHDEBUG(DBG_CALL, (L"END\n"));
}
// End of [#2535]

// [#RWC6-44] GivePay AutoEnrollment QR Code Display
void	CMainFrame::ClerkGivePayGenerateQRCode()
{	
	NVDump('O', 'C', "00", L"P_NHNOR", L"GPayGenerateQRCode");
	NHDEBUG(DBG_CALL, (L"[CMainFrame::ClerkGivePayGenerateQRCode]\n"));

	const __int64 UNIX_TIME_START = 116444736000000000; //January 1, 1970 (start of Unix epoch) in "ticks" // A Windows tick is 100 nanoseconds. Windows epoch 1601-01-01T00:00:00Z, 11644473600 seconds before Unix epoch 1970-01-01T00:00:00Z.
	const __int64 TICKS_PER_MILLISECOND = 10000; //a tick is 100ns

	// QREncode Generator Parameter
	CString strLightenedPrintData, strTempLine;
	CString strFieldDelimiter = _T("");
	CString strQRDelimiter = _T(";");
	CString sTaeURL = _T("");
	CString	sTID = _T("");
	CString	sIAT = _T("");
	CString sTaeKey = _T("");
	CString	sSIG = _T("");
	CString	strTemp = _T("");
	unsigned long long int nTempTime = 0;
	FILETIME ft;
	long nLenTaeKey = 0;
	
	strFieldDelimiter.Format(L"%c", FIELD_DELIMITER);
	
	// QR Code Format Version
	strLightenedPrintData = _T("");					// GivePay asked not to add initial version number on this

	// Inputs: TaeURL
	sTaeURL.Format(L"%s", m_pTranCmn->m_GivePayData.m_strTaeURL);

	// Inputs: Terminal ID
	strTemp.Format(L"%s", MemGetStr(_MEM_FLD_APP_ATMINFO,_MEM_VAR_APP_TERMINALID));
	sTID.Format(L"%s",strTemp.TrimRight());

	// Inputs: TaeKey
	sTaeKey.Format(L"%s", m_pTranCmn->m_GivePayData.m_strTaeKey);

	// Inputs: IAT
	GetSystemTimeAsFileTime(&ft);
	ULARGE_INTEGER li;
	li.LowPart  = ft.dwLowDateTime;		//Copy the low and high parts of FILETIME into a LARGE_INTEGER
	li.HighPart = ft.dwHighDateTime;
    nTempTime = (li.QuadPart - UNIX_TIME_START) / TICKS_PER_MILLISECOND;	//Convert ticks since 1/1/1970 into seconds
	sIAT.Format(L"%llu", nTempTime);

	// Output: signature of IAT using TaeKey
	unsigned char *pTaeKey = (unsigned char *) sTaeKey.GetBuffer(0);
	sTaeKey.ReleaseBuffer();
	sSIG = Encrypt_And_Base64Encode(sIAT, (unsigned char*)pTaeKey, 2);
	delete [] pTaeKey;

	// convert to URL friendly sSIG
	sSIG.Replace('+','.');
	sSIG.Replace('/','_');
	sSIG.Replace('=','-');

	if (sTaeURL.GetLength() <= 0){
		sTaeURL.Format(L"TaeURL_Missing");
	}
	if (sTID.GetLength() <= 0){
		sTID.Format(L"TID_Missing");
	}
	if (sIAT.GetLength() <= 0){
		sIAT.Format(L"IAT_Missing");
	}
	if (sSIG.GetLength() <= 0){
		sSIG.Format(L"SIG_Missing");
	}

	strTemp.Format(L"https://%s/enroll?tid=%s&iat=%s&sig=%s", sTaeURL, sTID, sIAT, sSIG);
	strLightenedPrintData += strTemp;

	NHDEBUG(DBG_INFO, (L"GivePay AutoEnrollment QR Code = [%s]\n", strTemp));

	// Delete Existing QR Image
	DeleteFile(GPAY_QR_AUTOENROLL_IMAGEFILE);


	MakeQRCodeImageFile(strLightenedPrintData, GPAY_QR_AUTOENROLL_IMAGEFILE);
	NHDEBUG(DBG_CALL, (L"[CMainFrame::ClerkGivePayGenerateQRCode] Success!\n"));
}
// end of [#RWC6-44]
#endif

// [#2446] US Justin 2016.09.29 Add Paypal CCA Setup
#if (US_VERSION)
/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkPaypalCCASetupProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 762 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkPaypalCCASetupProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	m_OpInfo.nMoveProcReason = MOVE_PROC_SELECT;
	
	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F1
		if (m_OpInfo.strReturn == _T("ENABLEPAYPALCCA"))
		{
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PAYDIANT_CCA_ENABLE) == ENABLE)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PAYDIANT_CCA_ENABLE, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PAYDIANT_CCA_ENABLE, ENABLE);
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nProcNextScrNum = 795;		// [#2471] US Justin 2017.02.01 Combine setup
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
		
	} // end of while
	NHDEBUG(DBG_CALL, (L"END\n"));
}
#endif
// End of [#2446]

