/*-------------------------------------------------------------------
CLASS    NAME: CMainFrame
FUNCTION NAME: ClerkRMSRingCountProc()
RETURN TYPE  : 
PARAMETER    : 
DESCRIPTION  : SCR 815 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkRMSRingCountProc()	
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// [#2166] NH KSK 2012.12.17
		// F1
// 		if (m_OpInfo.strTempArray[0] == L"RMS" && m_OpInfo.strTempArray.GetSize() == 2)
// 		{
// 			if(m_OpInfo.strTempArray[1] == L"ENABLE")
// 				MemSetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_RMSFLAG, 1);
// 			else
// 			{
// 				MemSetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_RMSFLAG, 0);
// 				MemSetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_RMSSTATUSSEND, 0);
// 			}
// 		}
		if (m_OpInfo.strReturn == L"RMS")
		{
			if(MemGetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_RMSFLAG) == ENABLE)
			{
				MemSetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_RMSFLAG, 0);
				MemSetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_RMSSTATUSSEND, 0);
			}
			else
			{
				MemSetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_RMSFLAG, ENABLE);
			}
		}
		// end of [#2166]
		// F2
		else if (m_OpInfo.strTempArray[0] == L"RMSRINGCOUNT")
		{
			CString strValue;
			strValue.Format(L"%d", MemGetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_RMSRINGCNT));

			if (ClerkInputNumber(L"815F2T", L"", strValue, EDIT_NORMAL, 1, m_OpInfo.strReturn) == TRUE)
			{
				m_OpInfo.m_strMsg = T_INVALID_DATA;

				// Check Numeric
				if (IsNum(m_OpInfo.strReturn) == TRUE)
				{
					int nRingCount = Asc2Int(m_OpInfo.strReturn);

					if (nRingCount > 0 && nRingCount < 8)	// RMS RING COUNT는 1~7회까지 입력 가능하다.(Modem 제약사항)
					{
						MemSetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_RMSRINGCNT, nRingCount);
						m_OpInfo.m_strMsg = T_OPERATE_OK;
					}
				}

				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 965;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
}

// [#508] NH AIREAT 2008.03.02 JNL SEARCH BY DATE
/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkSearchJournalbyDateProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 816 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkSearchJournalbyDateProc()
{
#define	NO_SEARCH_DATE	L"FROM ---------- TO ----------"

	NHDEBUG(DBG_CALL, (L"START"));

	m_OpInfo.strFromToDateScreen = NO_SEARCH_DATE;
	m_OpInfo.strFromToDateFile = _T("");
	m_OpInfo.strJNLSearchResult.RemoveAll();
	
	m_OpInfo.m_UserInputValue[0] = L"";
	m_OpInfo.m_UserInputValue[1] = L"";

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F1
		if (m_OpInfo.strReturn == L"FROM")
		{
			if (ClerkInputNumber(L"816F1T", L"816003", m_OpInfo.m_UserInputValue[0], EDIT_DATE, 10, m_OpInfo.strReturn) == TRUE)
			{
				int nYear=0, nMonth=0, nDay = 0;
//				GetCmnLocalDate(m_OpInfo.strReturn, &nYear, &nMonth, &nDay);
				GetCmnLocalDate(m_OpInfo.strReturn, &nMonth, &nDay, &nYear);	// [#11] NH KSK 2010.09.30 Bug Fix

				NHDEBUG(DBG_INFO, (L"YEAR[%d] MONTH[%d] DAY[%d] [%s]\n", nYear, nMonth, nDay, m_OpInfo.strReturn));

				if (IsValidDateTime(nMonth, nDay, nYear) != 0)
					m_OpInfo.m_UserInputValue[0] = m_OpInfo.strReturn;
				else
					ClerkNoticeToUser(T_INVALID_DATA);
			}
		}
		// F3
		else if (m_OpInfo.strReturn == L"TO")
		{
			if (ClerkInputNumber(L"816F3T", L"816003", m_OpInfo.m_UserInputValue[1], EDIT_DATE, 10, m_OpInfo.strReturn) == TRUE)
			{
				int nYear=0, nMonth=0, nDay = 0;
//				GetCmnLocalDate(m_OpInfo.strReturn, &nYear, &nMonth, &nDay);
				GetCmnLocalDate(m_OpInfo.strReturn, &nMonth, &nDay, &nYear);	// [#11] NH KSK 2010.09.30 Bug Fix

				if (IsValidDateTime(nMonth, nDay, nYear) != 0)
					m_OpInfo.m_UserInputValue[1] = m_OpInfo.strReturn;
				else
					ClerkNoticeToUser(T_INVALID_DATA);
			}
		}
		if (m_OpInfo.strReturn == L"SEARCH")
		{
			int sYear=0, sMonth=0, sDay=0;
			int eYear=0, eMonth=0, eDay=0;

			// check start Date
			GetCmnLocalDate(m_OpInfo.m_UserInputValue[0], &sMonth, &sDay, &sYear);
			GetCmnLocalDate(m_OpInfo.m_UserInputValue[1], &eMonth, &eDay, &eYear);

			m_OpInfo.m_strMsg = T_INVALID_DATA;

			// check validate of value
			if (IsValidDateTime(sMonth, sDay, sYear) != 0 &&
				IsValidDateTime(eMonth, eDay, eYear) != 0)
			{
				CTime	sDate(sYear, sMonth, sDay, 0, 0, 0);
				CTime	eDate(eYear, eMonth, eDay, 23, 59, 59);

				// check validate of range
				if (sDate <= eDate)
				{				
					// Inform to operator
					ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);

					m_OpInfo.strFromToDateScreen.Format(L"FROM %s TO %s", GetCmnLocalDate(sMonth, sDay, sYear), 
											 							   GetCmnLocalDate(eMonth, eDay, eYear));

					m_OpInfo.strFromToDateFile.Format(L"%s_%s", GetCmnLocalDate(sMonth, sDay, sYear, 0), 
											 				    GetCmnLocalDate(eMonth, eDay, eYear, 0));

					// search
					if (m_pDevCmn->m_JNLMgr.SearchByDate(sDate, eDate, m_OpInfo.strJNLSearchResult) == TRUE)
					{
						m_OpInfo.m_strMsg = T_OPERATE_OK;
					}
					else
					{
						m_OpInfo.strFromToDateScreen = NO_SEARCH_DATE;
						m_OpInfo.strFromToDateFile = _T("");
						m_OpInfo.strJNLSearchResult.RemoveAll();
						m_OpInfo.m_strMsg = T_NO_JNL_DATA;
					}
				}
			}
			else
			{
				m_OpInfo.m_UserInputValue[0] = L"";
				m_OpInfo.m_UserInputValue[1] = L"";
			}
			
			ClerkNoticeToUser(m_OpInfo.m_strMsg);
		}
		else if (m_OpInfo.strReturn == L"SAVETOUSB")
		{
			m_OpInfo.m_strMsg = T_NO_JNL_DATA;

			if (m_OpInfo.strJNLSearchResult.GetSize() > 0)
			{
				CString strTerminalID, strDestPath, strFullFileName;

				// Inform to operator
				ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);

				// Get terminalID
				strTerminalID = MemGetStr(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_TERMINALID);
				strTerminalID.TrimLeft();
				strTerminalID.TrimRight();

				// Get Path
				strDestPath.Format(_T("%s\\%s"), LOGBACKUP_DEST_PATH, strTerminalID);
				CreateDirectory(strDestPath, NULL);
				strDestPath += L"\\JNL";
				CreateDirectory(strDestPath, NULL);

				strFullFileName.Format(_T("%s\\%s_%s.dat"), strDestPath, strTerminalID, m_OpInfo.strFromToDateFile);

				// Save Jnl
				if (m_pDevCmn->m_JNLMgr.SaveJNLData(strFullFileName, m_OpInfo.strJNLSearchResult))
				{
					m_OpInfo.strJNLSearchResult.RemoveAll();
					m_OpInfo.strFromToDateScreen.Empty();
					m_OpInfo.m_UserInputValue[0] = L"";
					m_OpInfo.m_UserInputValue[1] = L"";
					m_OpInfo.m_strMsg = T_OPERATE_OK;
				}
				else
					m_OpInfo.m_strMsg = T_OPERATE_NG;
			}

			ClerkNoticeToUser(m_OpInfo.m_strMsg);
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 846;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));

	// clear
	m_OpInfo.strFromToDateScreen = NO_SEARCH_DATE;
	m_OpInfo.strFromToDateFile = _T("");
	m_OpInfo.strJNLSearchResult.RemoveAll();
}
// end of [#508]

