/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkRejectAnalysisProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 818 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkRejectAnalysisProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		if (m_OpInfo.strReturn == _T("PRINT"))
		{
			if (m_pDevCmn->fnSPR_GetDeviceStatus() == NORMAL)
			{
				ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);
				
				CString strPrintData;
				SYSTEMTIME localTime;
				::GetLocalTime(&localTime);

				//////////////////////////////////////////////////////////////////////
				// 보정처리를 안할 경우 CST TOTAL과 문제가 됨
				// 보정처리를 하면 아래의 REJECT REASON에 문제가 됨 사양협의 필요함
				//////////////////////////////////////////////////////////////////////


				// [#2160] CA KMK 2012.11.15 French OP
				AddPrintData(strPrintData, L"========================================");
				AddPrintData(strPrintData, m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_026));
				AddPrintData(strPrintData, L"========================================");

				int	nYear, nMonth, nDay, nHour, nMinute, nSecond;
				GetRejTotalStartDate(&nYear, &nMonth, &nDay);
				GetRejTotalStartTime(&nHour, &nMinute, &nSecond);
				AddPrintData(strPrintData, L"%-18.18s= %s %02d:%02d:%02d", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_030), GetCmnLocalDate(nMonth, nDay, nYear), nHour, nMinute, nSecond); 
				AddPrintData(strPrintData, L"%-18.18s= %s %2.2d:%2.2d:%2.2d", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_002), GetCmnLocalDate(localTime.wMonth, localTime.wDay, localTime.wYear),
					localTime.wHour, localTime.wMinute, localTime.wSecond);

				CString strTerminal = MemGetStr(_MEM_FLD_APP_ATMINFO,_MEM_VAR_APP_TERMINALID);
				AddPrintData(strPrintData, L"%-18.18s= %s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_JNL_001), strTerminal);
				//AddPrintData(strPrintData, L" ");
				AddPrintData(strPrintData, L"----------------------------------------");
				AddPrintData(strPrintData, m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_JNL_004));
				AddPrintData(strPrintData, L"----------------------------------------");
				AddPrintData(strPrintData, L"%-18.18s:  %4.4s,%4.4s,%4.4s,%4.4s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_027), Int2Asc(GetSumOfDispensed(CDU_CST_1)),
					Int2Asc(GetSumOfDispensed(CDU_CST_2)),
					Int2Asc(GetSumOfDispensed(CDU_CST_3)),
					Int2Asc(GetSumOfDispensed(CDU_CST_4)));
				AddPrintData(strPrintData, L"%-18.18s:  %4.4s,%4.4s,%4.4s,%4.4s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_028), Int2Asc(GetSumOfRejected(CDU_CST_1)),
					Int2Asc(GetSumOfRejected(CDU_CST_2)),
					Int2Asc(GetSumOfRejected(CDU_CST_3)),
					Int2Asc(GetSumOfRejected(CDU_CST_4)));
				AddPrintData(strPrintData, L"----------------------------------------");
				AddPrintData(strPrintData, L"%-18.18s:  %4.4s,%4.4s,%4.4s,%4.4s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_029), Int2Asc(GetSumOfDetectedSkew(CDU_CST_1)),
					Int2Asc(GetSumOfDetectedSkew(CDU_CST_2)),
					Int2Asc(GetSumOfDetectedSkew(CDU_CST_3)),
					Int2Asc(GetSumOfDetectedSkew(CDU_CST_4)));
				AddPrintData(strPrintData, L"%-18.18s:  %4.4s,%4.4s,%4.4s,%4.4s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_031), Int2Asc(GetSumOfDetectedGap(CDU_CST_1)),
					Int2Asc(GetSumOfDetectedGap(CDU_CST_2)),
					Int2Asc(GetSumOfDetectedGap(CDU_CST_3)),
					Int2Asc(GetSumOfDetectedGap(CDU_CST_4)));
				AddPrintData(strPrintData, L"%-18.18s:  %4.4s,%4.4s,%4.4s,%4.4s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_032), Int2Asc(GetSumOfDetectedLong(CDU_CST_1)),
					Int2Asc(GetSumOfDetectedLong(CDU_CST_2)),
					Int2Asc(GetSumOfDetectedLong(CDU_CST_3)),
					Int2Asc(GetSumOfDetectedLong(CDU_CST_4)));
				AddPrintData(strPrintData, L"%-18.18s:  %4.4s,%4.4s,%4.4s,%4.4s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_033), Int2Asc(GetSumOfDetectedShort(CDU_CST_1)),
					Int2Asc(GetSumOfDetectedShort(CDU_CST_2)),
					Int2Asc(GetSumOfDetectedShort(CDU_CST_3)),
					Int2Asc(GetSumOfDetectedShort(CDU_CST_4)));
				AddPrintData(strPrintData, L"%-18.18s:  %4.4s,%4.4s,%4.4s,%4.4s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_034), Int2Asc(GetSumOfDetectedDouble(CDU_CST_1)),
					Int2Asc(GetSumOfDetectedDouble(CDU_CST_2)),
					Int2Asc(GetSumOfDetectedDouble(CDU_CST_3)),
					Int2Asc(GetSumOfDetectedDouble(CDU_CST_4)));
				AddPrintData(strPrintData, L"%-18.18s:  %4.4s,%4.4s,%4.4s,%4.4s", m_pDevCmn->fstrSCR_GetStringFromTextID(T_MSG_CLERK_035), Int2Asc(GetSumOfTestRejected(CDU_CST_1)),
					Int2Asc(GetSumOfTestRejected(CDU_CST_2)),
					Int2Asc(GetSumOfTestRejected(CDU_CST_3)),
					Int2Asc(GetSumOfTestRejected(CDU_CST_4)));
				//AddPrintData(strPrintData, L"========================================");

				// end of [#2160]

				m_OpInfo.m_strMsg = T_PRINTER_ERROR;
				if (m_pDevCmn->fnSPR_PrintReceipt(FALSE, strPrintData, K_1_WAIT) == TRUE)
					m_OpInfo.m_strMsg = T_OPERATE_OK;

				if (m_pDevCmn->fnSPR_GetDeviceStatus() != NORMAL)
					m_pDevCmn->fnAPL_ResetDevice(DEV_SPR);
			}
			else
				m_OpInfo.m_strMsg = T_PRINTER_ERROR;

			ClerkNoticeToUser(m_OpInfo.m_strMsg);
		}
		else if (m_OpInfo.strReturn == _T("CLEAR"))
		{
			if (ClerkConfirm(L"818F8S", m_OpInfo.strReturn) == TRUE)
			{
				ClearRejectTotal();

				ClerkNoticeToUser(T_OPERATE_OK);
#if SUPPORT_CHANGE_PARAMETER_JNL //[#610] SOOK 2010.01.16 Configuration Change 저널 추가 
				m_pDevCmn->m_JNLMgr.Save(OPERATOR_ACTION, L"Reject Analysis Cleared"); 
#endif  //end of [#610]
			}
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 931;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
		
	} // end of while
	
	NHDEBUG(DBG_CALL, (L"END\n"));
}
// end of [#526]

/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkDeviceSetupProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 844 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkDeviceSetupProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));
	
	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		if (m_OpInfo.strReturn == L"CDUSETUP")
		{
			// CDU Close Start
			ClerkNoticeToUser(T_TERMINATING_CDU, FALSE);

			m_pDevCmn->fnCDU_Deinitialize();

			m_OpInfo.nProcNextScrNum = 845;
			break;
		}
		// F2
		else if (m_OpInfo.strReturn == L"CALIBRATION")
		{
			STARTUPINFO si;
			ZeroMemory (&si, sizeof(si));
			si.cb = sizeof (si);
			si.wShowWindow = SW_HIDE;
			PROCESS_INFORMATION pi;

			if (CreateProcess(L"\\Windows\\TSWCEUCP.exe",NULL,NULL,NULL,NULL,FALSE,0,NULL,&si, &pi) == TRUE)
			{
				DWORD dwExitCode;
				while(1)
				{
					if (GetExitCodeProcess(pi.hProcess, &dwExitCode) == TRUE)
					{
						if (dwExitCode != STILL_ACTIVE)
							break;
					}
					Delay_Msg(500);
				}

				CloseHandle(pi.hThread);
				CloseHandle(pi.hProcess);
			}	
		}
		// F3
		else if (m_OpInfo.strReturn == L"CARDREADERSETUP")		// [#2073] NH KSK 2011.06.24
		{
			m_OpInfo.nProcNextScrNum = 741;
			break;
		}														// end of [#2073]
		// [#2325] NH KSK 2015.01.20 전면 Touch 미양산으로 인해 RFID Device Option 처리로 변경
		/*
		else if (m_OpInfo.strReturn == L"TOUCHVIBRATION")
		{
			// [#2166] NH KSK 2012.12.17
			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_TOUCHVIBRATION_ENABLE) == ENABLE)
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_TOUCHVIBRATION_ENABLE, 0);
			else
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_TOUCHVIBRATION_ENABLE, ENABLE);
			// end of [#2166]

			// [#2220] AU KMK 2014.01.14 Touch Vibration 설정 즉시 적용 (기존에 왜 누락되어 있었는지?)
			SetTouchVibration(MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_TOUCHVIBRATION_ENABLE));
			// end of [#2220]
		}
		*/
		// F4
		else if (m_OpInfo.strReturn == L"RFIDENDISABLE")
		{
			// Confirm 화면 표시
			CString strText;

			if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_RFID_DEVICE_ENABLE) == ENABLE)
				strText = L"844F4S_D";
			else
				strText = L"844F4S_E";

			if (ClerkConfirm(strText, m_OpInfo.strReturn) == TRUE)
			{
				ClerkNoticeToUser(T_PROCESS_WAIT, TRUE);
				
				if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_RFID_DEVICE_ENABLE) == ENABLE)
				{
					// Deinitialize Execute
					m_pDevCmn->fnRFID_Deinitialize();
					m_pDevCmn->DeviceDefine &= ~DEV_RFID;	// RFID Disable로 인해 Define 제거

					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_RFID_DEVICE_ENABLE, 0);

					ClerkNoticeToUser(T_OPERATE_OK);
				}
				else
				{
					// Initialize Execute
					m_pDevCmn->DeviceDefine |= DEV_RFID;	// RFID Disable로 인해 Define 추가 후 Initialize 수행
					m_pDevCmn->fnRFID_Initialize();
					m_pDevCmn->fnAPL_CheckDeviceAction(DEV_RFID);

					MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_RFID_DEVICE_ENABLE, ENABLE);

					if (m_pDevCmn->fnRFID_GetDeviceStatus() != NORMAL)
						ClerkNoticeToUser(T_DEVICE_ERR);
					else
						ClerkNoticeToUser(T_OPERATE_OK);
				}
			}
		}
		// end of [#2325]
		// F5
		else if (m_OpInfo.strReturn == L"HALO_LED_SETUP")
		{
			// [#2205] US KSK 2013.06.28
			m_OpInfo.nProcNextScrNum = 747;
			break;
			// end of [#2205]
		}
		// [#2371] US JUstin 4000W Full/Partial Cut
		// F6
		else if (m_OpInfo.strReturn == L"RECEIPTCUT")
		{
			m_OpInfo.nProcNextScrNum = 756;
			break;
		}
		// end of [#2371]
		// [#2518] US Kook 2017.12.22 Support MX-2800SE
		// F7
		else if (m_OpInfo.strReturn == L"CAMERA")
		{
			m_OpInfo.nProcNextScrNum = 764;
			break;
		}
		// end of [#2518]
		// [#GLDV-3005] US Kook 2021.10.22 Support Side Car
		// F8
		else if (m_OpInfo.strReturn == L"SIDECAR")
		{
			m_OpInfo.nProcNextScrNum = 772;
			break;
		}
		// end of [#GLDV-3005]

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 951;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
}

/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkCDUSetupProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 845 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkCDUSetupProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	int nErrorCode = 0;
	int nDeviceCmd = 0;	
	BOOL	bWait = FALSE;

	// CDU SETUP INFORMATION Initialize
	// CDU Comport Open Start
	if( m_pDiagCdu == NULL )
		m_pDiagCdu			= (CDiagCdu*)  new CDiagCdu;

	/* Open CDU Device */
	if( m_bDiagCDUOpen == FALSE )
	{
		nErrorCode = m_pDiagCdu->Open();
		
		if(nErrorCode == CDU_SUCCESS)
		{
			m_bDiagCDUOpen = TRUE;

			// CDU SETUP INFORMATION Initialize
			m_OpInfo.m_pusCstNum = 0;
			m_OpInfo.m_mbCDUType = 0;
			memset(m_OpInfo.m_ulCstIndex, 0, sizeof(m_OpInfo.m_ulCstIndex));
			memset(m_OpInfo.m_szCstCountry, 0, sizeof(m_OpInfo.m_szCstCountry));

			m_pDiagCdu->GetCurrentCDUInform(&m_OpInfo.m_pusCstNum, m_OpInfo.m_ulCstIndex, m_OpInfo.m_szCstCountry, &m_OpInfo.m_mbCDUType);
			NHDEBUG(DBG_INFO, (_T("***ClerkCtrl***CMainFrame::ClerkCDUSetupProc() m_pDiagCdu->Open() : SUCCESS \n")));
		}
		else
		{
			m_bDiagCDUOpen = FALSE;

			// CDU SETUP INFORMATION Initialize
			m_OpInfo.m_pusCstNum = 0;
			m_OpInfo.m_mbCDUType = 0;
			memset(m_OpInfo.m_ulCstIndex, 0, sizeof(m_OpInfo.m_ulCstIndex));
			memset(m_OpInfo.m_szCstCountry, 0, sizeof(m_OpInfo.m_szCstCountry));

			NHDEBUG(DBG_INFO, (_T("***ClerkCtrl***CMainFrame::ClerkCDUSetupProc() m_pDiagCdu->Open() : FAIL \n")));
		}
	}
//[#610] SOOK 2010.01.16 CDU SETUP은 미리 정보를 가지고 있는 것이 아니라서 현재 화면에서 변경 사항 체크한다. 
#if SUPPORT_CHANGE_PARAMETER_JNL

	USHORT			usPrevCstNum;
	USHORT			usPrevmbCDUType;
	TCHAR			szPrevCstCountry[4];

	if ( m_bDiagCDUOpen == TRUE) //단선이 아닐 경우만 
	{
		usPrevCstNum = m_OpInfo.m_pusCstNum;
		memcpy(szPrevCstCountry, m_OpInfo.m_szCstCountry, sizeof(m_OpInfo.m_szCstCountry));
		usPrevmbCDUType = m_OpInfo.m_mbCDUType;
	}
	
	BOOL		bExecuteCDUSetup = FALSE;
#endif
//end of [#610]
	
	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// CDU SETUP
		if (m_OpInfo.strReturn == L"COUNTRY")
		{
			memcpy(m_OpInfo.m_szCstCountry, m_pDiagCdu->GetNextCountryInfos(m_OpInfo.m_szCstCountry), sizeof(m_OpInfo.m_szCstCountry));
		}
		else if (m_OpInfo.strReturn == L"CSTVOLUME")
		{
			m_OpInfo.m_pusCstNum = (m_OpInfo.m_pusCstNum++ % 4);
			if (m_OpInfo.m_pusCstNum == 0)
				m_OpInfo.m_pusCstNum = 1;
		}
		else if (m_OpInfo.strReturn == L"CDUTYPE")
		{
			// [#2260] CDU TYPE 설정값 추가 0x02, 0x42, 0x82
			// Next CDU TYPE SEt
			if (m_OpInfo.m_mbCDUType == 0x00)
				m_OpInfo.m_mbCDUType = 0x01;
			else if (m_OpInfo.m_mbCDUType == 0x01)
				m_OpInfo.m_mbCDUType = 0x02;
			else if (m_OpInfo.m_mbCDUType == 0x02)
				m_OpInfo.m_mbCDUType = 0x03;
			else if (m_OpInfo.m_mbCDUType == 0x03)
				m_OpInfo.m_mbCDUType = 0x08;
			else if (m_OpInfo.m_mbCDUType == 0x08)
				m_OpInfo.m_mbCDUType = 0x09;
			else if (m_OpInfo.m_mbCDUType == 0x09)
				m_OpInfo.m_mbCDUType = 0x0A;
			else if (m_OpInfo.m_mbCDUType == 0x0A)
				m_OpInfo.m_mbCDUType = 0x0B;
			else if (m_OpInfo.m_mbCDUType == 0x0B)
				m_OpInfo.m_mbCDUType = 0x41;
			else if (m_OpInfo.m_mbCDUType == 0x41)
				m_OpInfo.m_mbCDUType = 0x43;
			else if (m_OpInfo.m_mbCDUType == 0x43)
				m_OpInfo.m_mbCDUType = 0x45;
			else if (m_OpInfo.m_mbCDUType == 0x45)
				m_OpInfo.m_mbCDUType = 0x47;
			else if (m_OpInfo.m_mbCDUType == 0x47)
				m_OpInfo.m_mbCDUType = 0x80;
			else if (m_OpInfo.m_mbCDUType == 0x80)
				m_OpInfo.m_mbCDUType = 0x82;
			else if (m_OpInfo.m_mbCDUType == 0x82)
				m_OpInfo.m_mbCDUType = 0x00;
			else
				m_OpInfo.m_mbCDUType = 0x80;	// CDU TYPE이 잘못되었을 경우 Default로 설정 (CDU-L TYPE)
			// end of [#2260]
		}
		else if (m_OpInfo.strReturn == L"EXECUTE")
		{
			ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);

			if (m_pDiagCdu->SetCDUSetupInform(m_OpInfo.m_pusCstNum, m_OpInfo.m_ulCstIndex, m_OpInfo.m_szCstCountry, m_OpInfo.m_mbCDUType) == CDU_SUCCESS)
			{
				m_OpInfo.m_strMsg = T_OPERATE_OK;
#if SUPPORT_CHANGE_PARAMETER_JNL
				bExecuteCDUSetup = TRUE;
#endif
			}
			else
				m_OpInfo.m_strMsg = T_OPERATE_NG;

			ClerkNoticeToUser(m_OpInfo.m_strMsg);

			// CDU SETUP INFORMATION Initialize
			m_OpInfo.m_pusCstNum = 0;
			m_OpInfo.m_mbCDUType = 0;
			memset(m_OpInfo.m_ulCstIndex, 0, sizeof(m_OpInfo.m_ulCstIndex));
			memset(m_OpInfo.m_szCstCountry, 0, sizeof(m_OpInfo.m_szCstCountry));

			// Version Read를 해서 현재 CDU 정보를 화면에 Display한다.
			m_pDiagCdu->GetVersion(&m_OpInfo.m_pusCstNum, m_OpInfo.m_ulCstIndex, m_OpInfo.m_szCstCountry, &m_OpInfo.m_mbCDUType);

			// KSK 2009.09.30 DevCmn의 GetVersion하는 곳으로 위치 이동
			// EP에서 0x00 , 0x01, 0x03일 경우에는 0x30, 0x31, 0x33값으로 올라옴
			// 기존 VDM과 POS BUG성을그대로 유지함
//				if (m_OpInfo.m_mbCDUType == 0x30 || m_OpInfo.m_mbCDUType == 0x31 || m_OpInfo.m_mbCDUType == 0x33 || m_OpInfo.m_mbCDUType == 0x3b)
				if (m_OpInfo.m_mbCDUType == 0x30 || m_OpInfo.m_mbCDUType == 0x31 || m_OpInfo.m_mbCDUType == 0x32 || m_OpInfo.m_mbCDUType == 0x33 || 
					m_OpInfo.m_mbCDUType == 0x38 || m_OpInfo.m_mbCDUType == 0x39 || m_OpInfo.m_mbCDUType == 0x3a || m_OpInfo.m_mbCDUType == 0x3b) 			// [#2260] NH KSK 2014.03.13 Type 추가(0x02)에 따라 조건문 추가
					m_OpInfo.m_mbCDUType -= 0x30;
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL) ||
			(m_OpInfo.strReturn == S_TIMEOVER))
		{
			BOOL bExit = FALSE;

			if (m_OpInfo.strReturn == S_TIMEOVER)
				bExit = TRUE;
			else
				bExit = ClerkConfirm(L"845EXITT", m_OpInfo.strReturn);

			if (bExit == TRUE)
			{
				/*************************************/
				/* Close CDU & Set Exit Message		 */
				/*************************************/
		
NHDEBUG(DIAG_TEST, (_T("[CMainFrame::ClerkDiagnosticsExitScreen] CLOSING CDU PORT(845)+\n")));
				
				ClerkNoticeToUser(m_pDevCmn->fstrSCR_GetStringFromTextID(T_CLOSING_CDU), FALSE);	// [#2160] CA KMK 2012.11.16 French OP

				if(m_pDiagCdu != NULL)
				{
					m_pDiagCdu->Close();
					/* Wait to close device's serial port 1 sec. */
					Delay_Msg(1000);
					
					m_bDiagCDUOpen = FALSE;
					delete m_pDiagCdu;
					m_pDiagCdu = NULL;
					
				}
				
				/*************************************/
				/* INITIALIZE CDU & Set Exit Message */
				/*************************************/
NHDEBUG(DIAG_TEST, (_T("[CMainFrame::ClerkDiagnosticsExitScreen] INITIALIZING CDU(845)+\n")));

				ClerkNoticeToUser(m_pDevCmn->fstrSCR_GetStringFromTextID(T_INITIALIZING_CDU), FALSE);	// [#2160] CA KMK 2012.11.16 French OP

				m_pDevCmn->fnAPL_ResetDevice(DEV_CDU);
				
				if (m_OpInfo.nMoveProcReason == MOVE_PROC_TIMEOUT)
					m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
				else
					m_OpInfo.nProcNextScrNum = 844;

				break;
			}
			else
			{
				// [#2260] NH KSK 2014.03.14 Cancel시 CDU Information 갱신 로직 보완 (기존 잠재버그 Fix)
				// CDU SETUP INFORMATION Initialize
				if (m_bDiagCDUOpen == TRUE)
				{
					// CDU SETUP INFORMATION Initialize
					m_OpInfo.m_pusCstNum = 0;
					m_OpInfo.m_mbCDUType = 0;
					memset(m_OpInfo.m_ulCstIndex, 0, sizeof(m_OpInfo.m_ulCstIndex));
					memset(m_OpInfo.m_szCstCountry, 0, sizeof(m_OpInfo.m_szCstCountry));

					// Version Read를 해서 현재 CDU 정보를 화면에 Display한다.
					m_pDiagCdu->GetVersion(&m_OpInfo.m_pusCstNum, m_OpInfo.m_ulCstIndex, m_OpInfo.m_szCstCountry, &m_OpInfo.m_mbCDUType);

					if (m_OpInfo.m_mbCDUType == 0x30 || m_OpInfo.m_mbCDUType == 0x31 || m_OpInfo.m_mbCDUType == 0x32 || m_OpInfo.m_mbCDUType == 0x33 || 
						m_OpInfo.m_mbCDUType == 0x38 || m_OpInfo.m_mbCDUType == 0x39 || m_OpInfo.m_mbCDUType == 0x3a || m_OpInfo.m_mbCDUType == 0x3b)
						m_OpInfo.m_mbCDUType -= 0x30;
				}
				// end of [#2260]
			}
		}

	} // end of while
//[#610] SOOK 2010.01.16 CDU SETUP은 미리 정보를 가지고 있는 것이 아니라서 현재 화면에서 변경 사항 체크한다. 
#if SUPPORT_CHANGE_PARAMETER_JNL

	if ( m_bDiagCDUOpen == TRUE && bExecuteCDUSetup == TRUE) //단선이 아닐 경우만 
	{
		if ( usPrevCstNum != m_OpInfo.m_pusCstNum )
		{
			m_pDevCmn->m_JNLMgr.SaveChangeParameterJnl(m_OpInfo.nLoginMode, "CASSETTE VOLUME", Int2Asc(usPrevCstNum), Int2Asc(m_OpInfo.m_pusCstNum));
		}
		if ( memcmp(szPrevCstCountry, m_OpInfo.m_szCstCountry, sizeof(m_OpInfo.m_szCstCountry)) != 0)
		{
			CString strOldValue, strNewValue;
			strOldValue.Format(L"%s", m_pDiagCdu->GetCountryInfos(szPrevCstCountry, COU_NAME));
			strNewValue.Format(L"%s", m_pDiagCdu->GetCountryInfos(m_OpInfo.m_szCstCountry, COU_NAME ));
			m_pDevCmn->m_JNLMgr.SaveChangeParameterJnl(m_OpInfo.nLoginMode, "CDU COUNTRY", strOldValue, strNewValue);
		}
		if ( usPrevmbCDUType != m_OpInfo.m_mbCDUType)
		{
			CString strOldValue, strNewValue;
			strOldValue.Format(L"0x%02x", usPrevmbCDUType );
			strNewValue.Format(L"0x%02x", m_OpInfo.m_mbCDUType);
			m_pDevCmn->m_JNLMgr.SaveChangeParameterJnl(m_OpInfo.nLoginMode, "CDU TYPE", strOldValue, strNewValue);
		}
	}
#endif
//end of [#610]

	NHDEBUG(DBG_CALL, (L"END\n"));
}

/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkSystemControlProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 846 PROC
-------------------------------------------------------------------*/
void	CMainFrame::ClerkSystemControlProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	BOOL bShowScreen = TRUE;

	while(TRUE)
	{
		///////////////////////////////////
		// DISPLAY OR UPDATE SCREEN
		if (bShowScreen == TRUE)
		{
			ClerkScreenDisplay(m_OpInfo.nProcNextScrNum, m_OpInfo.nTimeout);
			m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);
			bShowScreen = FALSE;
			m_OpInfo.nProcLoofCnt = 0;
		}
		else if (m_OpInfo.nProcLoofCnt >= SCR_UPDATECYCLE)
		{
			ClerkCheckDeviceStatus();
			ClerkScreenUpdate(m_OpInfo.nProcNextScrNum);
			m_OpInfo.nProcLoofCnt = 0;
		}

		///////////////////////////////////
		// GET KEY STRING
		if (m_pDevCmn->fnSCR_ScanDeviceAction(DEV_SCR, 1, EVENT_IN) == DEV_SCR)
		{
			m_pDevCmn->fnAPL_EnDisableHotKey(DISABLE);
			m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

			NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

			//-----------------------------------
			// PROCESS KEY STRING
			//-----------------------------------
			// F1
			if (m_OpInfo.strReturn == L"SWUPDATE")
			{
				m_OpInfo.nProcNextScrNum = 1013;
				break;	
			}
			// F3
			else if (m_OpInfo.strReturn == L"REBOOT_SHUTDOWN")
			{
				// [#2536] NH Kook 2018.03.09 ATM Shutdown
				//if (ClerkConfirm(L"846F3S", m_OpInfo.strReturn) == TRUE)
				//{
				//	TerminateATM(T_REBOOT_OK, FALSE);
				//}
				m_OpInfo.nProcNextScrNum = 766;
				break;			
				// end of [#2536]
			}
			// F4
			else if (m_OpInfo.strReturn == L"BACKUPDATEJNL")
			{
				m_OpInfo.nProcNextScrNum = 816;
				break;			
			}

			// F5
			else if (m_OpInfo.strReturn == L"LOADFROMUSB")
			{
				HANDLE			hSearch = INVALID_HANDLE_VALUE;		// [#2022] NH KSK 2011.02.22
				CString			strDestPath;

				// Display OP MSG
				ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);

				if (LoadSettingsFromUSBOrSDCard())
				{
					m_OpInfo.m_strMsg = T_OPERATE_OK;
				}
				else
				{
					m_OpInfo.m_strMsg = T_OPERATE_NG;
				}

				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}
			// F7
			else if (m_OpInfo.strReturn == L"DISKMANAGE")
			{
				m_OpInfo.nProcNextScrNum = 1000;
				break;			
			}
			// F8
			else if (m_OpInfo.strReturn == L"NVRAM")	// F8
			{
				//[#2097] US PCS 2011.11.14
				//m_OpInfo.strSelectedMachineType = m_pDevCmn->m_pConfig->GetMachineType();
				//m_OpInfo.nProcNextScrNum = 908;
#if (US_VERSION || CA_VERSION || MX_VERSION)		// [#2571] NH Justin 2018.08.03 Fix Machine Type Setting Problem
				m_OpInfo.nProcNextScrNum = 908;
#else
				m_OpInfo.strSelectedMachineType = m_pDevCmn->m_pConfig->GetMachineType();
				m_OpInfo.nProcNextScrNum = 908;
#endif
				//end of [#2097]
				break;			
			}
			else if (m_OpInfo.strReturn == L"BACKUPALLJNL" || m_OpInfo.strReturn == L"BACKUPLOGRCOPY")
			{
				WIN32_FIND_DATA	FileData;
				HANDLE			hSearch = INVALID_HANDLE_VALUE;		// [#2022] NH KSK 2011.02.22
				CString			strDestPath, strTerminalID;
				BOOL			bOK;

				// find USB Folder
				// [#156] AIREAT 2008.05.13 OS Version에 따른 PATH 지정
				//strDestPath = L"\\USB";
				strDestPath.Format(_T("%s"), LOGBACKUP_DEST_PATH);
				// end of [#156]
				hSearch = FindFirstFile(strDestPath, &FileData);
				if (hSearch != INVALID_HANDLE_VALUE)
				{
					FindClose(hSearch);

					// Display OP MSG
					ClerkNoticeToUser(T_PROCESS_WAIT, FALSE);

					strTerminalID = MemGetStr(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_TERMINALID);
					strTerminalID.TrimLeft();
					strTerminalID.TrimRight();

					// [#156] KSK 2008.04.22 OS Version에 따른 PATH 지정
					strDestPath.Format(_T("%s\\%s"), LOGBACKUP_DEST_PATH, strTerminalID);
					// end of [#156]

					if (m_OpInfo.strReturn == L"BACKUPALLJNL")
					{
						CreateDirectory(strDestPath, NULL);
						strDestPath += L"\\JNL";
						CreateDirectory(strDestPath, NULL);
						bOK = m_pDevCmn->m_JNLMgr.BackupJNLData(strDestPath);

						// [#2518] US Kook 2018.03.06 Backup cam images.
						if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CAM_ENABLE) == ENABLE)
						{
							//m_pDevCmn->fnCAM_BackupImages(strDestPath);
							int nImageFolderCount = 0;
							CString strProgress = _T("");
							CString strSrcFolder = _T("");
							CString strDestFolder = _T("");

							// counting image folders to show progress.
							for (int folderIdx = 1; folderIdx <= ( NH_CAM_FACE_IMAGE_CNT_MAX / NH_CAM_FACE_IMAGE_CNT_PER_DIR); folderIdx++)
							{
								strSrcFolder.Format(_T("%s\\%02d"), NH_CAM_FACE_IMAGE_FOLDER, folderIdx);
								if (IsExistFile(strSrcFolder))
									nImageFolderCount++;
							}

							// backup journal pics.
							for (int copyIdx = 1; copyIdx <= nImageFolderCount; copyIdx++)
							{
								strProgress.Format(	_T("%s\n%s\n%d%%"),
									m_pDevCmn->fstrSCR_GetStringByTextID(_T("BACKING UP JOURNAL PIC")),
									m_pDevCmn->fstrSCR_GetStringByTextID(_T("THIS MIGHT TAKE SEVERAL MINUTES")),
									(int)((((float)(copyIdx-1)/(float)nImageFolderCount)*100.0)+0.5));
								ClerkNoticeToUser(strProgress, FALSE);

								strSrcFolder.Format(_T("%s\\%02d"), NH_CAM_FACE_IMAGE_FOLDER, copyIdx);
								strDestFolder.Format(_T("%s\\%s\\%02d"), strDestPath, _T("CAMIMAGE"), copyIdx);
								CreateDirectoryWithIntermediate(strDestFolder);

								//SYSTEMTIME	ti;
								//GetLocalTime(&ti);
								//RETAILMSG(1, (_T("[%02d/%02d %02d:%02d:%02d] --- COPYING %s to %s\n"), ti.wMonth, ti.wDay, ti.wHour, ti.wMinute, ti.wSecond,
								//																		strSrcFolder, strDestFolder));

								DeleteFileInDirectory(strDestFolder, _T("*.*"));
								CopyFileInDirectory(strSrcFolder, _T("*.*"), strDestFolder);
							}
						}
					}
					else
					{
						CreateDirectory(strDestPath, NULL);
						strDestPath += L"\\LOG";
						CreateDirectory(strDestPath, NULL);
						bOK = BackupLogData(strDestPath);
					}

					if (bOK)
						m_OpInfo.m_strMsg = T_OPERATE_OK;
					else
						m_OpInfo.m_strMsg = T_OPERATE_NG;
				}
				else
					m_OpInfo.m_strMsg = T_NO_USB_SLOT;

				ClerkNoticeToUser(m_OpInfo.m_strMsg);
			}

			//-----------------------------------
			// COMMON PROCESS
			//-----------------------------------
			if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
			{
				m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
				m_OpInfo.nProcNextScrNum = 951;
				break;
			}
			else if (m_OpInfo.strReturn == S_TIMEOVER)
			{
				m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
				m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
				break;
			}
			bShowScreen = TRUE;		// 화면 update를 위해
		}
		Delay_Msg(PROC_LOOFDELAY);
		m_OpInfo.nProcLoofCnt++;

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
}

// [#2536] NH Kook 2018.03.09 ATM Shutdown
/*-------------------------------------------------------------------
CLASS    NAME: CMainFrame
FUNCTION NAME: ClerkPowerControlProc()
RETURN TYPE  : 
PARAMETER    : 
DESCRIPTION  : SCR 766 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkPowerControlProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	BOOL bShowScreen = TRUE;

	while(TRUE)
	{
		///////////////////////////////////
		// DISPLAY OR UPDATE SCREEN
		if (bShowScreen == TRUE)
		{
			ClerkScreenDisplay(m_OpInfo.nProcNextScrNum, m_OpInfo.nTimeout);
			m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);
			bShowScreen = FALSE;
			m_OpInfo.nProcLoofCnt = 0;
		}
		else if (m_OpInfo.nProcLoofCnt >= SCR_UPDATECYCLE)
		{
			ClerkCheckDeviceStatus();
			ClerkScreenUpdate(m_OpInfo.nProcNextScrNum);
			m_OpInfo.nProcLoofCnt = 0;
		}

		///////////////////////////////////
		// GET KEY STRING
		if (m_pDevCmn->fnSCR_ScanDeviceAction(DEV_SCR, 1, EVENT_IN) == DEV_SCR)
		{
			m_pDevCmn->fnAPL_EnDisableHotKey(DISABLE);
			m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

			NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

			//-----------------------------------
			// PROCESS KEY STRING
			//-----------------------------------
			// F7
			if (m_OpInfo.strReturn == L"REBOOTNOW")
			{
				if (ClerkConfirm(L"766F7S", m_OpInfo.strReturn) == TRUE)
				{
					TerminateATM(T_REBOOT_OK, FALSE);
				}
			}
			// F8
			else if (m_OpInfo.strReturn == L"SHUTDOWNNOW")
			{
				if (ClerkConfirm(L"766F8S", m_OpInfo.strReturn) == TRUE)
				{
					TerminateATM(_T("Preparing to turn off ATM..."), TRUE, TRUE);
				}
			}
			// [#2558] NH Justin 2018.06.13 Add Scheduled Reboot Optioin
			// F1
			if (m_OpInfo.strReturn == L"SCHEDULEDREBOOT")
			{
				int nRebootOption = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_REBOOT_OPTION) + 1;
				if(nRebootOption > REBOOT_OPTION_INTERVAL)
					nRebootOption =	REBOOT_OPTION_DISABLE;	
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_REBOOT_OPTION, nRebootOption);
				SetNextRebootTime();
			}
			// F2
			else if (m_OpInfo.strReturn == L"SETTIME")
			{
				int nRebootOption = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_REBOOT_OPTION);

				if( (nRebootOption == REBOOT_OPTION_ONTIME) || (nRebootOption == REBOOT_OPTION_INTERVAL) )
				{
					CString strValue, strTitleRef, strGuide;
					if(nRebootOption == REBOOT_OPTION_ONTIME)
					{
						int nRebootTime = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_REBOOT_TIME);
						strValue.Format(L"%02d:%02d", (int) (0.01*nRebootTime), (nRebootTime % 100) );
						strTitleRef = L"766F2T1";	strGuide = L"766F2T1S";
					}
					else
					{
						strValue.Format(L"%2d", MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_REBOOT_INTERVAL) );
						strTitleRef = L"766F2T2";	strGuide = L"766F2T2S";
					}

					if (ClerkInputNumber(strTitleRef, strGuide, strValue, EDIT_NORMAL, 4, m_OpInfo.strReturn) == TRUE)
					{
						int nEnteredNum = Asc2Int(m_OpInfo.strReturn);
						BOOL bValidInput = FALSE;
						if(nRebootOption == REBOOT_OPTION_ONTIME)
						{
							int nEntHH = (int) (0.01 * nEnteredNum);
							int nEntMM = nEnteredNum % 100;
							if( (nEntHH>=0) && (nEntHH<=23) && (nEntMM>=0) && (nEntMM<=59) )
							{
								bValidInput = TRUE;
								MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_REBOOT_TIME, nEnteredNum);
							}
						}
						else
						{
							if( (nEnteredNum>0) && ( nEnteredNum<=REBOOT_OPTION_MAX_INTERVAL ) )
							{
								bValidInput = TRUE;
								MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_REBOOT_INTERVAL, nEnteredNum);
							}
						}

						if(bValidInput == TRUE)
						{
							SetNextRebootTime();
							ClerkNoticeToUser(T_OPERATE_OK);
						}
						else
							ClerkNoticeToUser(T_INVALID_DATA);
					}
				}
			}
			// End of [#2558]

			//-----------------------------------
			// COMMON PROCESS
			//-----------------------------------
			if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
			{
				m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
				m_OpInfo.nProcNextScrNum = 846;
				break;
			}
			else if (m_OpInfo.strReturn == S_TIMEOVER)
			{
				m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
				m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
				break;
			}
			bShowScreen = TRUE;		// 화면 update를 위해
		}
		Delay_Msg(PROC_LOOFDELAY);
		m_OpInfo.nProcLoofCnt++;

	} // end of while

	NHDEBUG(DBG_CALL, (L"END\n"));
}
// end of [#2536]

/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkChangBackgroundProc()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : SCR 847 PROC
-------------------------------------------------------------------*/
void CMainFrame::ClerkChangBackgroundProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F1
		// [#2166] NH KSK 2012.12.17
// 		if (m_OpInfo.strTempArray[0] == L"CHANGE" && m_OpInfo.strTempArray.GetSize() == 2)
// 		{
// 			if (m_OpInfo.strTempArray[1] == L"DISABLE")
// 				MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_CHANGE_ENDISFLAG, 0);
// 			else
// 			{
// 				// Check Screen n Flag
// 				// 모든 Screen이 Disable인 경우에는 Enable하지 못하도록 수정
// 				int i;
// 				for(i=0; i<6; i++)
// 				{
// 					if (MemGetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_ENDISFLAG_TYPE1 + i) == ENABLE)
// 						break;
// 				}
// 
// 				// Screen이 모두 Disable이므로 Enable 처리 불가
// 				if (i == 6)
// 					ClerkNoticeToUser(T_CANNOT_BE_ENABLED);
// 				else
// 					MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_CHANGE_ENDISFLAG, 1);
// 			}
// 		}
		if (m_OpInfo.strReturn == L"CHANGE")
		{
			if (MemGetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_CHANGE_ENDISFLAG) == ENABLE)
				MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_CHANGE_ENDISFLAG, 0);
			else
			{
				// Check Screen n Flag
				// 모든 Screen이 Disable인 경우에는 Enable하지 못하도록 수정
				int i;
				for(i=0; i<6; i++)
				{
					if (MemGetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_ENDISFLAG_TYPE1 + i) == ENABLE)
						break;
				}

				// Screen이 모두 Disable이므로 Enable 처리 불가
				if (i == 6)
					ClerkNoticeToUser(T_CANNOT_BE_ENABLED);
				else
					MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_CHANGE_ENDISFLAG, 1);
			}
		}
		// end of [#2166]
		// F2
		else if (m_OpInfo.strTempArray[0] == L"DEFAULT")
		{
			m_OpInfo.nProcNextScrNum = 848;
			break;
		}
		// F3
		else if (m_OpInfo.strTempArray[0] == L"SCR1")
		{
			m_OpInfo.nProcNextScrNum = 849;
			break;
		}
		// F4
		else if (m_OpInfo.strTempArray[0] == L"SCR2")
		{
			m_OpInfo.nProcNextScrNum = 850;
			break;
		}
		// F5
		else if (m_OpInfo.strTempArray[0] == L"SCR3")
		{
			m_OpInfo.nProcNextScrNum = 851;
			break;
		}
		// F6
		else if (m_OpInfo.strTempArray[0] == L"SCR4")
		{
			m_OpInfo.nProcNextScrNum = 852;
			break;
		}
		// F7
		else if (m_OpInfo.strTempArray[0] == L"SCR5")
		{
			m_OpInfo.nProcNextScrNum = 853;
			break;
		}
		// F8
		else if (m_OpInfo.strTempArray[0] == L"SCR6")
		{
			m_OpInfo.nProcNextScrNum = 854;
			break;
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 880;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
	}

	NHDEBUG(DBG_CALL, (L"END\n"));
}

