void CMainFrame::ClerkDefaultBackgroundProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F3
		if (m_OpInfo.strTempArray[0] == L"SCR1")
		{
			MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_DEFAULT_TYPE, 1);
		}
		// F4
		else if (m_OpInfo.strTempArray[0] == L"SCR2")
		{
			MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_DEFAULT_TYPE, 2);
		}
		// F5
		else if (m_OpInfo.strTempArray[0] == L"SCR3")
		{
			MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_DEFAULT_TYPE, 3);
		}
		// F6
		else if (m_OpInfo.strTempArray[0] == L"SCR4")
		{
			MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_DEFAULT_TYPE, 4);
		}
		// F7
		else if (m_OpInfo.strTempArray[0] == L"SCR5")
		{
			MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_DEFAULT_TYPE, 5);
		}
		// F8
		else if (m_OpInfo.strTempArray[0] == L"SCR6")
		{
			MemSetInt(_MEM_FLD_ADVINFO, _MEM_VAR_BACK_DEFAULT_TYPE, 6);
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 847;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
	}

	NHDEBUG(DBG_CALL, (L"END\n"));
}

