void CMainFrame::ClerkHaloLEDSetupProc()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	m_OpInfo.nTempHaloLedATM_Mode = 0;

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		//-----------------------------------
		// PROCESS KEY STRING
		//-----------------------------------
		// F1
		if (m_OpInfo.strReturn == L"IN_SERVICE")
		{
			m_OpInfo.nTempHaloLedATM_Mode = HALOLED_ATMMODE_INSERVICE;
		}
		// F3
		else if (m_OpInfo.strReturn == L"TRANSACTION")
		{
			m_OpInfo.nTempHaloLedATM_Mode = HALOLED_ATMMODE_TRANSACTION;
		}
		// F5
		else if (m_OpInfo.strReturn == L"DISPENSING")
		{
			m_OpInfo.nTempHaloLedATM_Mode = HALOLED_ATMMODE_DISPENSING;
		}
		// F7
		else if (m_OpInfo.strReturn == L"OUT_OF_SERVICE")
		{
			m_OpInfo.nTempHaloLedATM_Mode = HALOLED_ATMMODE_OUTOFSERVICE;
		}

		// F2
		else if (m_OpInfo.strReturn == L"LED_MODE")
		{
			/*
			int nCurrentMode	= 0;
			int nNextMode		= 0;
			if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_INSERVICE)
			{
				nCurrentMode = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_INSERVICE);
				nNextMode = (nCurrentMode+1) % 4;
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_INSERVICE, nNextMode);
			}
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_TRANSACTION)
			{
				nCurrentMode = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_TRANSACTION);
				nNextMode = (nCurrentMode+1) % 4;
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_TRANSACTION, nNextMode);
			}
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_DISPENSING)
			{
				nCurrentMode = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_DISPENSING);
				nNextMode = (nCurrentMode+1) % 4;
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_DISPENSING, nNextMode);
			}
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_OUTOFSERVICE)
			{
				nCurrentMode = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_OUTOFSERVICE);
				nNextMode = (nCurrentMode+1) % 4;
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_OUTOFSERVICE, nNextMode);
			}
			*/

			int nMemoryLoc = 0;
			if		(m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_INSERVICE)		nMemoryLoc = _MEM_VAR_OPT2_HALO_LEDMODE_INSERVICE;
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_TRANSACTION)		nMemoryLoc = _MEM_VAR_OPT2_HALO_LEDMODE_TRANSACTION;
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_DISPENSING)		nMemoryLoc = _MEM_VAR_OPT2_HALO_LEDMODE_DISPENSING;
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_OUTOFSERVICE)		nMemoryLoc = _MEM_VAR_OPT2_HALO_LEDMODE_OUTOFSERVICE;
			if(nMemoryLoc!=0)
			{
				int nCurrentMode = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, nMemoryLoc);
				int nNextMode    = (nCurrentMode+1) % 4;
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, nMemoryLoc, nNextMode);
			}


		}
		// F4
		else if (m_OpInfo.strReturn == L"LED_COLOR")
		{
			/*
			int nCurrentColor	= 0;
			int nNextColor		= 0;
			if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_INSERVICE)
			{
				nCurrentColor = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_INSERVICE);
				nNextColor = (nCurrentColor+1) % 6;
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_INSERVICE, nNextColor);
			}
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_TRANSACTION)
			{
				nCurrentColor = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_TRANSACTION);
				nNextColor = (nCurrentColor+1) % 4;
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_TRANSACTION, nNextColor);
			}
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_DISPENSING)
			{
				nCurrentColor = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_DISPENSING);
				nNextColor = (nCurrentColor+1) % 4;
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_DISPENSING, nNextColor);
			}
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_OUTOFSERVICE)
			{
				nCurrentColor = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_OUTOFSERVICE);
				nNextColor = (nCurrentColor+1) % 4;
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_OUTOFSERVICE, nNextColor);
			}
			*/
			int nMemoryLoc = 0;
			if		(m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_INSERVICE)		nMemoryLoc = _MEM_VAR_OPT2_HALO_LEDCOLOR_INSERVICE;
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_TRANSACTION)		nMemoryLoc = _MEM_VAR_OPT2_HALO_LEDCOLOR_TRANSACTION;
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_DISPENSING)		nMemoryLoc = _MEM_VAR_OPT2_HALO_LEDCOLOR_DISPENSING;
			else if (m_OpInfo.nTempHaloLedATM_Mode == HALOLED_ATMMODE_OUTOFSERVICE)		nMemoryLoc = _MEM_VAR_OPT2_HALO_LEDCOLOR_OUTOFSERVICE;			
			if(nMemoryLoc!=0)
			{
				int nCurrentColor = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, nMemoryLoc);
				int nNextColor    = (nCurrentColor+1) % 6;
				MemSetInt(_MEM_FLD_OPTIONALSETTING_2, nMemoryLoc, nNextColor);
			}
		}
		// F8
		else if (m_OpInfo.strReturn == L"DEFAULT")
		{
			// Default Set
			m_OpInfo.nTempHaloLedATM_Mode = 0;
			// In-Service Value
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_INSERVICE, FADE_HALOLED_MODE);
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_INSERVICE, HALOLED_COLOR_CYAN);	// Fade인 경우에는 의미 없음
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_TRANSACTION, ON_HALOLED_MODE);
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_TRANSACTION, HALOLED_COLOR_GREEN);
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_DISPENSING, FLICKING_HALOLED_MODE);
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_DISPENSING, HALOLED_COLOR_GREEN);
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDMODE_OUTOFSERVICE, ON_HALOLED_MODE);
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_HALO_LEDCOLOR_OUTOFSERVICE, HALOLED_COLOR_PINK);
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 844;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}

	} // end of while

	m_OpInfo.nTempHaloLedATM_Mode = 0;

	NHDEBUG(DBG_CALL, (L"END\n"));
}
