/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkInputAlpha()
 RETURN TYPE  : 
 PARAMETER    : 
 DESCRIPTION  : 사용자로 부터 문자 입력을 받는다.
-------------------------------------------------------------------*/
BOOL CMainFrame::ClerkInputAlpha(CString strTitleID, CString strValue, int nRow, int nCol, CString &strNewValue)
{
	BOOL		bShowScreen = TRUE;

	NHDEBUG(DBG_CALL, (L"TitleID(%s), strValue(%s), nRow(%d), nCol(%d)\n", strTitleID, strValue, nRow, nCol));

	m_OpInfo.strTempArray.RemoveAll();

	while (TRUE)
	{
		///////////////////////////////////
		// DISPLAY SCREEN
		if (bShowScreen == TRUE)
		{
			CString strTitle;
			CString strAllowRowCol;

			strTitle.Format(L"APTextID:%s", strTitleID);
			strAllowRowCol.Format(L"AllowRowCol:%d:%d", nRow, nCol);

			m_pDevCmn->fnSCR_DisplayPrevSet(600);
			m_pDevCmn->fnSCR_DisplayString(1, strTitle);
			m_pDevCmn->fnSCR_DisplayString(2, strAllowRowCol);
			m_pDevCmn->fnSCR_DisplayString(2, strValue);
			m_pDevCmn->fnSCR_DisplayScreen(600, m_OpInfo.nTimeout, 0);
			m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);
			bShowScreen = FALSE;
		}

		///////////////////////////////////
		// GET KEY STRING
		if (m_pDevCmn->fnSCR_ScanDeviceAction(DEV_SCR, 1, EVENT_IN) == DEV_SCR)
		{
			strNewValue = m_pDevCmn->fstrSCR_GetKeyString(1);

			NHDEBUG(DBG_INFO, (_T("INPUT VALUE [%s]\n"), strNewValue));

			if (strNewValue.Left(5) == L"INPUT")
			{
				strNewValue = strNewValue.Mid(6);
				return TRUE;
			}
			else if (strNewValue == L"EXIT" || strNewValue == L"CANCEL")
			{
				strNewValue = L"";
				return FALSE;
			}
			else if (strNewValue == L"TIMEOVER")
			{
				return FALSE;
			}
		}

		Delay_Msg(50);
	}

	m_pDevCmn->fnAPL_EnDisableHotKey(DISABLE);

	return FALSE;
}

