/*-------------------------------------------------------------------
CLASS    NAME: CMainFrame
FUNCTION NAME: ClerkTangoPaySettings()
RETURN TYPE  : 
PARAMETER    : 
DESCRIPTION  : SCR 1040 PROC
-------------------------------------------------------------------*/
#if (APP_TANGOPAY)	// [RWC6-676] Start SKKim 2024.03.29
void CMainFrame::ClerkTangoPaySettings()
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	if (m_pTranCmn->m_pTangoPayConfigManager == NULL)
	{
		m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
		m_OpInfo.nProcNextScrNum = 795;
		return;
	}

	m_pTranCmn->m_pTangoPayConfigManager->GetConfiguration(m_pTranCmn->m_TangoPayConfig);

	CString strTemp;

	while(TRUE)
	{
		NHDEBUG(DBG_INFO, (L"WAIT FOR USER INPUT\n"));

		///////////////////////////////////
		// WAIT FOR USER INPUT
		ClerkWaitScreenInput_byCha();
		m_OpInfo.strReturn = m_pDevCmn->fstrSCR_GetKeyString();
		SplitString(m_OpInfo.strReturn, SCR_RES_DELIMITER, m_OpInfo.strTempArray);

		NHDEBUG(DBG_INFO, (L"USER INPUT [%s]\n", m_OpInfo.strReturn));

		if (m_OpInfo.strReturn == L"PARTNERID")
		{
			strTemp = m_pTranCmn->m_TangoPayConfig.strPartnerID;

			strTemp.Trim();

			if (ClerkInputAlpha(L"1040TF1T", strTemp, 1, 16, m_OpInfo.strReturn) == TRUE)
			{
				strTemp = m_OpInfo.strReturn;
				strTemp.Trim();
				m_pTranCmn->m_TangoPayConfig.strPartnerID = strTemp;
		
				ClerkNoticeToUser(T_OPERATE_OK);
				m_pTranCmn->m_pTangoPayConfigManager->SaveConfiguration(m_pTranCmn->m_TangoPayConfig);
			}
		}
		else if (m_OpInfo.strReturn == L"ENABLE")
		{
			bool bEnDisable = m_pTranCmn->m_TangoPayConfig.bEnable;

			if (bEnDisable == true)
				m_pTranCmn->m_TangoPayConfig.bEnable = false;
			else
				m_pTranCmn->m_TangoPayConfig.bEnable = true;

			m_pTranCmn->m_pTangoPayConfigManager->SaveConfiguration(m_pTranCmn->m_TangoPayConfig);
		}
		else if (m_OpInfo.strReturn == L"APIKEY")
		{
			strTemp = m_pTranCmn->m_TangoPayConfig.strApiKey;
			strTemp.Trim();
			//strTemp.MakeUpper();

			if (ClerkInputAlpha(L"1040DF3T", strTemp, 1, 36, m_OpInfo.strReturn) == TRUE)	// '-' 4개 포함하여 36개 (key값은 32개)
			{
				strTemp = m_OpInfo.strReturn;
				strTemp.Trim();
				//strTemp.MakeUpper();

				if (strTemp.GetLength() == 36)
				{
					m_pTranCmn->m_TangoPayConfig.strApiKey = strTemp;
					ClerkNoticeToUser(T_OPERATE_OK);
					m_pTranCmn->m_pTangoPayConfigManager->SaveConfiguration(m_pTranCmn->m_TangoPayConfig);
				}
				else
				{
					ClerkNoticeToUser(T_INVALID_DATA);
				}
			}
		}
		else if (m_OpInfo.strReturn == L"PUBLICKEY_DOWNLOAD")
		{
			// TODO
			ClerkNoticeToUser(T_PROCESS_WAIT);

			if (m_pTranCmn->P_NH_TangoPay_GetPublicKey() == RES_OK)
				ClerkNoticeToUser(T_OPERATE_OK, TRUE);
			else
				ClerkNoticeToUser(T_OPERATE_NG, TRUE);
		}
		else if (m_OpInfo.strReturn == L"JWT_DOWNLOAD")
		{
			// TODO: Get JWT
			if (m_pTranCmn->P_NH_TangoPay_GetTerminalJWT() == RES_OK)
				ClerkNoticeToUser(T_OPERATE_OK, TRUE);
			else
				ClerkNoticeToUser(T_OPERATE_NG, TRUE);
		}
		else if (m_OpInfo.strReturn == L"RESET_APIKEY")
		{
			if (m_pTranCmn->P_NH_TangoPay_ResetApiKey() == RES_OK)
				ClerkNoticeToUser(T_OPERATE_OK, TRUE);
			else
				ClerkNoticeToUser(T_OPERATE_NG, TRUE);
		}

		//-----------------------------------
		// COMMON PROCESS
		//-----------------------------------
		if ((m_OpInfo.strReturn == S_EXIT) || (m_OpInfo.strReturn == S_CANCEL))
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_EXIT;
			m_OpInfo.nProcNextScrNum = 795;
			break;
		}
		else if (m_OpInfo.strReturn == S_TIMEOVER)
		{
			m_OpInfo.nMoveProcReason = MOVE_PROC_TIMEOUT;
			m_OpInfo.nProcNextScrNum = OP_TIMEOUT_SCREEN_NUMBER;
			break;
		}
	}

	NHDEBUG(DBG_CALL, (L"END\n"));
}
#endif				// [RWC6-676] End SKKim 2024.03.29

/*-------------------------------------------------------------------
CLASS    NAME: CMainFrame
FUNCTION NAME: ClerkConfirm()
RETURN TYPE  : 
PARAMETER    : 
DESCRIPTION  : SCR 601 PROC 사용자 확인 화면
-------------------------------------------------------------------*/
BOOL CMainFrame::ClerkConfirm(CString strGuideID, CString &strNewValue, BOOL bUseInputText)			// [#2428] Justin Add USE INPUT TEXT OPTION
{
	BOOL bShowScreen = TRUE;

	NHDEBUG(DBG_CALL, (L"GuideID(%s)\n", strGuideID));

	while (TRUE)
	{
		///////////////////////////////////
		// DISPLAY SCREEN
		if (bShowScreen == TRUE)
		{
			
			CString strGuide;
			// [#2428] Justin Add Use Input Text Option 
			//strGuide.Format(L"APTextID:%s", strGuideID);
			if( bUseInputText == TRUE)
				strGuide = strGuideID;								// Added
			else
				strGuide.Format(L"APTextID:%s", strGuideID);		// Existing.....
			// End of [#2428]

			m_pDevCmn->fnSCR_DisplayPrevSet(601);
			if (strGuideID.GetLength() > 0)
				m_pDevCmn->fnSCR_DisplayString(1, strGuide);
			
			m_pDevCmn->fnSCR_DisplayScreen(601, m_OpInfo.nTimeout, 0);
			m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);
			bShowScreen = FALSE;
		}

		///////////////////////////////////
		// GET KEY STRING
		if (m_pDevCmn->fnSCR_ScanDeviceAction(DEV_SCR, 1, EVENT_IN) == DEV_SCR)
		{
			m_pDevCmn->fnAPL_EnDisableHotKey(DISABLE);
			strNewValue = m_pDevCmn->fstrSCR_GetKeyString(1);

			NHDEBUG(DBG_INFO, (_T("INPUT VALUE [%s]\n"), strNewValue));

			if (strNewValue == L"YES")
			{
				return TRUE;
			}
			else if (strNewValue == L"CANCEL")
			{
				strNewValue = "NO";
				return FALSE;
			}
			else if (strNewValue == L"TIMEOVER")
			{
				return FALSE;
			}
			else if (strNewValue == L"NO")
			{
				return FALSE;
			}

			m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);
		}

		Delay_Msg(50);
	}

	return FALSE;
}

/*-------------------------------------------------------------------
CLASS    NAME: CMainFrame
FUNCTION NAME: ClerkInputNumber()
RETURN TYPE  : 
PARAMETER    : 
DESCRIPTION  : SCR 602 PROC 숫자 입력 화면
-------------------------------------------------------------------*/
BOOL CMainFrame::ClerkInputNumber(CString strTitleID, CString strGuideID, CString strValue, CString strInputType, int MaxInChar, CString &strNewValue)
{
	BOOL		bShowScreen = TRUE;

	NHDEBUG(DBG_CALL, (L"TitleID(%s), strValue(%s), nMaxInChar(%d)\n", strTitleID, strValue, MaxInChar));

	m_OpInfo.strTempArray.RemoveAll();

	while (TRUE)
	{
		///////////////////////////////////
		// DISPLAY SCREEN
		if (bShowScreen == TRUE)
		{
			CString strTitle;
			CString strGuide;
			CString strMaxInChar;
			CString strEditBoxType;

			strTitle.Format(L"APTextID:%s", strTitleID);
			strGuide.Format(L"APTextID:%s", strGuideID);
			strMaxInChar.Format(L"MaxInChar:%d", MaxInChar);
			strEditBoxType.Format(L"EditBoxType:%s", strInputType);

			m_pDevCmn->fnSCR_DisplayPrevSet(602);

			// TITLE
			if (strTitleID.GetLength() > 0)
				m_pDevCmn->fnSCR_DisplayString(1, strTitle);

			// GUIDE
			if (strGuideID.GetLength() > 0)
				m_pDevCmn->fnSCR_DisplayString(2, strGuide);
			
			// APVALUE 3
			if (strEditBoxType.GetLength() > 0)
				m_pDevCmn->fnSCR_DisplayString(3, strEditBoxType);

			m_pDevCmn->fnSCR_DisplayString(3, strValue);

			// APVALUE 4
			if (strMaxInChar.GetLength() > 0)
				m_pDevCmn->fnSCR_DisplayString(4, strMaxInChar);
			if (strEditBoxType.GetLength() > 0)
				m_pDevCmn->fnSCR_DisplayString(4, strEditBoxType);

			m_pDevCmn->fnSCR_DisplayScreen(602, m_OpInfo.nTimeout, 0);
			m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);
			bShowScreen = FALSE;
		}

		///////////////////////////////////
		// GET KEY STRING
		if (m_pDevCmn->fnSCR_ScanDeviceAction(DEV_SCR, 1, EVENT_IN) == DEV_SCR)
		{
			CStringArray strTempArray;

			m_pDevCmn->fnAPL_EnDisableHotKey(DISABLE);
			CString strInputValue = m_pDevCmn->fstrSCR_GetKeyString(1);
			SplitString(strInputValue, SCR_RES_DELIMITER, strTempArray);

			for (int i = 0; i < strTempArray.GetSize(); i++)
				NHDEBUG(DBG_INFO, (_T("INPUT VALUE [%d]-[%s]\n"), i, strTempArray[i]));

			if (strTempArray[0] == L"INPUT")
			{
				strNewValue = strTempArray[2];
				return TRUE;
			}
			else if (strTempArray[0] == L"CANCEL" || strTempArray[0] == L"EXIT")
			{
				strNewValue = L"";
				return FALSE;
			}
			else if (strTempArray[0] == L"TIMEOVER")
			{
				strNewValue = L"TIMEOVER";
				return FALSE;
			}

			m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);
		}

		Delay_Msg(50);
	}

	return FALSE;
}

//void CMainFrame::ClerkNoticeToUser(CString strMessage, BOOL bWait) // [#RWC6-10]
void CMainFrame::ClerkNoticeToUser(CString strMessage, BOOL bWait, int nWaitTime) // [#RWC6-10]
{
	NHDEBUG(DBG_CALL, (_T("Message(%s)\n"), strMessage));

	m_pDevCmn->fnSCR_DisplayPrevSet(603);
	m_pDevCmn->fnSCR_DisplayString(1, strMessage);
	m_pDevCmn->fnSCR_DisplayScreen(603, 0, 0);
	
	if (bWait == TRUE)
		if (nWaitTime > 1)							// [#RWC6-10]
			m_pDevCmn->fstrSCR_WaitTime(nWaitTime); // [#RWC6-10]
		else										// [#RWC6-10]
			m_pDevCmn->fstrSCR_WaitTime(1);
}

