// [#2518] US Kook 2018.01.15 Support Camera
void CMainFrame::ClerkViewCamImages(CString strTitle1, CString strImg1Path,
									CString strTitle2, CString strImg2Path)
{
	NHDEBUG(DBG_CALL, (L"Title1:(%s), ImgPath1:(%s)\n", strTitle1, strImg1Path));
	NHDEBUG(DBG_CALL, (L"Title2:(%s), ImgPath2:(%s)\n", strTitle2, strImg2Path));

	// [#2552] NH Justin 2018.05.29 2800 OP Journal Image View Bug Fix - Tr. without picture : ATM displays previously viewed Image.
	if( strImg1Path.IsEmpty() && strImg2Path.IsEmpty() )
		return;
	// End of [#2552]

	m_OpInfo.strTempArray.RemoveAll();

	///////////////////////////////////
	// DISPLAY SCREEN
	m_pDevCmn->fnSCR_DisplayPrevSet(605);

	// initialize images
	for (int i = 1; i <= 6; i++)
		m_pDevCmn->fnSCR_DisplayString(i, _T(""));

	// 1 image (image 2 not exist... possible case?)
	if (strImg2Path.IsEmpty())
	{
		// Image1 with title
		if (strTitle1.GetLength() > 0)		m_pDevCmn->fnSCR_DisplayString(5, strTitle1);
		if (strImg1Path.GetLength() > 0)	m_pDevCmn->fnSCR_DisplayString(6, strImg1Path);
	}
	// 2 images
	else
	{
		// Image1 with title
		if (strTitle1.GetLength() > 0)		m_pDevCmn->fnSCR_DisplayString(1, strTitle1);
		if (strImg1Path.GetLength() > 0)	m_pDevCmn->fnSCR_DisplayString(2, strImg1Path);

		// Image2 with title
		if (strTitle2.GetLength() > 0)		m_pDevCmn->fnSCR_DisplayString(3, strTitle2);
		if (strImg2Path.GetLength() > 0)	m_pDevCmn->fnSCR_DisplayString(4, strImg2Path);
	}

	m_pDevCmn->fnSCR_DisplayScreen(605, m_OpInfo.nTimeout, 0);
	m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);

	while (TRUE)
	{
		///////////////////////////////////
		// GET KEY STRING
		if (m_pDevCmn->fnSCR_ScanDeviceAction(DEV_SCR, 1, EVENT_IN) == DEV_SCR)
		{
			m_pDevCmn->fnAPL_EnDisableHotKey(DISABLE);
			CString strInputValue = m_pDevCmn->fstrSCR_GetKeyString(1);

			if (strInputValue == S_CANCEL || strInputValue == S_EXIT)
			{
				return;
			}
			else if (strInputValue == S_TIMEOVER)
			{
				return;
			}

			m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);
		}

		Delay_Msg(100);
	}
}
// end of [#2518]

/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkWaitScreenInput()
 RETURN TYPE  :
 PARAMETER    :
 DESCRIPTION  : Clerk 화면을 표시, Update, Input을 기다린다.
				OP의 902 화면을 제외하고 공통루틴을 사용한다.
				예외가 발생시 루틴을 PROC안에 구현해야 한다.
-------------------------------------------------------------------*/
BOOL CMainFrame::ClerkWaitScreenInput(BOOL bDIAGNOSTICS, BOOL bKeyControl)
{
	if (bKeyControl == TRUE)
		m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);			// [#126] NH AIREAT 2008.4.18 OP Process 진행 중 모든 Key Disable 처리

	// start to check timeout
	// [#236] NZ AIREAT 2008.06.04
	if (m_OpInfo.nCurScrNum == m_OpInfo.nProcNextScrNum)
	{
		m_pDevCmn->fnSCR_SetDisplayData(L"APTimeoutMode", L"TimeoutLast");		// NH PSC 2008.07.07 소스리뷰결과 공통적용.
		m_pDevCmn->fnSCR_SetDisplayData(L"APMaxTime", Int2Asc(m_OpInfo.nTimeout));
	}
	// end of [#236]

	while(TRUE)
	{
		// OP의 하단의 메시지를 지운다.
		if (m_OpInfo.nMsgClearCount == 0)
		{
			m_OpInfo.strTempClerkMessage = _T("");
			m_OpInfo.nMsgClearCount = -1;
		}
	
		// 장치의 상태를 체크하고 변경시 아래에서 Update를 수행한다.
		if (m_OpInfo.nProcLoofCnt >= SCR_UPDATECYCLE)
		{
			if( !(bDIAGNOSTICS) )
				ClerkCheckDeviceStatus();

			m_OpInfo.nProcLoofCnt = 0;

			// 화면을 표시 or Update 한다.
			if (m_OpInfo.nCurScrNum != m_OpInfo.nProcNextScrNum)
				ClerkScreenDisplay(m_OpInfo.nProcNextScrNum, m_OpInfo.nTimeout);
			else
				ClerkScreenUpdate(m_OpInfo.nProcNextScrNum);
		}
				
		// 화면 입력을 기다린다.
		if (m_pDevCmn->fnSCR_ScanDeviceAction(DEV_SCR, SCR_INPUTWAIT, EVENT_IN) == DEV_SCR)
			break;
		
		if (m_OpInfo.nMsgClearCount > 0)
			m_OpInfo.nMsgClearCount--;
		
		m_OpInfo.nProcLoofCnt++;
		
		Delay_Msg(PROC_LOOFDELAY);
	}

	// Stop to check timeout
	m_pDevCmn->fnSCR_SetDisplayData(L"APTimeoutMode", L"TimeoutStop");				// [#236] NZ AIREAT 2008.06.04

	if (bKeyControl == TRUE)
		m_pDevCmn->fnAPL_EnDisableHotKey(DISABLE);			// [#126] NH AIREAT 2008.4.18 OP Process 진행 중 모든 Key Disable 처리
	
	return TRUE;
}

/*-------------------------------------------------------------------
 CLASS    NAME: CMainFrame
 FUNCTION NAME: ClerkWaitScreenInput()
 RETURN TYPE  :
 PARAMETER    :
 DESCRIPTION  : Clerk 화면을 표시, Update, Input을 기다린다.
				OP의 902 화면을 제외하고 공통루틴을 사용한다.
				예외가 발생시 루틴을 PROC안에 구현해야 한다.
-------------------------------------------------------------------*/
BOOL CMainFrame::ClerkWaitScreenInput_byCha(BOOL bDIAGNOSTICS, BOOL bKeyControl)
{
	NHDEBUG(DBG_CALL, (L"START\n"));

	BOOL	bShowScreen = TRUE;

	m_OpInfo.strTempArray.RemoveAll();
	m_OpInfo.nProcLoofCnt = 0;

	while(TRUE)
	{
		///////////////////////////////////
		// DISPLAY SCREEN
		if (bShowScreen == TRUE)
		{
			ClerkScreenDisplay(m_OpInfo.nProcNextScrNum, m_OpInfo.nTimeout);

			if (bKeyControl == TRUE)
				m_pDevCmn->fnAPL_EnDisableHotKey(ENABLE);

			bShowScreen = FALSE;
		}
		
		///////////////////////////////////
		// Check Device
		// 장치의 상태를 체크하고 변경시 아래에서 Update를 수행한다.
		if (m_OpInfo.nProcLoofCnt >= SCR_UPDATECYCLE)
		{
			//if( !(bDIAGNOSTICS) )
			//	ClerkCheckDeviceStatus();

			m_OpInfo.nProcLoofCnt = 0;
		}
		
		///////////////////////////////////
		// GET KEY STRING
		// 화면 입력을 기다린다.
		if (m_pDevCmn->fnSCR_ScanDeviceAction(DEV_SCR, SCR_INPUTWAIT, EVENT_IN) == DEV_SCR)
			break;
		
		m_OpInfo.nProcLoofCnt++;	
		Delay_Msg(PROC_LOOFDELAY);
	}

	// Stop to check timeout
	m_pDevCmn->fnSCR_SetDisplayData(L"APTimeoutMode", L"TimeoutStop");

	if (bKeyControl == TRUE)
		m_pDevCmn->fnAPL_EnDisableHotKey(DISABLE);
	
	NHDEBUG(DBG_CALL, (L"END\n"));

	return TRUE;
}

