OPERATION_RESULT CMainFrame::ProcAddCash(CStringArray &arAddCashString, int nActUser)
{
	BOOL	bValid = FALSE;
	int		nTempCnt = 0;
	CString strJnlData, strTemp;

	// 파라미터 체크
	// [#2267] US KSK 2014.05.12 1500인경우에는 2CST만 지원하므로 Parameter Check 조건 변경
//	if ((arAddCashString.GetSize() <= 0) || (arAddCashString.GetSize() > 5) || (arAddCashString[0] != L"ADDCASH"))
//		return OPERATION_NG_DATANG;
	int nCSTValidParamSize = 0;

	if (m_pDevCmn->m_pConfig->GetOSVersion() != NH_OS_NH1500SE)
		nCSTValidParamSize = 5;
	else
		nCSTValidParamSize = 3;

	if ((arAddCashString.GetSize() <= 0) || (arAddCashString.GetSize() > nCSTValidParamSize) || (arAddCashString[0] != L"ADDCASH"))
		return OPERATION_NG_DATANG;
	// end of [#2267]

	bValid = FALSE;
	// ADD CASH VALUE 체크해서 모두 0 일때 불가
	for (int i=0; i<m_pDevCmn->CSTCnt; i++)
	{
		if (Asc2Int(arAddCashString[i+1]) != 0)
			bValid = TRUE;
	}

	if (bValid == FALSE)
		return OPERATION_NG_DATANG;

	// CDU 단선시 ADD CASH 불가하도록 수정
	if (m_pDevCmn->fstrAPL_GetErrorCode().Left(5) == "97400")
		return OPERATION_NG_CDUNG;

	// [#626] NH KSK 2010.03.09 Denomination이 0인 경우 Invalid 처리
	int		i, nDenomination[4];

	memset(nDenomination, 0, sizeof(nDenomination));
	nDenomination[0] = m_pDevCmn->FirstCSTValue;
	nDenomination[1] = m_pDevCmn->SecondCSTValue;
	nDenomination[2] = m_pDevCmn->ThirdCSTValue;
	nDenomination[3] = m_pDevCmn->FourthCSTValue;

	for (i=0; i<m_pDevCmn->CSTCnt; i++)
	{
		if (nDenomination[i] == 0)
			return OPERATION_NG_DENOM;
	}
	// end of [#626]

	m_pDevCmn->m_nCstAvail = 0;	// Initialize Cst Available
	m_pDevCmn->RejectCSTCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_REJECT);	// [#392] [NH] KSK 2008.8.5
	m_pDevCmn->FirstCSTInitCash		= 0;
	m_pDevCmn->SecondCSTInitCash	= 0;
	m_pDevCmn->ThirdCSTInitCash		= 0;
	m_pDevCmn->FourthCSTInitCash	= 0;

	m_pDevCmn->FirstCSTSetCash		= 0;
	m_pDevCmn->SecondCSTSetCash		= 0;
	m_pDevCmn->ThirdCSTSetCash		= 0;
	m_pDevCmn->FourthCSTSetCash		= 0;

	m_pDevCmn->nAdditionCST1		= 0;
	m_pDevCmn->nAdditionCST2		= 0;
	m_pDevCmn->nAdditionCST3		= 0;
	m_pDevCmn->nAdditionCST4		= 0;

	if (m_pDevCmn->CSTCnt >= CDU_CST_1)
	{
		// [#2270] AU KSK 2014.05.26
		// Note Counting Disable시 AP에서 관리하는 값에 Setting하도록 함
		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			nTempCnt = m_pDevCmn->fnCDU_GetNumberOfSetCash(CDU_CST_1) + Asc2Int(arAddCashString[1]);
		else
			nTempCnt = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST1_INITIALCOUNT_AP) + Asc2Int(arAddCashString[1]);

		m_pDevCmn->FirstCSTInitCash = nTempCnt;

		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			nTempCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_1) + Asc2Int(arAddCashString[1]);
		else
			nTempCnt = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST1_CURRENTCOUNT_AP) + Asc2Int(arAddCashString[1]);

		if (nTempCnt > 2000)		return OPERATION_NG_INSERTOVER;

		m_pDevCmn->FirstCSTSetCash = nTempCnt;

//		m_pDevCmn->FirstCSTInitCash	= m_pDevCmn->fnCDU_GetNumberOfSetCash(CDU_CST_1) + Asc2Int(arAddCashString[1]);
//		m_pDevCmn->FirstCSTSetCash	= nTempCnt;
		// end of [#2270]

		m_pDevCmn->nAdditionCST1	= Asc2Int(arAddCashString[1]);
		m_pDevCmn->m_nCstAvail	|= CST1_AVAIL;

		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			strTemp.Format(L"%6.6d^%6.6d", m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_1), Asc2Int(arAddCashString[1]));
		else
			strTemp.Format(L"%6.6d^%6.6d", MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST1_CURRENTCOUNT_AP), Asc2Int(arAddCashString[1]));

		strJnlData += strTemp;
	}
	if (m_pDevCmn->CSTCnt >= CDU_CST_2)
	{
		// [#2270] AU KSK 2014.05.26
		// Note Counting Disable시 AP에서 관리하는 값에 Setting하도록 함

		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			nTempCnt = m_pDevCmn->fnCDU_GetNumberOfSetCash(CDU_CST_2) + Asc2Int(arAddCashString[2]);
		else
			nTempCnt = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST2_INITIALCOUNT_AP) + Asc2Int(arAddCashString[2]);

		m_pDevCmn->SecondCSTInitCash = nTempCnt;

		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			nTempCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_2) + Asc2Int(arAddCashString[2]);
		else
			nTempCnt = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST2_CURRENTCOUNT_AP) + Asc2Int(arAddCashString[2]);

		m_pDevCmn->SecondCSTSetCash = nTempCnt;

		if (nTempCnt > 2000)		return OPERATION_NG_INSERTOVER;

//		m_pDevCmn->SecondCSTInitCash	= m_pDevCmn->fnCDU_GetNumberOfSetCash(CDU_CST_2) + Asc2Int(arAddCashString[2]);
//		m_pDevCmn->SecondCSTSetCash		= nTempCnt;
		// end of [#2270]

		m_pDevCmn->nAdditionCST2		= Asc2Int(arAddCashString[2]);
		m_pDevCmn->m_nCstAvail |= CST2_AVAIL;

		// [#2270] AU KSK 2014.05.26
		// Note Counting Disable시 AP에서 관리하는 값에 Setting하도록 함
		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			strTemp.Format(L"^%6.6d^%6.6d", m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_2), Asc2Int(arAddCashString[2]));
		else
			strTemp.Format(L"^%6.6d^%6.6d", MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST2_CURRENTCOUNT_AP), Asc2Int(arAddCashString[2]));
		// end of [#2270]

		strJnlData += strTemp;
	}
	if (m_pDevCmn->CSTCnt >= CDU_CST_3)
	{
		// [#2270] AU KSK 2014.05.26
		// Note Counting Disable시 AP에서 관리하는 값에 Setting하도록 함
		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			nTempCnt = m_pDevCmn->fnCDU_GetNumberOfSetCash(CDU_CST_3) + Asc2Int(arAddCashString[3]);
		else
			nTempCnt = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST3_INITIALCOUNT_AP) + Asc2Int(arAddCashString[3]);

		m_pDevCmn->ThirdCSTInitCash = nTempCnt;

		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			nTempCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_3) + Asc2Int(arAddCashString[3]);
		else
			nTempCnt = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST3_CURRENTCOUNT_AP) + Asc2Int(arAddCashString[3]);

		m_pDevCmn->ThirdCSTSetCash = nTempCnt;

		if (nTempCnt > 2000)		return OPERATION_NG_INSERTOVER;

//		m_pDevCmn->ThirdCSTInitCash	= m_pDevCmn->fnCDU_GetNumberOfSetCash(CDU_CST_3) + Asc2Int(arAddCashString[3]);
//		m_pDevCmn->ThirdCSTSetCash	= nTempCnt;
		// end of [#2270]

		m_pDevCmn->nAdditionCST3		= Asc2Int(arAddCashString[3]);
		m_pDevCmn->m_nCstAvail |= CST3_AVAIL;

		// [#2270] AU KSK 2014.05.26
		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			strTemp.Format(L"^%6.6d^%6.6d", m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_3), Asc2Int(arAddCashString[3]));
		else
			strTemp.Format(L"^%6.6d^%6.6d", MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST3_CURRENTCOUNT_AP), Asc2Int(arAddCashString[3]));
		// end of [#2270]

		strJnlData += strTemp;
	}
	if (m_pDevCmn->CSTCnt >= CDU_CST_4)
	{
		// [#2270] AU KSK 2014.05.26
		// Note Counting Disable시 AP에서 관리하는 값에 Setting하도록 함
		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			nTempCnt = m_pDevCmn->fnCDU_GetNumberOfSetCash(CDU_CST_4) + Asc2Int(arAddCashString[4]);
		else
			nTempCnt = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST4_INITIALCOUNT_AP) + Asc2Int(arAddCashString[4]);

		m_pDevCmn->FourthCSTInitCash = nTempCnt;

		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			nTempCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_4) + Asc2Int(arAddCashString[4]);
		else
			nTempCnt = MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST4_CURRENTCOUNT_AP) + Asc2Int(arAddCashString[4]);

		m_pDevCmn->FourthCSTSetCash = nTempCnt;

		if (nTempCnt > 2000)		return OPERATION_NG_INSERTOVER;

//		m_pDevCmn->FourthCSTInitCash	= m_pDevCmn->fnCDU_GetNumberOfSetCash(CDU_CST_4) + Asc2Int(arAddCashString[4]);
//		m_pDevCmn->FourthCSTSetCash		= nTempCnt;
		// end of [#2270]

		m_pDevCmn->nAdditionCST4		= Asc2Int(arAddCashString[4]);;
		m_pDevCmn->m_nCstAvail |= CST4_AVAIL;

		// [#2270] AU KSK 2014.05.26
		if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == 0)
			strTemp.Format(L"^%6.6d^%6.6d", m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_4), Asc2Int(arAddCashString[4]));
		else
			strTemp.Format(L"^%6.6d^%6.6d", MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST4_CURRENTCOUNT_AP), Asc2Int(arAddCashString[4]));
		// end of [#2270]
		strJnlData += strTemp;
	}

	if (nActUser == 0)
		m_pDevCmn->strJnlKindCode.Format(L"A%x", m_pDevCmn->m_nCstAvail);			// RMS에서 ADD CASH시 Journal Code가 다르다 ("A1, A2 ...")
	else
		m_pDevCmn->strJnlKindCode.Format(L"E%x", m_pDevCmn->m_nCstAvail);			// RMS에서 ADD CASH시 Journal Code가 다르다 ("E1, E2 ...")

	m_pDevCmn->strJnlKindCode.MakeUpper();
	m_pDevCmn->m_JNLMgr.Save(m_pDevCmn->strJnlKindCode, strJnlData);

	// Save Last Add Cash Time (Journal Save시에는 무조건 Success라고 판단함)
	CTime		CurTime = CTime::GetCurrentTime();

	strTemp.Format(L"%02d%02d%04d%02d%02d%02d",			
		CurTime.GetMonth(), CurTime.GetDay(), CurTime.GetYear(),
		CurTime.GetHour(), CurTime.GetMinute(), CurTime.GetSecond());
	// ADD CASH LAST TIME 갱신
	MemSetStr(_MEM_FLD_INI_TRANSINFO, _MEM_VAR_APP_LASTADDCASHTIME, strTemp);

	m_pTranCmn->BIZ_AddCashProc(nActUser);				// Add Cash Procedure
	m_pDevCmn->fnAPL_SetSensorInfo(TRUE);			// Update CST Information

	// [#2270] AU KSK 2014.05.26 Negative Count가 Disable시에만 Add한 값을 Setting한다.
	if (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CDUM_NEGATIVE_COUNT_ENABLE) == ENABLE)
	{
		for(int i=0; i<CDU_MAX_CST_COUNT; i++)
		{
			nTempCnt =  MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST1_INITIALCOUNT_AP + i) + Asc2Int(arAddCashString[i+1]);
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST1_INITIALCOUNT_AP + i, nTempCnt);
			nTempCnt =  MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST1_CURRENTCOUNT_AP + i) + Asc2Int(arAddCashString[i+1]);
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CST1_CURRENTCOUNT_AP + i, nTempCnt);			
		}
	}
	// end of [#2270]

	// [#453] [NH] KSK 2008.11.25
	// Status Monitoring Field가 ON시에만 하도록 수정
	// Triton은 Add Cash 시, 호스트로 카세트 전문 발송 필수임
	// [#2309] US Justin 2014.11.18 Send Health Check Message for ADD Cash (STD1 and STD3)
	//if( (MemGetStr(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_MSGTYPE) == MSG_TRITON_TYPE) &&
	//	  (MemGetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_STATUSMONITORINGENABLE) == ENABLE) &&
	//	  (m_pDevCmn->HostOpenFlag == TRUE) )
	if( ( (MemGetStr(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_MSGTYPE) == MSG_TRITON_TYPE) &&
		  (MemGetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_STATUSMONITORINGENABLE) == ENABLE) &&
		  (m_pDevCmn->HostOpenFlag == TRUE) ) ||
	    ( (MemGetStr(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_MSGTYPE) == MSG_HYOSUNG_TYPE) &&
		  (MemGetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_HEALTHYFLAG) == ENABLE)	&&
		  (MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_TERMINAL_STATUS_FIELD_ENABLE) == ENABLE) &&
		  (m_pDevCmn->HostOpenFlag == TRUE) ) )
	{
		if (nActUser == 0)
			ClerkNoticeToUser(T_HEARTBEAT_SENT, FALSE);

		ClerkCheckDeviceStatus();						// [#2290] NH Justn 2014.08.13 Update Device Status for Health Check after Add Cash
		m_pTranCmn->BIZ_HealthCheckProc(FALSE);
		m_pDevCmn->fnAPL_SetHealthCheckTimer();			// [#583] NH KSK 2009.11.24 Sec로 변경됨에 따라 Refresh Time 설정 위치 수정 (송신 후)
	}
	// end of [#453]
	
	if (m_pDevCmn->CSTCnt >= CDU_CST_1)
		m_pDevCmn->FirstCSTCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_1);
	if (m_pDevCmn->CSTCnt >= CDU_CST_2)
		m_pDevCmn->SecondCSTCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_2);
	if (m_pDevCmn->CSTCnt >= CDU_CST_3)
		m_pDevCmn->ThirdCSTCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_3);
	if (m_pDevCmn->CSTCnt >= CDU_CST_4)
		m_pDevCmn->FourthCSTCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_4);
	
	if (m_pDevCmn->fnSPR_GetDeviceStatus() != NORMAL && nActUser == 0)		// by OP일 경우 SPR Reset (by Remote인 경우에는 Reset하지 않음)
	{
		m_pDevCmn->fnAPL_ResetDevice(DEV_SPR);
		return OPERATION_OK_SPRNG;
	}

	return OPERATION_OK;
}

// [#2504] US Justin 2017.09.11 Test Dispensing on ADD CASH SCREEN
OPERATION_RESULT CMainFrame::ProcOPTestDispensing()
{
	BOOL bEnoughCash = TRUE;

	// Check remain Note Count
	if( (bEnoughCash==TRUE) && (m_pDevCmn->CSTCnt >= CDU_CST_1) )
	{
		if( m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_1) < 1 )
			bEnoughCash = FALSE;
	}
	if( (bEnoughCash==TRUE) && (m_pDevCmn->CSTCnt >= CDU_CST_2) )
	{
		if( m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_2) < 1 )
			bEnoughCash = FALSE;
	}
	if( (bEnoughCash==TRUE) && (m_pDevCmn->CSTCnt >= CDU_CST_3) )
	{
		if( m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_3) < 1 )
			bEnoughCash = FALSE;
	}
	if( (bEnoughCash==TRUE) && (m_pDevCmn->CSTCnt >= CDU_CST_4) )
	{
		if( m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_4) < 1 )
			bEnoughCash = FALSE;
	}
	if (bEnoughCash!=TRUE)
		return OPERATION_NG;

	// Test Dispense.....
	m_pDevCmn->fnCDU_TestDispense();

	// Wait
	m_pDevCmn->fnAPL_CheckDeviceAction(DEV_CDU);
	m_pDevCmn->fnAPL_CheckDevice();

	// Dispense Status
	{
		int	i = 0;
		int	nDispensed[4] = { 0, }, nRejected[4] = { 0, };
		int nSkewNote[4] = { 0, }, nGapNote[4] = { 0, }, nLongNote[4] = { 0, }, nShortNote[4] = { 0, }, nDoubleNote[4] = { 0, };
		CString strtemp;
		
		CString strErrorCode = m_pDevCmn->fstrAPL_GetErrorCode();

		if ((strErrorCode == L"9792401") ||			// FATAL ERROR
			(strErrorCode.Left(5) == L"97400"))		// CDU 단선
		{
			// Dispense Command가 SP로 가지 않는 경우 Dispensed / Rejected Count를 임의로 0으로 만든다.
			strtemp.Format(L"00 00 00 00");
			MemSetStr(_MEM_FLD_APP_ERRTRANS, _MEM_VAR_APP_TRANS_DISP_COUNT, strtemp);
			MemSetStr(_MEM_FLD_APP_ERRTRANS, _MEM_VAR_APP_TRANS_REJ_COUNT,	strtemp);				
		}
		else
		{
			// Get Last Dispense Info
			for (i = 0; i < 4; i++)
			{
				nDispensed[i]  = MemGetInt(_MEM_FLD_SP_CDM, _MEM_VAR_CDMSP_CST1_T_DISP_CNT + i);
				nRejected[i]   = MemGetInt(_MEM_FLD_SP_CDM, _MEM_VAR_CDMSP_CST1_T_REJ_CNT + i);
				nSkewNote[i]   = MemGetInt(_MEM_FLD_SP_CDM, _MEM_VAR_DEVINFO_RJTSKEW_CST1 + i);
				nGapNote[i]	   = MemGetInt(_MEM_FLD_SP_CDM, _MEM_VAR_DEVINFO_RJTGAPTOCLOSE_CST1 + i);
				nLongNote[i]   = MemGetInt(_MEM_FLD_SP_CDM, _MEM_VAR_DEVINFO_RJTLONGNOTE_CST1 + i);
				nShortNote[i]  = MemGetInt(_MEM_FLD_SP_CDM, _MEM_VAR_DEVINFO_RJTSHORTNOTE_CST1 + i);
				nDoubleNote[i] = MemGetInt(_MEM_FLD_SP_CDM, _MEM_VAR_DEVINFO_RJTDOUBLE_CST1 + i);

				NHDEBUG(1, (_T("CDiagCdu::ThreadHandlerProc : CMD_DISPENSE CALL CST [%d] DISPENSED[%d] REJECTED[%d]\n"), i+1, MemGetInt(_MEM_FLD_SP_CDM, _MEM_VAR_CDMSP_CST1_T_DISP_CNT + i), MemGetInt(_MEM_FLD_SP_CDM, _MEM_VAR_CDMSP_CST1_T_REJ_CNT + i)));
			}

			// Add to Reject Total
			for (i = 0; i < 4; i++)
			{
				AddSumOfDispensed(i+1, nDispensed[i]);
				AddSumOfRejected(i+1, nRejected[i]);
				AddSumOfDetectedSkew(i+1, nSkewNote[i]);
				AddSumOfDetectedGap(i+1, nGapNote[i]);
				AddSumOfDetectedLong(i+1, nLongNote[i]);
				AddSumOfDetectedShort(i+1, nShortNote[i]);
				AddSumOfDetectedDouble(i+1, nDoubleNote[i]);
			}

			// save Last dispensed Info
			strtemp.Format(L"%02d %02d %02d %02d",	nDispensed[0], nDispensed[1], nDispensed[2], nDispensed[3]);
			MemSetStr(_MEM_FLD_APP_ERRTRANS, _MEM_VAR_APP_TRANS_DISP_COUNT, strtemp);

			// save Last rejected Info
			strtemp.Format(L"%02d %02d %02d %02d",  nRejected[0], nRejected[1], nRejected[2], nRejected[3]);
			MemSetStr(_MEM_FLD_APP_ERRTRANS, _MEM_VAR_APP_TRANS_REJ_COUNT,	strtemp);
		}
	}

	// Update number of Bills
	if (m_pDevCmn->CSTCnt >= CDU_CST_1)
		m_pDevCmn->FirstCSTCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_1);
	if (m_pDevCmn->CSTCnt >= CDU_CST_2)
		m_pDevCmn->SecondCSTCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_2);
	if (m_pDevCmn->CSTCnt >= CDU_CST_3)
		m_pDevCmn->ThirdCSTCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_3);
	if (m_pDevCmn->CSTCnt >= CDU_CST_4)
		m_pDevCmn->FourthCSTCnt = m_pDevCmn->fnCDU_GetNumberOfCash(CDU_CST_4);

	return OPERATION_OK;
}
