			// [#651] NH KSK 2010.09.07
			if (m_OpInfo.nLoginMode == LOGIN_MASTER)
			{
				// [#RWC6-56] US William 2019.12.26 Hash passwords
				strnClerkInformation += SCR_CMD_DELIMITER + m_pDevCmn->fstrSCR_GetStringFromTextID(T_OPERATOR_PASSWORD);
			}
			else if (m_OpInfo.nLoginMode == LOGIN_SERVICE)
			{
				// [#RWC6-56] US William 2019.12.26 Hash passwords
				strnClerkInformation += SCR_CMD_DELIMITER + m_pDevCmn->fstrSCR_GetStringFromTextID(T_OPERATOR_PASSWORD);
			}
			else
			{
				// [#RWC6-56] US William 2019.12.26 Hash passwords
				strnClerkInformation += SCR_CMD_DELIMITER + m_pDevCmn->fstrSCR_GetStringFromTextID(T_CURRENT_PASSWORD);
			}
			// end of [#651]
			break;

		case 727:												// Quick Configuration
		case 906:												// Clerk Service Password Procedure
//			strnClerkInformation = MemGetStr(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_SERVICEPW);
			// [#651] NH KSK 2010.09.07
			if (m_OpInfo.nLoginMode == LOGIN_MASTER)
			{
				// [#RWC6-56] US William 2019.12.26 Hash passwords
				strnClerkInformation += SCR_CMD_DELIMITER + m_pDevCmn->fstrSCR_GetStringFromTextID(T_SERVICE_PASSWORD);
			}
			else
			{
				// [#RWC6-56] US William 2019.12.26 Hash passwords
				strnClerkInformation += SCR_CMD_DELIMITER + m_pDevCmn->fstrSCR_GetStringFromTextID(T_CURRENT_PASSWORD);
			}
			// end of [#651]
			break;

		case 728:
			// 1. Dual Balance
#if (APP_DUALBALANCE && !APP_TDL_OPTION) // [#2482] US Justin 2017.05.23 Open Dual Balance to all customer.. Cardtronics => Under TDL Option
			strnClerkInformation.Format(L"%s%s", m_pDevCmn->fstrSCR_GetStringFromTextID(GET_ENDIS_APTEXTID(MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_CUSTOMIZED_DUALBALANCE))), SCR_CMD_DELIMITER);
#else
			strnClerkInformation = L"";
#endif

			// 2. Mastercard Cash
			szTemp.Format(L"%s%s", m_pDevCmn->fstrSCR_GetStringFromTextID(GET_ENDIS_APTEXTID(MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_PIN4_ENABLE))), SCR_CMD_DELIMITER);
			strnClerkInformation += szTemp;

			// 3. Surch Seg
